INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (437, 'Gwaerost', 'castle', 50, '', 'A castle in southwestern Anfalas held by House Maldring of Haerlond. Its stone towers overlook the coastal road; the surrounding estate grows grain and raises sheep on the wind-swept Anfalas plain. The castle is a working garrison and manor combined — practical rather than elegant, with a small garrison and the lord''s household sharing its walls.', 'Un castillo del suroeste de Anfalas en manos de la Casa Maldring de Haerlond. Sus torres de piedra dominan el camino de la costa; la hacienda que lo rodea cultiva cereal y cría ovejas en la llanura ventosa de Anfalas. El castillo es a la vez guarnición en servicio y casa señorial — práctico antes que elegante, con una guarnición pequeña y la casa del señor compartiendo sus muros.', '00e5f2d229a2edcf3766d67af82c63af', ST_GeomFromText('POINT(2.943926 40.441266)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (438, 'Rond Deren', 'manor', 15, '', 'A lordly manor tucked in the hills of northern Anfalas between Umb Estelwain and Rond Rhandir, in the County of Agarinna. Rond Deren is a stone manor house with attached farmsteads — a quiet, well-maintained estate of a minor Gondorian noble family who tend their lands and keep out of larger politics.', 'Una casa señorial recogida entre las colinas del norte de Anfalas, entre Umb Estelwain y Rond Rhandir, en el Condado de Agarinna. Rond Deren es un caserón de piedra con granjas anexas — una hacienda tranquila y bien mantenida, de una familia noble gondoriana menor que atiende sus tierras y se mantiene al margen de la política mayor.', '033f56d8b661b104d5a147e1a75be0b1', ST_GeomFromText('POINT(6.361441 43.005169)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (439, 'Tarmabar', 'keep', 82, '100% Dúnadan', 'Built by the Tarma family in T.A. 2.. A rural power base and summer retreat for the Lords of Tarma.. The Tarmas are second in power only to the King himself, and they have a history of insubordination against the throne.', 'Construido por la familia Tarma en la T.E. 2.. Base de poder rural y residencia de verano de los Señores de Tarma.. Los Tarma solo son superados en poder por el Rey mismo, y tienen un historial de insubordinación contra el trono.', '03d2ab1b44e07dd4eda050853c7d7a9e', ST_GeomFromText('POINT(-2.10898 52.659012)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (440, 'Barad Garan', 'ruins', 'Barad Garan stands as a ruin — towers toppled, walls breached — a shell of the fortress it once was. No garrison remains; wind moves through the open gateways and birds nest in the cracked stonework.', 'Barad Garan no es más que una ruina — torres derribadas, murallas abiertas — el cascarón de la fortaleza que fue. No queda guarnición; el viento pasa por los portales abiertos y los pájaros anidan en la piedra agrietada.', '04bc5a40947e50f0eaa4e0a86776c9d1', ST_GeomFromText('POINT(-2.068102 53.013253)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (441, 'Sunthra Unsar', 'city', 6000, 'Dunlendings', 'Originally built under the name Mistalonde, the city appeared in records from the mid-Second Age until T.A. 1503, when Gordaig of Saerlann captured and renamed it Sunthra Unsar. The rebuilt city became the seat of power of the Saerlannish (Dynion) clan, and its inhabitants were almost entirely hillmen.', 'Levantada en su origen con el nombre de Mistalonde, la ciudad aparece en los registros desde mediados de la Segunda Edad hasta la T.E. 1503, cuando Gordaig de Saerlann la tomó y la rebautizó Sunthra Unsar. La ciudad reconstruida se convirtió en el asiento del poder del clan saerlannés (Dynion), y sus habitantes eran casi por completo hombres de las colinas.', '04e3220ac767492d0a7e4a40af1cf5f7', ST_GeomFromText('POINT(-0.338526 47.295549)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (442, 'Eolburg', 'town', 220, 'Northmen', 'Buhr Ailgra is one of the few permanent colonies of the Eothraim, who follow the migratory movements of their flocks across the plains of Rhovanion. The village is a simple community with houses built of straw and peat, surrounded by a sturdy earthen fence.', 'Buhr Ailgra es una de las pocas colonias permanentes de los Eothraim, que siguen los movimientos migratorios de sus rebaños por las llanuras de Rhovanion. La aldea es una comunidad sencilla, de casas hechas de paja y turba, rodeada por una recia cerca de tierra.', '0573bacfdc7be405711b2229aac84155', ST_GeomFromText('POINT(22.190484 50.535117)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (443, 'Oatbarton', 'village', 200, '50% Harfoot, 40% Stoor, 10% Fallohide', 'Settled in T.A. 1625 by a family from Bree.. Agriculture.. The rural Hobbits of Oatbarton have a fair amount of contact with Men.', 'Poblada en la T.E. 1625 por una familia de Bree.. Agricultura.. Los hobbits rurales de Oatbarton tienen bastante contacto con los Hombres.', '05bfff19fd4ef4921a8ab483a9a1606e', ST_GeomFromText('POINT(-1.144238 51.970683)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (444, 'Tir Elena', 'town', 490, 'Gondor', 'A small Gondorian town of Anórien, on the northeastern eaves of Drúadan Forest — capital and seat of House Elenion, the local barons. Stone houses with tiled roofs line the road through the forest''s edge; the Drúadan Forest is just beyond the tree-line to the south. The Woses of the forest are never seen in town but their presence is always felt.', 'Un pequeño pueblo gondoriano de Anórien, en el linde nororiental del Bosque de Drúadan — capital y asiento de la Casa Elenion, los barones locales. Casas de piedra con techos de teja bordean el camino que pasa por el borde del bosque; el Bosque de Drúadan queda apenas más allá de la línea de árboles, al sur. A los woses del bosque no se los ve nunca en el pueblo, pero su presencia se siente siempre.', '06a832f049e40fd2956c67aafa4b97b4', ST_GeomFromText('POINT(17.042721 43.969903)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (445, 'Nornhabar', 'dwarven mine', 84, 'Dwarves', 'The dwarven population varied considerably, having reached its peak in the Second Age. It was mainly abandoned before the War of the Last Alliance and, although never completely deserted, was largely dilapidated by T.A. 1643.', 'La población enana varió considerablemente y alcanzó su máximo en la Segunda Edad. La mina fue abandonada en buena parte antes de la Guerra de la Última Alianza y, aunque nunca quedó del todo desierta, hacia la T.E. 1643 estaba muy deteriorada.', '0780dc18f26046f385079adf790b14cb', ST_GeomFromText('POINT(-6.24766 50.463435)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (446, 'Balost', 'fortress', 132, '60% Dunman/Eriadoran, 35% Cardolani, 5% Dúnadan', 'Completed in T.A. 923 by Hir Girithlin.. A base for administration of rural estates; a strategic strong point in Gwathló valley between Tharbad and Saralainn.. Balost is a sturdy castle which withstood many attacks from without.', 'Terminado en la T.E. 923 por Hir Girithlin.. Base para la administración de las haciendas rurales; punto fuerte estratégico en el valle del Gwathló, entre Tharbad y Saralainn.. Balost es un castillo recio que resistió muchos ataques desde fuera.', '095f5496d06b45426748380218dd28bc', ST_GeomFromText('POINT(0.84075 48.028125)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (447, 'Lindabad', 'manor', 20, '', '097732fb0cf5be220774f197e7b5e939', ST_GeomFromText('POINT(3.339786 42.953196)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (448, 'Hwarin', 'village', 100, '', 'A small coastal village in Rast Rhaen, a sheltered garth on the central Andrast coast. Its few stone houses and fishing boats sit in a protected cove; the people are Dunir fisher-folk who live by the sea and avoid the attention of passing ships.', 'Una pequeña aldea costera de Rast Rhaen, un garth abrigado en la costa central de Andrast. Sus pocas casas de piedra y sus botes de pesca ocupan una cala protegida; la gente son pescadores dunir que viven del mar y evitan llamar la atención de los barcos que pasan.', '09ebe7fb2ead8fce2e13bcb494347b54', ST_GeomFromText('POINT(1.579458 39.692717)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (449, 'Frogmorton', 'village', 230, '60% Harfoot, 30% Fallohide, 10% Stoor', 'Frogmorton is a comfortable Hobbit village on the Great East Road in the Eastfarthing, its central position on the road making it a natural stopping point for travellers crossing the Shire. The local farmers bring their produce to market here on regular days; a decent inn serves the road traffic. The surrounding land is well-farmed and peaceful, typical of the Eastfarthing''s prosperous character.', 'Frogmorton es una aldea hobbit acomodada sobre el Gran Camino del Este, en la Cuaderna del Este; su posición central en el camino la vuelve una parada natural para quien atraviesa la Comarca. Los granjeros de los alrededores traen aquí sus productos al mercado en días fijos, y una posada decente atiende el tránsito del camino. La tierra que la rodea está bien trabajada y es apacible, como corresponde al carácter próspero de la Cuaderna del Este.', '0a4b4faabc031f6513c920b1a7889659', ST_GeomFromText('POINT(-0.546626 51.552754)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (450, 'Cair Andros', 'fortress', 560, 'Gondor', 'Cair Andros (S. Ship of Long Foam) was an island fortress on the River Anduin, roughly forty miles north of Osgiliath. Shaped like a great ship with a high rocky prow pointing north, it was fortified by Steward Túrin II to protect Anórien from enemy crossings. It served as a vital northern bulwark of Gondor against Mordor throughout the late Third Age.', 'Cair Andros (S. Nave de la Espuma Larga) era una fortaleza isleña en el río Anduin, unas cuarenta millas al norte de Osgiliath. Con forma de gran navío, con una proa rocosa y alta apuntando al norte, fue fortificada por el Senescal Túrin II para proteger Anórien de los cruces enemigos. Sirvió como baluarte septentrional decisivo de Gondor frente a Mordor durante toda la última parte de la Tercera Edad.', '0ad87f9426e41d0331a292db56e11def', ST_GeomFromText('POINT(17.804309 44.121168)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (451, 'Beldwin', 'castle', 475, '60% Dunman, 40% Dúnadan', 'Beldwin is a Dúnadan castle and its surrounding settlement in the northern Westmarch, just south of the River Isen near an ancient stone bridge. It serves as the administrative base for this corner of the region and maintains a garrison that keeps order among the mixed Dunman and Dúnadan population. The castle is solid and well-maintained; the bridge beside it carries considerable traffic between the Westmarch and the lands to the north.', 'Beldwin es un castillo dúnadan y el asentamiento que lo rodea, en el norte de la Marca del Oeste, justo al sur del río Isen y cerca de un antiguo puente de piedra. Funciona como base administrativa de este rincón de la región y mantiene una guarnición que conserva el orden entre la población mixta de dunlendinos y dúnedain. El castillo es sólido y está bien mantenido; el puente que tiene al lado soporta un tránsito considerable entre la Marca del Oeste y las tierras del norte.', '0b2e6a36edcefc06e5f110a065fd8a4b', ST_GeomFromText('POINT(6.583805 46.066796)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (452, 'Minas Thonfalon', 'ruins', 0, 'N/A', 'Minas Thonfalon is a ruined Arnorian watchtower on the ''Bog Coast'' of the Rast Vorn, built in T.A. 503 to watch traffic along the coast. Its foundations are slowly sinking into the waterlogged ground; the upper courses have already tumbled into the bog. On foggy days the broken tower is barely visible above the reed-beds, and local fishermen give it a wide berth.', 'Minas Thonfalon es una torre de vigilancia arnoriana en ruinas, en la ''Costa del Pantano'' de Rast Vorn, construida en la T.E. 503 para vigilar el tránsito a lo largo de la costa. Sus cimientos se hunden poco a poco en el terreno encharcado; las hiladas superiores ya se han derrumbado en la ciénaga. En los días de niebla la torre partida apenas se distingue por encima de los juncales, y los pescadores del lugar le pasan bien lejos.', '0d1123b21ecdf4915a1414dfbdc79bd8', ST_GeomFromText('POINT(-3.694613 47.422739)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (453, 'Annúminas', 'ruins', 0, 'N/A', 'Founded in 3396 by the High-king Elendil.. Royal seat of Arnor; locus of a Palantír; after T.A. 861 the capital of Arthedain.. Annúminas was the home of Arthedain''s Kings before the city was sacked in 1409, when the hordes of the Witch-king overran all the former lands of Arnor. Annúminas once held the position of the fairest of Dúnadan cities in the North, with broad, tree-lined avenues and graceful buildings of white marble. No wall surrounded the city, which was deemed a place of peace and learning. Scavengers have picked most of the ruins clean, but tales abound of sealed vaults underneath the library and the palace.', 'Fundada en el 3396 por el Rey Supremo Elendil.. Sede real de Arnor; lugar de un palantír; capital de Arthedain después de la T.E. 861.. Annúminas fue el hogar de los Reyes de Arthedain hasta que la ciudad fue saqueada en el 1409, cuando las hordas del Rey Brujo invadieron todas las antiguas tierras de Arnor. Annúminas tuvo en su momento el lugar de la más hermosa de las ciudades dúnedain del Norte, con avenidas anchas y arboladas y edificios gráciles de mármol blanco. Ninguna muralla rodeaba la ciudad, tenida por un lugar de paz y estudio. Los saqueadores han dejado casi limpias las ruinas, pero abundan los relatos sobre bóvedas selladas bajo la biblioteca y el palacio.', '0d8e3b9e2948db2be16c2f4956546265', ST_GeomFromText('POINT(-0.848949 53.010855)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (454, 'Cathiel', 'ruins', '', 'Ruined city. Cathiel was a settlement of Ethir Gwathló in Cardolan, about seventy-five miles inland from the mouths of the Gwathló. It had a population of roughly 4,000 in T.A. 250, declining through the Third Age and finally abandoned by T.A. 1640.', 'Ciudad en ruinas. Cathiel era un asentamiento de Ethir Gwathló, en Cardolan, unas setenta y cinco millas tierra adentro desde las bocas del Gwathló. Tenía una población de unos 4.000 habitantes en la T.E. 250, que fue decayendo a lo largo de la Tercera Edad hasta quedar abandonada hacia la T.E. 1640.', '0df0970789f98c362a31cfadb2b83153', ST_GeomFromText('POINT(-2.236776 47.126324)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (455, 'Haerlond', 'point of interest', '', 'A small harbour village in Andrast, its modest dock serving ships damaged rounding the dangerous cape. Beneath the village''s timber houses lie the buried ruins of an older Númenórean settlement, visible when the ground shifts. Sailors know Haerlond as a last refuge before the open sea; the villagers are skilled at patching hulls and provisioning vessels.', 'Una pequeña aldea portuaria de Andrast, cuyo modesto muelle atiende a los barcos averiados al doblar el cabo peligroso. Bajo las casas de madera de la aldea yacen las ruinas enterradas de un asentamiento numenóreano más antiguo, visibles cuando el terreno se mueve. Los marinos conocen Haerlond como último refugio antes del mar abierto; los aldeanos tienen mano para remendar cascos y aprovisionar naves.', '0fefd0115eb8dc430522a1ee0368e24e', ST_GeomFromText('POINT(1.892833 40.529686)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (456, 'Calembel', 'fortified town', 1100, '100% Gondorian', 'Settled by Númenóreans in late Second Age, granted charter by Ostoher of Gondor in T.A. 488.. Provisioning the mining communities in the Ered Nimrais; seat for the Lord Protector of Lamedon.. Calembel is on the road which links central Gondor to the mining communities of the southern White Mountains.', 'Poblada por numenóreanos a fines de la Segunda Edad; recibió fuero de Ostoher de Gondor en la T.E. 488.. Aprovisionamiento de las comunidades mineras de las Ered Nimrais; asiento del Señor Protector de Lamedon.. Calembel está sobre el camino que une el centro de Gondor con las comunidades mineras del sur de las Montañas Blancas.', '125192817421a689c47d02e86b8e7513', ST_GeomFromText('POINT(11.577131 43.689014)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (457, 'Bree', 'town', 410, '45% Stoor Hobbit, 50% Bree-man, 5% Dúnadan', 'Settled by migrating Dunmen in the early Second Age.. Collecting point for the products of surrounding farms; trading center due to its location at the junction of the Greenway and the Great East Road.. Bree is the largest town in Bree-land, a region of Arthedain that is peaceful, agricultural, and largely autonomous. The town is built around a large hill and is protected by a formidable dike surmounted by a thick hedge. Numerous smials, or Hobbit-holes, can be found in the flanks of Bree-hill. Both Men and Hobbits live in Bree, making it one of the few locations in Middle-earth where co-operation between folk of different races occurs. Due to its central location, Bree witnesses many strange folk passing through its streets, and the town is a perfect place to acquire or sell information.', 'Poblada por dunlendinos migrantes a comienzos de la Segunda Edad.. Punto de acopio de los productos de las granjas vecinas; centro de comercio por su ubicación en el cruce del Camino Verde y el Gran Camino del Este.. Bree es el pueblo más grande de las Tierras de Bree, una región de Arthedain apacible, agrícola y en buena medida autónoma. El pueblo está construido alrededor de una gran colina y lo protege un dique formidable coronado por un seto espeso. En las laderas de la Colina de Bree se encuentran numerosos smials, o agujeros-hobbit. En Bree viven tanto Hombres como hobbits, lo que la vuelve uno de los pocos lugares de la Tierra Media donde hay cooperación entre pueblos de razas distintas. Por su posición central, Bree ve pasar por sus calles mucha gente extraña, y el pueblo es un sitio perfecto para conseguir o vender información.', '12861aa0bb58c19dd55228f70e240f6b', ST_GeomFromText('POINT(1.228323 51.560255)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (458, 'Greenholm', 'town', 310, 'Humans, Hobbits, Silvan Elves', 'A quiet outpost in the middle Third Age, home to a few Arthadan families coexisting with nearby Elves who observed the comings and goings of mortals on behalf of the lords of the Grey Havens. One of the Elves, Sinda Calenlinn, was an expert herbalist fond of fermented grains.', 'Un puesto tranquilo de mediados de la Tercera Edad, hogar de unas pocas familias arthedanas que convivían con los Elfos de las cercanías, encargados de observar las idas y venidas de los mortales por cuenta de los señores de los Puertos Grises. Uno de esos Elfos, el sinda Calenlinn, era un herbolario experto y aficionado a los granos fermentados.', '13328700f334769383730b40c93d2add', ST_GeomFromText('POINT(-3.382751 51.39257)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (459, 'Enerond', 'ruins', 5, '', 'Ruined city. Enerond was a township of Brethyar in Arthedain, on the east bank of the Lune River. It had a population of about 5,100 in T.A. 250, declining through the Third Age until abandoned before its end.', 'Ciudad en ruinas. Enerond era un municipio de Brethyar, en Arthedain, sobre la orilla oriental del río Lhûn. Tenía unos 5.100 habitantes en la T.E. 250, que fueron decayendo a lo largo de la Tercera Edad hasta su abandono antes del fin de la Edad.', '1529023a68b193b8bf5fbe78196b3d6e', ST_GeomFromText('POINT(-1.237397 52.950469)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (460, 'Lomost', 'fortress', 120, 'Gondor', 'Along with its sister fortress of Aerost, Lómost (''Echo Fortress'') is one of two critical coastal beacons defending Anfalas against Corsair raids. Built in T.A. 1634 after the Great Raid on Pelargir, it stands on the western Anfalas coast and can relay news of approaching enemies to Lond Galen or Annon Drúin within hours via its beacon tower. The fortress is a solid coastal structure of dark stone, battered by sea-wind; the garrison here is small but alert.', 'Junto con su fortaleza hermana de Aerost, Lómost (''Fortaleza del Eco'') es una de las dos almenaras costeras decisivas para la defensa de Anfalas frente a las incursiones de los Corsarios. Construida en la T.E. 1634, después de la Gran Incursión sobre Pelargir, se alza en la costa occidental de Anfalas y puede transmitir noticia de un enemigo que se acerque a Lond Galen o a Annon Drúin en pocas horas por medio de su torre de fuego. La fortaleza es una construcción costera sólida, de piedra oscura, castigada por el viento del mar; la guarnición es pequeña pero está atenta.', '1534c928808a039095dd49e5eb3d37b9', ST_GeomFromText('POINT(3.325376 40.91388)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (461, 'Ethring', 'fortified town', 1300, '95% Gondorian, 5% Dunnish', 'Settled by Gondorians in the late Second Age, granted a royal charter in T.A. 180.. A market town serving most agricultural and mining communities of Lamedon.. Ethring profits from the traffic along the Gondor Road.', 'Poblada por gondorianos a fines de la Segunda Edad; recibió fuero real en la T.E. 180.. Pueblo de mercado que atiende a casi todas las comunidades agrícolas y mineras de Lamedon.. Ethring se beneficia del tránsito por el Camino de Gondor.', '155d4c11e6dc874f9b09cb0dd0f37f1b', ST_GeomFromText('POINT(12.41734 43.320786)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (462, 'Fornost Erain', 'fortified city', 3100, '95% Dúnadan, 5% Mixed Mannish', 'Fornost Erain — the ''Fortress of the Kings'' — crowns a steep rise on the southern slopes of the North Downs, capital of Arthedain. It is as much fortress as city: concentric rings of stone walls enclose the royal palace, the great library, and the merchant quarters of the Dúnedain. The city''s streets are orderly and well-paved; the men who walk them are tall and grave-faced, with the bearing of a people who know themselves to be heirs of Númenór. Beyond the walls, the North Downs roll away in all directions.', 'Fornost Erain — la ''Fortaleza de los Reyes'' — corona una loma empinada en las laderas meridionales de las Quebradas del Norte, capital de Arthedain. Es tanto fortaleza como ciudad: anillos concéntricos de murallas de piedra encierran el palacio real, la gran biblioteca y los barrios de mercaderes de los dúnedain. Las calles son ordenadas y están bien empedradas; los hombres que las caminan son altos y de rostro grave, con el porte de un pueblo que se sabe heredero de Númenor. Más allá de las murallas, las Quebradas del Norte se extienden en todas direcciones.', '15ba230084a51abb21a6873b76a635a0', ST_GeomFromText('POINT(1.475915 53.015801)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (463, 'Galenros', 'point of interest', '', 'A tiny Elvish hamlet south of the spur of the Forered Luin — fifteen households of 41 Elves in total, a mixture of various kindreds. It was founded in the Second Age as a communal retreat by High Elven philosophers, artists and nature-lovers who sought refuge from the bustle of Mithlond. The settlement answers to Tawarobel for governance. A visitor finds a handful of delicate timber-and-stone houses half-hidden among the trees, connected by winding paths — an air of quietude and careful order marks everything here.', 'Una diminuta aldea élfica al sur del espolón de Forered Luin — quince casas, cuarenta y un Elfos en total, de linajes diversos. Fue fundada en la Segunda Edad como retiro comunal por filósofos, artistas y amantes de la naturaleza de los Altos Elfos que buscaban apartarse del bullicio de Mithlond. Para su gobierno responde a Tawarobel. El visitante encuentra un puñado de casas delicadas de madera y piedra, medio ocultas entre los árboles y unidas por senderos sinuosos — un aire de quietud y de orden cuidadoso marca todo el lugar.', '1691e47321554c359e67eaa3f4b72b85', ST_GeomFromText('POINT(-6.386798 53.375535)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (464, 'Harlond', 'town', 500, '100% Gondorian', 'Settled soon after founding of Minas Anor, circa S.A. 3320.. The port for Minas Anor; oversees river traffic on Anduin.. Harlond is a busy town, handling almost all of the freight from southern Gondor bound for the lands of Calenardhon and Rhovanion.', 'Poblada poco después de la fundación de Minas Anor, hacia la S.E. 3320.. El puerto de Minas Anor; supervisa el tránsito fluvial del Anduin.. Harlond es un pueblo activo, que maneja casi toda la carga del sur de Gondor destinada a las tierras de Calenardhon y Rhovanion.', '16cbb3fddb6eb25580cda7bcfc7f71e9', ST_GeomFromText('POINT(-8.135416 50.782548)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (465, 'Eithel Thurin', 'town', 620, '40% Gondorian, 60% Haradan', 'Eithel Thurin is a Gondorian garrison-town in Harondor, founded by the army in T.A. 932 to extend Gondor''s control over this contested coastal region. It serves as a trading centre for coastal traffic and the main base for Gondorian authority between the Poros and Harnen rivers. The town is frequently raided by Umbar and hostile Haradrim; its walls have been repaired many times, and the population has a watchful, embattled quality.', 'Eithel Thurin es un pueblo-guarnición gondoriano de Harondor, fundado por el ejército en la T.E. 932 para extender el control de Gondor sobre esta disputada región costera. Funciona como centro de comercio del tránsito de cabotaje y como base principal de la autoridad gondoriana entre los ríos Poros y Harnen. El pueblo sufre incursiones frecuentes de Umbar y de los haradrim hostiles; sus murallas se han reparado muchas veces, y su población tiene algo de vigilante y de sitiada.', '1978c4880d101efe741d9f6709199d4f', ST_GeomFromText('POINT(13.750343 39.180084)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (466, 'Minas Arthor', 'city', 5000, 'Gondor', 'Minas Arthor, once the capital of Arnach, was situated at the crossings of the Erui, where a settlement had existed since the earliest chronicles. Founded at the beginning of the Third Age, it grew into the center of a prosperous agricultural district.', 'Minas Arthor, antaño capital de Arnach, se alzaba en los vados del Erui, donde había habido un asentamiento desde las crónicas más antiguas. Fundada a comienzos de la Tercera Edad, creció hasta ser el centro de un distrito agrícola próspero.', '19f01cb59625b48166dd6ffef0991750', ST_GeomFromText('POINT(16.769285 42.493854)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (467, 'Lond Rhaen', 'village', 120, '', 'A small fishing village on the northwestern coast of Andrast, sheltered in a safe bay of Rast Rhaen. A handful of stone-walled houses face the water; the people here are Dunir fisher-folk whose boats rarely venture far from the bay''s protection.', 'Una pequeña aldea de pescadores en la costa noroccidental de Andrast, abrigada en una bahía segura de Rast Rhaen. Un puñado de casas con muros de piedra da al agua; la gente de aquí son pescadores dunir cuyos botes rara vez se aventuran lejos del amparo de la bahía.', '1a056b5e31d35c42e643f9f716ee1b84', ST_GeomFromText('POINT(0.966925 39.862769)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (468, 'Mirimar', 'city', 560, '', '1a43bb9d28424d1c7a09348ba2f53e46', ST_GeomFromText('POINT(-10.308741 52.60319)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (469, 'Bar Astirian', 'manor', 20, '', 'Astorion Manor (S. Bâr Astorion) was the former home of House Astorion, a noble Gondorian family. It was situated on the outskirts of the Entwash Mouths, north of Min-Rimmon, where the family held extensive lands.', 'La Casa Astorion (S. Bâr Astorion) fue el antiguo hogar de la Casa Astorion, una familia noble gondoriana. Se hallaba en las afueras de las Bocas del Entaguas, al norte de Min-Rimmon, donde la familia tenía tierras extensas.', '1c4692f658908ed6ebfc090f4b3ab0a5', ST_GeomFromText('POINT(14.603374 45.026475)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (470, 'Ossarnen', 'fortified town', 1400, '85% Gondorian, 15% Dunnish', 'Ossarnen is a Gondorian mining town in the White Mountains, established in the Second Age and grown since. Its population works the mineral seams of the surrounding mountains; the settlement sits well off the main road, connected to it by a rough track. Stone houses and mine-head structures crowd the narrow valley floor; the sound of picks and hammers carries far in the clear mountain air.', 'Ossarnen es un pueblo minero gondoriano de las Montañas Blancas, establecido en la Segunda Edad y crecido desde entonces. Su población trabaja los filones minerales de las montañas vecinas; el asentamiento queda bien apartado del camino principal, unido a él por una senda tosca. Las casas de piedra y las bocaminas se apiñan en el fondo estrecho del valle; el sonido de los picos y los martillos llega lejos en el aire claro de la montaña.', '212b1c186141ab63909ccb43e5d88c00', ST_GeomFromText('POINT(11.391809 44.11232)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (471, 'Gram', 'dwarven mine', 1000, 'Orcs', 'The Witch-King''s servants erected this mountain fortress on the southern branch of the Misty Mountains forming the boundary of Nan Angmar. Gram was the most formidable Orc stronghold west of the mountains; no man had ever escaped its depths to give a coherent account of its interior.', 'Los siervos del Rey Brujo erigieron esta fortaleza de montaña en el ramal meridional de las Montañas Nubladas que forma el límite de Nan Angmar. Gram era la plaza fuerte orca más formidable al oeste de las montañas; ningún hombre había escapado nunca de sus profundidades para dar una relación coherente de su interior.', '221d7d6f3912b1b81ab7b3186ce88fb3', ST_GeomFromText('POINT(7.71789 54.443782)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (472, 'Imladris', 'manor', 125, 'Mixed Elvish', 'Founded by Elrond Half-elven in S.A. 1697.. A haven for healing, learning, and the arts.. The house of Elrond Half-elven is located in a narrow ravine, not easily found in the broken lands of fallen Rhudaur.', 'Fundada por Elrond Medio Elfo en la S.E. 1697.. Refugio de curación, estudio y artes.. La casa de Elrond Medio Elfo se encuentra en un barranco angosto, no fácil de hallar en las tierras quebradas del caído Rhudaur.', '223f370e8996d2b428a5d4e5d6c21035', ST_GeomFromText('POINT(9.871206 51.52831)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (473, 'Tharbad', 'fortified town', 21345, '60% Cardolani, 20% Dunnish, 10% Northman, 5% Eriadoran, 5% Other Mannish', 'A Númenórean river port dating to the mid-Second Age.. A major urban hub; the effective administrative center of Cardolan; an outpost of Gondorian authority.. Since the fall of King Ostoher in T.A. 1410, the former Númenórean port of Tharbad has declined from the glory it held in ages past.', 'Un puerto fluvial numenóreano que data de mediados de la Segunda Edad.. Un gran centro urbano; el centro administrativo efectivo de Cardolan; un puesto de la autoridad gondoriana.. Desde la caída del rey Ostoher en la T.E. 1410, el antiguo puerto numenóreano de Tharbad ha decaído de la gloria que tuvo en otras edades.', '22fe3e29220c0d9a82bfb2680d8b854a', ST_GeomFromText('POINT(3.094174 48.841242)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (474, 'Minas Ongoth', 'ruins', '', 'Minas Ongoth stands in ruin on its hilltop, its towers broken and its gates long rotted away. The site commands a good view of the surrounding country, which is probably why it was built here; now only the wind occupies it.', 'Minas Ongoth está en ruinas sobre su cerro, con las torres partidas y las puertas podridas hace mucho. El sitio domina una buena vista de la comarca circundante, que es probablemente la razón por la que se construyó aquí; ahora solo lo ocupa el viento.', '235269a8e1723e126b7887d29c4fd341', ST_GeomFromText('POINT(-2.005377 54.129843)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (475, 'Bar Engui', 'village', 60, '', 'A small hamlet on the river Engui in Andrast, one of the most remote corners of Gondor. A handful of stone-walled garths cluster near the river; the people here are Dunir fishermen and small farmers who seldom see strangers.', 'Un caserío pequeño sobre el río Engui, en Andrast, uno de los rincones más remotos de Gondor. Un puñado de garths con muros de piedra se agrupa cerca del río; la gente de aquí son pescadores y pequeños agricultores dunir que rara vez ven forasteros.', '23a6ef21a52eb11823391f20df3fc5a7', ST_GeomFromText('POINT(-0.162456 40.376272)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (476, 'Athrad Poros', 'town', 450, '', 'The ford settlement of Athrad Poros was an important stop on the land trade route south. It began as a military garrison protecting the border between the nascent Kingdom-in-Exile and the Umbarean sphere of influence. When the Harnen Corridor opened, Athrad Poros became a critical juncture for trade with Near Harad and Khand.', 'El asentamiento del vado de Athrad Poros era una parada importante en la ruta comercial terrestre hacia el sur. Empezó como guarnición militar para proteger la frontera entre el naciente Reino en el Exilio y la esfera de influencia de Umbar. Cuando se abrió el Corredor del Harnen, Athrad Poros pasó a ser un cruce decisivo para el comercio con el Harad Cercano y Khand.', '25d3ae62f10cbc7919506ae65fd7dd2c', ST_GeomFromText('POINT(18.127267 40.357852)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (477, 'Rood', 'village', 280, '70% Dúnadan, 30% Mixed Mannish', 'Grew around Baranduin river traffic in early Third Age.. A collecting point for area farms; a shipping station for freight on Baranduin.. With the sack of Annúminas, Rood began to fall into a decline, becoming a den for thieves and bandits.', 'Creció alrededor del tránsito fluvial del Baranduin a comienzos de la Tercera Edad.. Punto de acopio de las granjas de la zona; estación de embarque de carga en el Baranduin.. Con el saqueo de Annúminas, Rood empezó a decaer y se volvió una guarida de ladrones y bandidos.', '28a90db52bc32e64d25b3ba266dd7c80', ST_GeomFromText('POINT(0.44034 52.870134)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (478, 'Fangoth', 'ruins', '', 'Fangoth is a ruin now, its walls toppled and its streets empty. Once a city of some standing, it was abandoned after the troubles that plagued this region in the middle Third Age. Only broken archways and the outlines of old streets remain visible beneath the weeds.', 'Fangoth es hoy una ruina, con las murallas derribadas y las calles vacías. Fue en su momento una ciudad de cierta importancia; quedó abandonada después de los problemas que asolaron esta región a mediados de la Tercera Edad. Solo se distinguen todavía arcos partidos y el trazado de las calles viejas bajo la maleza.', '2ac39eaf2604ce7c7b5058e778f63624', ST_GeomFromText('POINT(0.92569 48.750512)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (479, 'Minas Tirith', 'fortified city', 25000, 'Gondor', 'Originally called Minas Anor (S. Tower of the Sun), Minas Tirith was built at the foot of Mount Mindolluin in the Ered Nimrais. The city rose in seven concentric tiers of white stone, each gate offset from the last, and the White Tower housed the last Palantír in Gondor''s keeping. Together with Osgiliath and Minas Ithil, it formed the core of Gondor.', 'Llamada en su origen Minas Anor (S. Torre del Sol), Minas Tirith fue construida al pie del Monte Mindolluin, en las Ered Nimrais. La ciudad se levantaba en siete niveles concéntricos de piedra blanca, con cada puerta desplazada respecto de la anterior, y la Torre Blanca albergaba el último palantír en poder de Gondor. Junto con Osgiliath y Minas Ithil formaba el núcleo de Gondor.', '2c1d9a8d2a5d1ab62942438dfd375a62', ST_GeomFromText('POINT(17.422569 43.158864)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (480, 'Tir Feren', 'castle', 80, 'Gondor', 'A Gondorian castle overlooking Parth Feren in the westernmost Pinnath Gelin. Built of local stone, it commands the beechwood hills that give it its name (''Beech-ward''). A small garrison and the lord''s household maintain the castle; the surrounding parkland of old beeches is peaceful in summer but exposed to the sea-wind in winter.', 'Un castillo gondoriano que domina Parth Feren, en el extremo occidental de Pinnath Gelin. Construido con piedra del lugar, vigila las colinas de hayas que le dan su nombre (''Guarda de las Hayas''). Una guarnición pequeña y la casa del señor mantienen el castillo; el parque de hayas viejas que lo rodea es apacible en verano, pero queda expuesto al viento del mar en invierno.', '2ca07fa0e4327709a553cdaef455adce', ST_GeomFromText('POINT(2.740454 41.548916)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (481, 'Car Gaul', 'manor', 30, '', 'A freehold estate in the County of Nan Lefnui, on the lower Lefnui. It is the property of the Bannor family, who farm the surrounding fields and pastures of this remote corner of Gondor''s western frontier. The manor house is a solid stone farmstead with a small courtyard and stableyard.', 'Una hacienda libre en el Condado de Nan Lefnui, sobre el curso bajo del Lefnui. Es propiedad de la familia Bannor, que cultiva los campos y pastos de este rincón remoto de la frontera occidental de Gondor. La casa señorial es una granja sólida de piedra, con un patio y un corral de establos pequeños.', '2cfbecb372b043aee8f642cd6a7b86ed', ST_GeomFromText('POINT(1.549864 42.010386)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (482, 'Mithlond', 'city', 2200, '50% Silvan Elvish, 40% Sinda, 10% Noldo', 'Mithlond — the Grey Havens — comprises two harbours at the end of the Gulf of Lhûn: Mithannúnlond on the west shore and Mithrónalond on the east. Founded by Círdan after the drowning of Beleriand, it is the principal Elvish settlement in the west of Middle-earth, a place of shipbuilding and of departure for those sailing to the Undying Lands. Its stone quays are graceful and always busy with some quiet Elvish industry; tall ships lie at anchor in the fjord, their white sails furled.', 'Mithlond — los Puertos Grises — comprende dos puertos en el extremo del Golfo de Lhûn: Mithannúnlond en la orilla occidental y Mithrónalond en la oriental. Fundado por Círdan después del hundimiento de Beleriand, es el principal asentamiento élfico del occidente de la Tierra Media, un lugar de construcción de naves y de partida para quienes navegan hacia las Tierras Imperecederas. Sus muelles de piedra son gráciles y siempre hay en ellos alguna labor élfica callada; naves altas están fondeadas en el fiordo, con las velas blancas recogidas.', '2d63757ee0677b0d14e6ef15cf80e497', ST_GeomFromText('POINT(-5.813533 51.636483)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (483, 'Linhir', 'city', 4100, '95% Gondorian, 5% Mixed Mannish', 'Founded by Anárion in S.A. 3421.. A port and center for trade and manufacturing, situated at the point where the Gondor Road crosses the Gilrain.. Linhir is prosperous and busy, and a large population of unseemly characters has grown to prey upon the weak and gullible.', 'Fundada por Anárion en la S.E. 3421.. Puerto y centro de comercio y manufactura, situado donde el Camino de Gondor cruza el Gilrain.. Linhir es próspera y concurrida, y ha crecido en ella una población numerosa de gente de mal vivir que se aprovecha de los débiles y los incautos.', '2f80c0f3f97fa5120648aac455745217', ST_GeomFromText('POINT(13.13929 41.259747)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (484, 'Bar-i-Dinuviel', 'point of interest', 244, 'Noldor', 'Bar-i-Dinuviel (S. Home of the Nightingale; Os. Mbar Tinduvela) was a fishing village on the coast of Dor Tinuviel.', 'Bar-i-Dinuviel (S. Hogar del Ruiseñor; Os. Mbar Tinduvela) era una aldea de pescadores en la costa de Dor Tinuviel.', '2fb7c7e28436f4bd9c61816182aed529', ST_GeomFromText('POINT(-7.395721 48.731791)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (485, 'Edoras', 'city', 1600, 'Rohirrim', 'Edoras (R. The Courts) was the capital of Rohan, built upon an ancient hill site at the northern edge of the White Mountains. The great hall Meduseld crowned the hill, and the kings of the Mark were buried in twin rows of barrows outside the main gate. The surrounding treeless plains gave its lookouts a commanding view of all approaches.', 'Edoras (R. Las Cortes) fue la capital de Rohan, construida sobre un antiguo emplazamiento en una colina, en el borde norte de las Montañas Blancas. El gran salón de Meduseld coronaba la colina, y los reyes de la Marca eran sepultados en dos filas de túmulos frente a la puerta principal. Las llanuras sin árboles de alrededor daban a sus vigías una vista dominante de todos los accesos.', '3111faba40b284fcb721cbdcf31ac234', ST_GeomFromText('POINT(9.385098 45.345745)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (486, 'Firaen', 'ruins', '', 'Firaen is a ghost of a settlement — crumbling walls, collapsed rooftops, and silence. Whatever community lived here was driven away or died out long ago, and nature has been slowly reclaiming the stone ever since.', 'Firaen es el fantasma de un asentamiento — muros que se desmoronan, techos hundidos y silencio. La comunidad que vivió aquí fue expulsada o se extinguió hace mucho, y desde entonces la naturaleza viene recuperando lentamente la piedra.', '3176e8d194093b2c5dc2ae99f1343b86', ST_GeomFromText('POINT(-3.695985 53.387085)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (487, 'Litash', 'town', 3400, '95% Angmarean (Mixed Mannish), 5% Orc', 'Litash guards the eastern approaches to Angmar from its position at the mountain''s foot, garrisoned by a large force of the Witch-king''s mixed Mannish troops. A training centre for priests of the Dark Religion and a base for tax-collection in eastern Angmar, it is a grim town of barracks and ritual halls. The priests who walk its streets wear dark robes; the ordinary soldiers are rough and watchful. Travellers approaching from the east are stopped and questioned before being allowed to pass.', 'Litash guarda los accesos orientales de Angmar desde su posición al pie de la montaña, con una guarnición numerosa de las tropas humanas mixtas del Rey Brujo. Centro de instrucción de los sacerdotes de la Religión Oscura y base de recaudación de tributos en el este de Angmar, es un pueblo sombrío de cuarteles y salas rituales. Los sacerdotes que caminan sus calles visten túnicas oscuras; los soldados rasos son bastos y desconfiados. A los viajeros que llegan desde el este se los detiene y se los interroga antes de dejarlos pasar.', '31a29acf8ccc956ecf4321750e626859', ST_GeomFromText('POINT(9.489663 54.634588)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (488, 'Lond Daer', 'ruins', 0, 'N/A', 'Established as a colony of Númenor by Aldarion in the ninth century of the Second Age.. A Númenórean haven on the shores of Endor.. Lond Daer was ruined by a cataclysmic tidal wave in S.A. 3319.', 'Establecido como colonia de Númenor por Aldarion en el siglo noveno de la Segunda Edad.. Un puerto numenóreano en las costas de Endor.. Lond Daer fue arrasado por una ola cataclísmica en la S.E. 3319.', '32ec88080dbad7aa7fa3312e02d2fd8e', ST_GeomFromText('POINT(-0.911886 46.925789)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (489, 'Himihiril', 'castle', 50, 'Gondor', '330a8f4cdc4243eab59df18dc11bc301', ST_GeomFromText('POINT(-3.212527 54.57971)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (490, 'Woodmen Village', 'town', 200, 'Woodmen', 'A small village of the Woodmen in the Upper Anduin Vales, partially built on large platforms in the trees in the Elven fashion, reflecting the friendly relations between the Woodmen and the nearby Wood-Elves.', 'Una pequeña aldea de los Hombres de los Bosques en los Valles del Alto Anduin, construida en parte sobre grandes plataformas en los árboles, a la manera élfica, lo que refleja las relaciones amistosas entre los Hombres de los Bosques y los Elfos Silvanos vecinos.', '33776f6e655140f9d3dcf37a1f809675', ST_GeomFromText('POINT(16.365852 51.231894)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (491, 'Turonost', 'city', 890, 'Noldor', '364708d6d5fa3c5222b7232ac0755ec8', ST_GeomFromText('POINT(-11.932362 55.033719)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (492, 'Arailt', 'fortress', 120, 'Dunlendings', 'Arailt Hold was the ancient seat of the Dunlending Arailt clan. By the time of the War of the Ring it had long been abandoned; the Rohirrim had established a scouting camp above the ruins and nearby caves.', 'El Refugio de Arailt fue el antiguo asiento del clan dunlendino Arailt. Para la época de la Guerra del Anillo estaba abandonado desde hacía mucho; los rohirrim habían establecido un campamento de exploradores sobre las ruinas y las cuevas cercanas.', '39a1fb6f2b80d2adcf19c573d6e18ad2', ST_GeomFromText('POINT(6.432063 47.021704)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (493, 'Cerin Amroth', 'keep', 40, '15% Sinda, 85% Silvan', 'Cerin Amroth is a grass-covered hill in the heart of Lórien, crowned by two concentric rings of trees — one of niphredil, one of elanor — whose flowers bloom in gold and white all year. It was designed as a royal retreat by King Amroth and served as the palace of Lothlórien for ages. The traveller allowed inside Lórien finds the hill astonishingly beautiful; the light here is unlike that of the world outside, clear and golden even in winter.', 'Cerin Amroth es una colina cubierta de hierba en el corazón de Lórien, coronada por dos anillos concéntricos de árboles — uno de niphredil, otro de elanor — cuyas flores florecen en oro y blanco todo el año. Fue concebida como retiro real por el rey Amroth y sirvió de palacio de Lothlórien durante edades. El viajero al que se le permite entrar en Lórien encuentra la colina asombrosamente hermosa; la luz de aquí no es la del mundo de fuera, sino clara y dorada incluso en invierno.', '3a0e8f7057a10fdba04997b4c64e5c03', ST_GeomFromText('POINT(12.115104 49.415377)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (494, 'Fennas Drunnin', 'town', 430, '', 'A Council directed most affairs in Fennas Drúnin, a town that depended on local farms and vineyards for its prosperity. Some Hobbits lived nearby but generally avoided contact with the townspeople. Far from the main roads of Cardolan, it was a good base for anyone wishing to explore southern Rhudaur or the Elven ruins of Eregion.', 'Un Consejo dirigía la mayor parte de los asuntos de Fennas Drúnin, un pueblo que dependía de las granjas y los viñedos del lugar para su prosperidad. Algunos hobbits vivían en las cercanías, pero por lo general evitaban el trato con los del pueblo. Lejos de los caminos principales de Cardolan, era una buena base para quien quisiera explorar el sur de Rhudaur o las ruinas élficas de Eregion.', '3a6a1f51e11f666f2597c738833772d8', ST_GeomFromText('POINT(5.871737 50.178819)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (495, 'Herubar Gûlar', 'castle', 0, 'N/A', 'Herubar Gûlar is a keep of uncertain origin — possibly Númenórean — on the Mitheithel, controlling traffic along and across the river. Its age means its stonework is of high quality, but it has clearly changed hands many times; the current arrangements inside are rough and military. The keep is reputed to be haunted by the spirits of previous garrisons, and the soldiers stationed here are uneasy in the lower levels.', 'Herubar Gûlar es un torreón de origen incierto — posiblemente numenóreano — sobre el Mitheithel, que controla el tránsito por el río y a través de él. Su antigüedad se nota en la calidad de la piedra, pero está claro que ha cambiado de manos muchas veces; los arreglos actuales de su interior son toscos y militares. Se dice que el torreón está encantado por los espíritus de guarniciones anteriores, y los soldados apostados aquí no están tranquilos en los niveles bajos.', '3b0b65c60127a330e405a5e4f60c6590', ST_GeomFromText('POINT(7.128556 52.04951)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (496, 'Mindolhendi', 'city', 900, '', '3d368f4dc9bafeeb9ae34a63791ffd66', ST_GeomFromText('POINT(-8.571719 55.929858)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (497, 'Eredimar', 'village', 92, 'Silvan Elves, Dwarves, Men, Hobbits', 'Eredimar (S. Mountain Home) lay at the foot of the Ered Luin within the valley of Imladorn (S. The Wooded Valley). Despite housing fewer than 100 people, it was remarkable for its cultural diversity — Hobbits, Dwarves, Elves, and Men had all settled here at various times. Sulfur springs nearby gave Eredimar renown as a place of healing, and three well-maintained lodges welcomed travelers.', 'Eredimar (S. Hogar de la Montaña) se hallaba al pie de las Ered Luin, en el valle de Imladorn (S. El Valle Boscoso). Aunque albergaba a menos de cien personas, era notable por su diversidad: hobbits, Enanos, Elfos y Hombres se habían asentado allí en distintos momentos. Unas fuentes de azufre cercanas le dieron a Eredimar renombre como lugar de curación, y tres albergues bien mantenidos recibían a los viajeros.', '3d50c595ccaa0ae4f93d96ce0dd050c6', ST_GeomFromText('POINT(-7.199672 52.568257)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (498, 'Filimer', 'ruins', '', 'Filimer lies in silent ruin, its crumbled walls barely distinguishable from the surrounding landscape. Locals say it was once a settlement of some size, but no record survives of who built it or when it fell. Travellers passing through see only broken stone half-swallowed by grass and thorny scrub.', 'Filimer yace en ruina silenciosa, con los muros desmoronados apenas distinguibles del paisaje que los rodea. La gente del lugar dice que fue un asentamiento de cierto tamaño, pero no se conserva registro de quién lo construyó ni de cuándo cayó. Los viajeros que pasan solo ven piedra partida medio tragada por el pasto y la maleza espinosa.', '3d84453a5c46f62464fcb2edc61b25e1', ST_GeomFromText('POINT(4.034143 49.498538)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (499, 'Bar Irlossiel', 'ruins', '', 'Ruined castle. Barad Perinluoss, commonly known as the Silent Castle, was an ancient Elven refuge in southern Sîrgala — an independent community of Wood-Elves and Arthadan religious refugees who pledged fealty to a half-Elf known as Iralussiel the Tranquil. Iralussiel died mysteriously around the 11th or 12th century T.A., and the shelter became eerily peaceful thereafter.', 'Castillo en ruinas. Barad Perinluoss, conocido comúnmente como el Castillo Silencioso, fue un antiguo refugio élfico en el sur de Sîrgala — una comunidad independiente de Elfos Silvanos y de refugiados religiosos arthedanos que juraron lealtad a una medio elfa llamada Iralussiel la Tranquila. Iralussiel murió de manera misteriosa alrededor de los siglos XI o XII de la T.E., y desde entonces el refugio quedó envuelto en una paz inquietante.', '3df2661c13cb9ec080b86da4f7a5298b', ST_GeomFromText('POINT(-1.862215 50.200255)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (500, 'Methrast', 'tower', 87, 'Gondor', 'Methrast is the southernmost cape of the Belfalas peninsula — sheer, unclimbable cliffs and dangerous shoals that only the most skilled pilots dare approach by sea. The cape also marks one terminus of the Belfalas coastal beacon system; news of approaching enemies sighted here can reach Dol Amroth in hours. Seals sun themselves on the rocky shores below. There is no settlement at the cape itself, only a small watch-post.', 'Methrast es el cabo más meridional de la península de Belfalas — acantilados verticales, imposibles de escalar, y bajíos peligrosos a los que solo los pilotos más diestros se atreven a acercarse por mar. El cabo marca también uno de los extremos del sistema de almenaras costeras de Belfalas; la noticia de un enemigo avistado aquí puede llegar a Dol Amroth en pocas horas. Abajo, en las orillas rocosas, las focas se asolean. En el cabo mismo no hay asentamiento, solo un pequeño puesto de vigía.', '4106d605bd81fc06a53f32b824e5e37a', ST_GeomFromText('POINT(10.279651 39.454845)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (501, 'Nan i Naugrim', 'dwarven mine', 430, '', 'The greatest mine of Nan-i-Naugrim and the capital of the Broadbeam Dwarves since the Second Age. By the mid-Third Age, Edennogrod — the largely ruined Khazad above Nan-i-Naugrim — stood as a shadow of its former self. At the end of the Third Age it was ruled by the feudal lord Grár, who held the honorary title Mountain King among the Shire-folk.', 'La mina más grande de Nan-i-Naugrim y capital de los Enanos de Anchas Vigas desde la Segunda Edad. Hacia mediados de la Tercera Edad, Edennogrod — el Khazad en buena parte arruinado que se alza sobre Nan-i-Naugrim — era una sombra de lo que había sido. Al final de la Tercera Edad la gobernaba el señor feudal Grár, que llevaba entre los de la Comarca el título honorífico de Rey de la Montaña.', '4291252739bbc7141616918bcaba22ad', ST_GeomFromText('POINT(-7.108307 54.632519)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (504, 'Minas Girithlin', 'castle', 60, '70% Cardolani, 20% Eriadoran, 10% Dunnish', 'Minas Girithlin is a stout castle set in the hills, ancestral home of the Princes of Dol Girithlin, built around T.A. 590 to dominate the surrounding countryside. Its walls have withstood several sieges without being breached; the garrison is loyal and experienced. The Prince''s hall within is comfortable if not luxurious — a working noble''s house, with stables and a well-stocked armoury.', 'Minas Girithlin es un castillo recio asentado en las colinas, hogar ancestral de los Príncipes de Dol Girithlin, construido hacia la T.E. 590 para dominar la comarca circundante. Sus muros han resistido varios sitios sin ser abiertos; la guarnición es leal y experimentada. El salón del Príncipe, dentro, es cómodo aunque no lujoso — la casa de un noble en servicio, con establos y una armería bien provista.', '440c871cf631fbad125559f4e3d7fcea', ST_GeomFromText('POINT(-2.625009 48.761944)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (505, 'Bar Adorn', 'town', 600, '', 'Bar Adorn was a settlement on the River Adorn near the western borders of Rohan, serving as a minor trading post between the Rohirrim and the Dunlendings of the region.', 'Bar Adorn era un asentamiento sobre el río Adorn, cerca de las fronteras occidentales de Rohan, que funcionaba como puesto comercial menor entre los rohirrim y los dunlendinos de la región.', '443fc38145c4ef1c1899d04d3d02ce4d', ST_GeomFromText('POINT(3.388161 46.091757)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (506, 'Saerthondost', 'fortress', 200, 'Gondor', 'Saerthondost was one of two Dúnedain strongholds protecting Pinnath Gelin and Nan Lefnui from the wilds of Hairaverkien. Located on the north bank of the Lefnui where the river turned sharply northwest, it was named for the nearby swamps rich in shepherd''s herbs. A lighthouse tower linked it to its sister fortress Pinnornost to the northeast; it was founded in T.A. 823 and abandoned in T.A. 2157.', 'Saerthondost fue una de las dos plazas fuertes dúnedain que protegían Pinnath Gelin y Nan Lefnui de las tierras salvajes de Hairaverkien. Situada en la orilla norte del Lefnui, donde el río gira bruscamente al noroeste, recibió su nombre por los pantanos cercanos, ricos en hierbas de pastor. Una torre de fuego la unía con su fortaleza hermana de Pinnornost, al nordeste; fue fundada en la T.E. 823 y abandonada en la T.E. 2157.', '46d9ea208b4d78d838a35cbfe57ccc5f', ST_GeomFromText('POINT(3.287055 42.466171)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (507, 'Calenhad', 'watchtower', 90, '100% Gondorian', 'Ordered built in T.A. 491 by Gondor''s King on the site of an earlier signal-platform.. Communications in northern Gondor.. Calenhad is the sixth beacon in the chain stretching from Minas Anor to the northwest.', 'Su construcción fue ordenada en la T.E. 491 por el Rey de Gondor, sobre el sitio de una plataforma de señales anterior.. Comunicaciones en el norte de Gondor.. Calenhad es la sexta almenara de la cadena que se extiende desde Minas Anor hacia el noroeste.', '476fb6b7cd1817b7359c8b8c58e1a266', ST_GeomFromText('POINT(14.264176 44.278558)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (508, 'Adavalinda', 'village', 140, '', 'A small village on the eastern bank of the Lefnui, where the river meets the Rámanen confluence. It serves as a staging point for travellers seeking to cross the White Mountains via the Cirith Iaur, some forty miles to the northwest. A ferry here is the last easy crossing before the river narrows to flat-bottomed-boat country upstream. Stone and timber houses cluster around the landing, their occupants largely dependent on guiding travellers and working the river.', 'Una aldea pequeña en la orilla oriental del Lefnui, donde el río se junta con la confluencia del Rámanen. Sirve de punto de partida para los viajeros que buscan cruzar las Montañas Blancas por el Cirith Iaur, unas cuarenta millas al noroeste. La balsa que hay aquí es el último cruce fácil antes de que el río se angoste y solo admita botes de fondo plano. Casas de piedra y madera se agrupan alrededor del embarcadero, y sus habitantes viven en buena medida de guiar viajeros y de trabajar el río.', '481a34f0a4593aa08c7b358c62091a35', ST_GeomFromText('POINT(1.378078 41.886452)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (509, 'Cargash', 'watchtower', 50, '100% Angmarean (Mixed Mannish)', 'Built by Witch-king, ca. T.A. 1400.. Designed to give the Witch-king warning of trespassers and a base from which to strike at Arthedain.. Regular patrols depart from Mindil Cargash to sweep En Udanoriath which lies between Angmar and Arthedain.', 'Construida por el Rey Brujo hacia la T.E. 1400.. Pensada para dar al Rey Brujo aviso de intrusos y una base desde la que golpear Arthedain.. De Mindil Cargash parten patrullas regulares para barrer En Udanoriath, que se extiende entre Angmar y Arthedain.', '482aba99e3d5973b8398277777044585', ST_GeomFromText('POINT(5.813279 54.991128)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (510, 'Thingastathbaurg', 'town', 150, 'Woodmen', 'A village of the Woodmen in the Upper Anduin Vales, the name meaning ''Assembly-Place Fort'' in Rhovanion. Its timber longhouses and stockaded hall sit in a forest clearing; the Woodmen here are sturdy folk who live by hunting, forestry and small farming. The great trees of Mirkwood are close by; the village is self-reliant and watchful.', 'Una aldea de los Hombres de los Bosques en los Valles del Alto Anduin; su nombre significa ''Fuerte del Lugar de Asamblea'' en la lengua de Rhovanion. Sus casas largas de madera y su salón empalizado ocupan un claro del bosque; los Hombres de los Bosques de aquí son gente recia que vive de la caza, del monte y de la agricultura pequeña. Los grandes árboles del Bosque Negro quedan cerca; la aldea se basta a sí misma y está siempre atenta.', '48d6956a9e549bdf8867e069a7424d2c', ST_GeomFromText('POINT(13.723291 53.101593)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (511, 'Minas Ithil', 'fortified city', 30000, '90% Gondorian, 10% Mixed Mannish', 'Founded by Isildur in S.A. 3320, rebuilt in T.A. 1.. Control of the passes into Mordor; garrison for Gondor''s army in Ithilien; location of a Palantír.. Minas Ithil is a Gondorian city protected by a deep valley in the Ephel Dúath.', 'Fundada por Isildur en la S.E. 3320, reconstruida en la T.E. 1.. Control de los pasos hacia Mordor; guarnición del ejército de Gondor en Ithilien; lugar de un palantír.. Minas Ithil es una ciudad gondoriana protegida por un valle profundo de las Ephel Dúath.', '4935db7004ad27dfe5c8740008ea1b23', ST_GeomFromText('POINT(18.905247 43.528463)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (512, 'Michel Delving', 'town', 650, '45% Harfoot, 30% Stoor, 25% Fallohide', 'Michel Delving is the largest town and administrative capital of the Shire, spread across the gentle slopes of the White Downs in the Westfarthing. The Mayor''s Hall and the Mathom-house — a repository of Hobbit curiosities — are its two most notable buildings. Most houses are of whitewashed stone with round doors and windows; kitchen gardens and flower beds line every lane. Market day is the social high point of the week, drawing Hobbits from the surrounding villages to sell produce and catch up on news.', 'Cavada Grande es el pueblo más grande y la capital administrativa de la Comarca, extendida sobre las laderas suaves de las Quebradas Blancas, en la Cuaderna del Oeste. La Casa del Alcalde y la Casa de los Mathoms — depósito de curiosidades hobbit — son sus dos edificios más notables. Casi todas las casas son de piedra encalada, con puertas y ventanas redondas; huertas y canteros de flores bordean cada callejón. El día de mercado es el punto alto de la semana y atrae a los hobbits de las aldeas vecinas a vender sus productos y ponerse al día con las noticias.', '493a02d2bcbd0fb36907edb7ea0eecaf', ST_GeomFromText('POINT(-2.454585 51.363869)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (513, 'Vidusbaurg', 'town', 520, 'Northmen', 'Buhr Widu, situated near the small Forest Lake, retained some of the royal splendor of the days of Vidugavia. The Grammuz princes who ruled it after the Plague lacked the strength to restore its former glory. Like most Northman villages on the plains, it consisted of long wooden and thatched houses defended by an earthen wall and sturdy wooden towers.', 'Buhr Widu, situada cerca del pequeño Lago del Bosque, conservaba algo del esplendor real de los días de Vidugavia. Los príncipes Grammuz que la gobernaron después de la Plaga no tuvieron fuerza para devolverle su gloria anterior. Como la mayoría de las aldeas de los Hombres del Norte en las llanuras, consistía en casas largas de madera y techo de paja, defendidas por un muro de tierra y recias torres de madera.', '4a24da5b5ac1a6c3fb9cdd15d503819f', ST_GeomFromText('POINT(20.2981 50.405638)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (514, 'Morkai', 'castle', 1000, '100% Angmarean (Mixed Mannish)', 'Barad Morkai rises from a granite bluff above the Angmar Road — a black-stone fortress built by the Witch-king to monitor all movement entering and leaving the Nan Angmar. The road passes directly beneath its walls; travellers feel the weight of the fortress''s watch as they pass. A large garrison occupies it permanently; the broad plains to the south serve as Orc training grounds.', 'Barad Morkai se alza sobre un risco de granito por encima del Camino de Angmar — una fortaleza de piedra negra construida por el Rey Brujo para vigilar todo movimiento que entre o salga de Nan Angmar. El camino pasa justo bajo sus muros; el viajero siente el peso de esa vigilancia al pasar. La ocupa de forma permanente una guarnición numerosa, y las llanuras anchas del sur sirven de campo de instrucción para los orcos.', '4be9468f854fa8a1dcb64764ace32902', ST_GeomFromText('POINT(6.60636 55.068171)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (515, 'Faranel', 'ruins', '', 'Faranel is a ruined city in the northern lands, its once-inhabited quarters now exposed to wind and rain. The scale of the ruins suggests a sizeable population at its height; by the mid-Third Age there is not a single inhabited building remaining.', 'Faranel es una ciudad en ruinas de las tierras del norte, con sus barrios antaño habitados hoy expuestos al viento y a la lluvia. La extensión de las ruinas sugiere una población considerable en su mejor momento; hacia mediados de la Tercera Edad no queda en pie un solo edificio habitado.', '5011afade619f3d35e1d667cfb0f6f69', ST_GeomFromText('POINT(-1.381329 54.563073)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (517, 'Bar Morthil', 'point of interest', 'Dúnedain', 'A royal estate at the westernmost tip of Andrast — the farthest habitation in all of Gondor. A single stone manor overlooks the sheer sea-cliffs of Ras Morthil, where the ocean crashes hundreds of feet below. The estate is maintained year-round by a warden and servants; it faces west toward the open sea, built by the sons of Elendil as a memorial to drowned Númenór. Kings and Stewards sometimes come here for solitude.', 'Una hacienda real en el extremo más occidental de Andrast — la vivienda más lejana de todo Gondor. Una sola casa señorial de piedra domina los acantilados verticales de Ras Morthil, donde el océano rompe cientos de pies más abajo. La hacienda se mantiene todo el año a cargo de un guardián y de sus sirvientes; mira al oeste, hacia el mar abierto, y fue construida por los hijos de Elendil como memorial de la Númenor hundida. Reyes y Senescales vienen aquí a veces a buscar soledad.', '556e0b805bb4afe0be501c6fb7924f5e', ST_GeomFromText('POINT(-3.144798 39.274599)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (518, 'Tilmendir', 'castle', 140, '70% Gondorian, 30% Dunnish', 'Built by Gondor, circa T.A. 991.. Surveillance of traffic passing from Westmarch to Anfalas; a show of authority for the local Dunnish tribes.. Tilmendir is located ten miles south of the town Derwath.', 'Construido por Gondor hacia la T.E. 991.. Vigilancia del tránsito que pasa de la Marca del Oeste a Anfalas; muestra de autoridad ante las tribus dunlendinas del lugar.. Tilmendir se encuentra diez millas al sur del pueblo de Derwath.', '5782c24e1c9a90bd8ae93a0624d9e87d', ST_GeomFromText('POINT(6.214492 45.163506)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (521, 'Guinnion', 'ruins', '', 'The village of Guinnion has long since been abandoned — a scattering of mossy foundation stones and choked lanes where a small community once lived. The site lies quietly off the road, overlooked by all but the most curious travellers.', 'La aldea de Guinnion está abandonada desde hace mucho — un puñado de piedras de cimiento cubiertas de musgo y callejones ahogados por la maleza donde vivió una comunidad pequeña. El sitio queda tranquilo, apartado del camino, y pasa desapercibido para todos salvo para los viajeros más curiosos.', '59cf3830ff27cef7e73d05bbe03b3805', ST_GeomFromText('POINT(-1.168778 47.430766)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (522, 'Bodroth', 'city', 0, '', 'Bodroth was a city of Eketyar in Arthedain, situated on the northern shores of Lake Evendim about forty miles north of Annúminas. It had a population of roughly 4,900 in T.A. 250, but declined through the Third Age and was eventually abandoned, though it survived the fall of the last King by several generations.', 'Bodroth era una ciudad de Eketyar, en Arthedain, situada en las orillas septentrionales del Lago Evendim, unas cuarenta millas al norte de Annúminas. Tenía una población de unos 4.900 habitantes en la T.E. 250, pero decayó a lo largo de la Tercera Edad y acabó abandonada, aunque sobrevivió a la caída del último Rey por varias generaciones.', '5abbd6f333ee1250e91efc4a02013c02', ST_GeomFromText('POINT(-1.098611 53.3107)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (523, 'Culwic', 'village', 400, 'Gondor, Dwarves', 'Culwic, originally known as Himtil or Himobel (S. Chill Village) and later as Colwich, was a small town in western Arthedain on the Little Lune, just north of the borders of Dor Lelvin and Lindon. Its mixed population of Men and Dwarves supported the dwarven settlements to the north through industry and agriculture.', 'Culwic, conocida en su origen como Himtil o Himobel (S. Aldea Fría) y más tarde como Colwich, era un pueblo pequeño del oeste de Arthedain, sobre el Pequeño Lhûn, justo al norte de los límites de Dor Lelvin y Lindon. Su población mixta de Hombres y Enanos sostenía con su industria y su agricultura a los asentamientos enanos del norte.', '5cbba5e7606045d742bbfc0cd65aa0b1', ST_GeomFromText('POINT(-6.450549 53.936333)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (525, 'Cirith Dudhrandir', 'town', 450, '', 'Cirith Dudhrandir was the only major mountain pass through the Belfalas Peninsula and the only one with a paved road, making it strategically vital for Gondor''s southern defenses. At 5,800 feet and over sixty miles east to west, it was guarded by the fortress of Naur Amrûn. The pass was named in S.A. 3400 when Edhelion of Eldalonde received Belfalas as a fief.', 'Cirith Dudhrandir era el único paso de montaña importante de la península de Belfalas y el único con camino empedrado, lo que lo volvía vital para las defensas meridionales de Gondor. A 5.800 pies de altura y con más de sesenta millas de este a oeste, lo guardaba la fortaleza de Naur Amrûn. El paso recibió su nombre en la S.E. 3400, cuando Edhelion de Eldalonde recibió Belfalas en feudo.', '5ee93f5bc3e4001805d234e95a79657d', ST_GeomFromText('POINT(10.161853 41.049572)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (526, 'Anghul', 'castle', 80, 'Sauron', 'Anghul (''Iron-wind'' in Sindarin) is one of the six great fortresses of Angmar, situated on a hill above the Anghir below the escarpment of Nan Angmar. It broods over the Anghir Vale and controls the No Man''s Land. A garrison of 300 men watches for spies; the commander is one of the Witch-king''s Ashâktur. Dark stone walls; the wind off the escarpment is bitter and constant. The Black Raven on Red is the garrison''s banner.', 'Anghul (''Viento de Hierro'' en sindarin) es una de las seis grandes fortalezas de Angmar, situada en una colina sobre el Anghir, al pie del escarpe de Nan Angmar. Vigila con ceño el Valle del Anghir y controla la Tierra de Nadie. Una guarnición de trescientos hombres busca espías; su comandante es uno de los Ashâktur del Rey Brujo. Muros de piedra oscura; el viento que baja del escarpe es amargo y constante. El estandarte de la guarnición es el Cuervo Negro sobre Rojo.', '5f7b31b1e45bc32f9710965931ec02be', ST_GeomFromText('POINT(5.880489 55.633701)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (527, 'Forlond', 'town', 840, '50% Silvan Elvish, 40% Sinda, 10% Noldo', 'Forlond is the southern Elvish haven of Lindon, hidden at the head of a steep fjord on the eastern shore of the Gulf of Lhûn. Founded after the ruin of Beleriand, it is primarily a shipbuilding settlement — the sound of hammers on timber and caulking mallets is heard on every visit. The Elves here are of mixed kindred and more accustomed to mortal visitors than most Elvish settlements, though the haven is not on any road and is difficult to find.', 'Forlond es el puerto élfico meridional de Lindon, oculto en la cabecera de un fiordo empinado en la orilla oriental del Golfo de Lhûn. Fundado después de la ruina de Beleriand, es sobre todo un asentamiento de construcción de naves — el sonido de los martillos sobre la madera y de los mazos de calafateo se oye en cualquier visita. Los Elfos de aquí son de linajes mezclados y están más acostumbrados a las visitas de mortales que en la mayoría de los asentamientos élficos, aunque el puerto no queda sobre ningún camino y es difícil de encontrar.', '60d41486e9354c4d4dd2445e69e812e8', ST_GeomFromText('POINT(-9.783386 52.192311)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (528, 'Rildolach', 'ruins', '', 'Rildolach lies in ruin among the hills, its old streets grown over. Travellers who venture close enough to see it clearly describe a settlement of Arnorian-era stonework, collapsed and overgrown, with no inhabitants and no sign of recent occupation.', 'Rildolach yace en ruinas entre las colinas, con sus calles viejas cubiertas de maleza. Los viajeros que se acercan lo bastante para verla con claridad describen un asentamiento de piedra de la época arnoriana, derrumbado y invadido por la vegetación, sin habitantes ni señal de ocupación reciente.', '62529e65a017f5026aa81f71c3acec85', ST_GeomFromText('POINT(-3.902661 53.717587)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (529, 'Malehaut', 'village', 45, '', 'A coastal Eriadorian town of Fonntir in Minhiriath, known as Atem (''fathom'') or Carmalehaute (''Malehaut''s town'') in Dunnish. By T.A. 2740 it had a population of some 2,700 — a working port with fishermen, traders and those who live by the sea''s rhythms.', 'Un pueblo costero eriadorano de Fonntir, en Minhiriath, conocido como Atem (''braza'') o Carmalehaute (''el pueblo de Malehaut'') en dunlendino. Hacia la T.E. 2740 tenía unos 2.700 habitantes — un puerto de trabajo, con pescadores, comerciantes y gente que vive según los ritmos del mar.', '62ee9d110b26b1dfee272ff8634879da', ST_GeomFromText('POINT(-3.251467 47.012628)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (530, 'Iant Methed', 'point of interest', 5, '', 'Iant Methed (The Last Bridge) was built of stone with three great arches at the height of Arnorian power in T.A. 320. In the petty wars of Rhudaur the crossing was generally considered neutral ground. The Last Inn, long run by the Grumm family, stood nearby; just northwest lay the ruins of Dol Elerilde, stronghold of an old lord of Rhudaur.', 'Iant Methed (El Último Puente) fue construido en piedra, con tres grandes arcos, en el momento de mayor poder de Arnor, en la T.E. 320. En las guerras menudas de Rhudaur el cruce se tuvo por lo general como terreno neutral. Cerca estaba la Última Posada, regenteada largo tiempo por la familia Grumm; justo al noroeste quedaban las ruinas de Dol Elerilde, plaza fuerte de un antiguo señor de Rhudaur.', '6442aa8e9dbeb487c3a787e44786eb05', ST_GeomFromText('POINT(6.656038 51.505654)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (531, 'Laur Dunnen', 'town', 420, '', 'Larach Duhnnan lay on territory of Clan Feargan but the flow of foreign traffic made it a neutral ground for inter-tribal discussions and trade. It had no walls, relying on the nearby Feargan fortress for defense, and sat at one of the few accessible crossings of the Dunstrem, for which the clan lords charged a modest toll.', 'Larach Duhnnan quedaba en territorio del Clan Feargan, pero el paso de tránsito extranjero la volvió terreno neutral para las conversaciones y el comercio entre tribus. No tenía murallas y dependía para su defensa de la fortaleza Feargan vecina; se asentaba en uno de los pocos cruces accesibles del Dunstrem, por el que los señores del clan cobraban un peaje modesto.', '650c99a437e0cce7a326674897da17d6', ST_GeomFromText('POINT(4.330594 47.761037)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (532, 'Aerost', 'fortress', 300, 'Gondor', 'A coastal fortress on the Rathon Gondor in Anfalas, some forty miles west of Lond Galen. Built after the Great Raid on Pelargir (T.A. 1634) to defend the coast between the Celgalen and the Lefnui, Aerost is a key link in Anfalas''s chain of coastal beacon towers. From its walls, watchmen can warn neighbouring settlements of Corsair raids within hours. The fort''s stone battlements are weathered by salt wind, and a small settlement of soldiers and their families huddles in its shadow.', 'Una fortaleza costera sobre el Rathon Gondor, en Anfalas, unas cuarenta millas al oeste de Lond Galen. Construida después de la Gran Incursión sobre Pelargir (T.E. 1634) para defender la costa entre el Celgalen y el Lefnui, Aerost es un eslabón clave en la cadena de torres de fuego de Anfalas. Desde sus muros los vigías pueden avisar a los asentamientos vecinos de una incursión de los Corsarios en pocas horas. Las almenas de piedra del fuerte están gastadas por el viento salado, y un pequeño asentamiento de soldados y sus familias se acurruca a su sombra.', '65907bd900d495733194dcf01f5f1dde', ST_GeomFromText('POINT(3.626902 41.034679)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (533, 'Talsir', 'town', 250, '', 'Talsir was one of the free cities of Cardolan on the west bank of the Gwathló, about 170 miles downstream from Tharbad. With a population of roughly 4,300 in T.A. 250, it was an important river stop and one of the few settlements of ancient Minhiriath to survive into the late Third Age.', 'Talsir fue una de las ciudades libres de Cardolan, en la orilla occidental del Gwathló, unas 170 millas río abajo de Tharbad. Con una población de unos 4.300 habitantes en la T.E. 250, era una parada fluvial importante y uno de los pocos asentamientos del antiguo Minhiriath que sobrevivió hasta la última parte de la Tercera Edad.', '67efb3b67cdd1b2fd62ecb938e847972', ST_GeomFromText('POINT(-0.234818 47.538839)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (534, 'Framsburg', 'city', 340, 'Northmen', 'Wraecaburg, though not directly under the Witch-King''s rule, suffered frequent attacks and harbored many unsavory characters from outside Rhovanion. Its men occasionally traded with kinsmen at Maethelburg, but relations grew increasingly suspicious over time.', 'Wraecaburg, aunque no estaba directamente bajo el dominio del Rey Brujo, sufría ataques frecuentes y daba cobijo a mucha gente de mal vivir venida de fuera de Rhovanion. Sus hombres comerciaban de tanto en tanto con sus parientes de Maethelburg, pero las relaciones se fueron volviendo cada vez más desconfiadas.', '681965fb86a89207792118ea20e07ff9', ST_GeomFromText('POINT(14.009562 54.17404)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (535, 'Amon Sûl', 'ruins', 0, 'N/A', 'Originally built by Elendil in the Second Age.. Repository for a Palantír; later served as a landmark at the juncture of the three Kingdoms of the North.. From this vantage point, one has an excellent view of the Great East Road as it heads towards Rhudaur. For this reason, the hill served as a strategic focus for western Arthedain and Cardolan and has a long history of conflict surrounding it. The tower of Amon Sûl once held Palantír, which was removed to Fornost following the invasion by Angmar in T.A. 1409.', 'Construida en su origen por Elendil en la Segunda Edad.. Depósito de un palantír; más tarde sirvió como mojón en el punto de encuentro de los tres Reinos del Norte.. Desde este punto se tiene una vista excelente del Gran Camino del Este mientras se dirige hacia Rhudaur. Por eso la colina fue foco estratégico del oeste de Arthedain y de Cardolan, y tiene una larga historia de conflictos a su alrededor. La torre de Amon Sûl albergó un palantír, que fue llevado a Fornost después de la invasión de Angmar en la T.E. 1409.', '68bdd7527815b3a3996d6fe4a7ffc0d4', ST_GeomFromText('POINT(3.521455 51.600639)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (536, 'Caras Galadhon', 'city', 800, '60% Silvan, 35% Sinda, 5% Noldo', 'Caras Galadhon is the city of the Galadhrim in the heart of Lórien, built as a network of interconnected flets on the massive trunks of mallorn trees. Designed by Galadriel, it rises tier upon tier through the golden canopy; the highest flets look out over a sea of leaves lit from within by the light that never quite matches the light of the world outside. Mortals who enter feel simultaneously welcomed and observed; the city is safe but its beauty is unsettling.', 'Caras Galadhon es la ciudad de los Galadhrim en el corazón de Lórien, construida como una red de flets unidos entre sí sobre los troncos enormes de los mallorn. Concebida por Galadriel, se eleva nivel tras nivel a través de la bóveda dorada; los flets más altos miran sobre un mar de hojas encendido por dentro con una luz que nunca llega a coincidir con la del mundo de fuera. Los mortales que entran se sienten a la vez bien recibidos y observados; la ciudad es segura, pero su belleza inquieta.', '6bbb1c408a02daac53e41d565a15fea4', ST_GeomFromText('POINT(12.542319 49.212858)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (538, 'Endrist', 'ruins', '', 'Endrist was once a township of the highland region, but by the mid-Third Age its population had long since gone. The foundations and a few stretches of wall are all that remain — a quiet ruin avoided by those who know its history.', 'Endrist fue en su momento un municipio de la región de las tierras altas, pero hacia mediados de la Tercera Edad su población había desaparecido hacía tiempo. Solo quedan los cimientos y unos tramos de muro — una ruina tranquila que evitan quienes conocen su historia.', '6e182f410f716a021ddf51be662a827d', ST_GeomFromText('POINT(-3.934113 50.51091)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (539, 'Annulond', 'city', 1200, 'Gondor', 'The principal town of Pinnath Gelin, set at the tip of a tongue of land where a stream from the Ram Galen joins the Lefnui. The folk of Annúlond maintain the only bridge spanning the Lefnui in this region. The town is modest but orderly: small stone houses of one or two storeys line the streets, and the lieutenant-Cáno''s large house stands beside the open main square that slopes down to the river wharf. Since the area lies in Gondor''s peaceful interior, no town wall was ever built. Outside the walls, the Knight of Annúlond''s manor overlooks liegemen''s farms and tenant plots.', 'El pueblo principal de Pinnath Gelin, asentado en la punta de una lengua de tierra donde un arroyo bajado del Ram Galen se une al Lefnui. La gente de Annúlond mantiene el único puente que cruza el Lefnui en esta región. El pueblo es modesto pero ordenado: casas pequeñas de piedra, de uno o dos pisos, bordean las calles, y la casa grande del teniente-Cáno se alza junto a la plaza principal abierta, que baja en pendiente hasta el muelle del río. Como la zona queda en el interior apacible de Gondor, nunca se construyó una muralla. Fuera del pueblo, la casa señorial del Caballero de Annúlond domina las granjas de sus vasallos y las parcelas de los arrendatarios.', '7019dd7f9f38eca5ad9f1305d1aec81b', ST_GeomFromText('POINT(1.770028 41.004206)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (540, 'Gamwich', 'village', 120, '50% Harfoot, 30% Stoor, 20% Fallohide', 'Settled during the migration of Hobbits into the Shire, T.A. 1601-1610.. An agricultural community.. Gamwich is the Westron translation of the Kuduk name Galabas.', 'Poblada durante la migración de los hobbits a la Comarca, T.E. 1601-1610.. Comunidad agrícola.. Gamwich es la traducción al oestron del nombre kuduk Galabas.', '703e799a1608a3b9ff4ba4d98bf4f5bd', ST_GeomFromText('POINT(-3.155729 52.02727)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (542, 'Bar Nevedui', 'castle', 600, 'Gondor', 'A modest castle of southern Andrast on the river Nevduin, part of the remote county of Bar Morthil. Its walls are of local grey stone, maintained by a small household garrison; the surrounding land is sparsely farmed by Dunir dependants who provide the fort with supplies in exchange for protection from Corsair raiders.', 'Un castillo modesto del sur de Andrast, sobre el río Nevduin, parte del remoto condado de Bar Morthil. Sus muros son de piedra gris del lugar y los mantiene una guarnición doméstica pequeña; la tierra de alrededor la cultivan de forma dispersa unos dependientes dunir que proveen al fuerte de suministros a cambio de protección frente a los saqueadores Corsarios.', '72157ca5d66a0573a56b3e8a6faabf35', ST_GeomFromText('POINT(-2.29744 39.175898)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (543, 'Lorilad', 'village', 89, '', 'Lórilad was a fortified village of Lebennin, situated in the Ethir Anduin roughly seventy-five miles downstream from Pelargir, halfway between Pelargir and the western cape of Lebennin.', 'Lórilad fue una aldea fortificada de Lebennin, situada en el Ethir Anduin unas setenta y cinco millas río abajo de Pelargir, a mitad de camino entre Pelargir y el cabo occidental de Lebennin.', '737cd8e5ebf3e66dbf23ade112de8011', ST_GeomFromText('POINT(14.580513 40.790865)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (544, 'Sindbar', 'town', 540, 'Gondor', 'A small Gondorian town near the westernmost eaves of Drúadan Forest, about eight miles north of Mount Nardol. Its stone houses and quiet market serve the scattered farms and woodcutters of the area. The Drúadan Forest nearby is avoided by most travellers; the Woses are seldom seen but always suspected to be watching.', 'Un pueblo gondoriano pequeño cerca del linde más occidental del Bosque de Drúadan, unas ocho millas al norte del Monte Nardol. Sus casas de piedra y su mercado tranquilo atienden a las granjas dispersas y a los leñadores de la zona. La mayoría de los viajeros evita el Bosque de Drúadan vecino; a los woses casi nunca se los ve, pero siempre se sospecha que están mirando.', '75990a293755b179f5736ad958400efe', ST_GeomFromText('POINT(16.166696 44.061143)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (545, 'Larad', 'ruins', '', 'Larad is a ruin on the edge of a river — the remains of a once-inhabited city now silent and empty. Its stone walls have partly fallen; the streets are overgrown and the only visitors are the occasional shepherd sheltering from rain.', 'Larad es una ruina al borde de un río — los restos de una ciudad antes habitada, ahora silenciosa y vacía. Sus muros de piedra han caído en parte; las calles están cubiertas de maleza y las únicas visitas son algún pastor que se guarece de la lluvia.', '76dfe74b025986ac0f4ebb77b57d9539', ST_GeomFromText('POINT(-4.625452 55.090882)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (546, 'Sackville', 'village', 110, '50% Stoor, 45% Harfoot, 5% Fallohide', 'Settled during the migration to the Shire, 1601-1610.. Agriculture.. Proximity to the rugged Men of Eriador''s Red Hills bestows a reputation for crudity upon the residents of Sackville.', 'Poblada durante la migración a la Comarca, 1601-1610.. Agricultura.. La cercanía de los rudos Hombres de las Colinas Rojas de Eriador le da a los habitantes de Sackville fama de gente tosca.', '77d37e506c88125d784b139a91d2b8c5', ST_GeomFromText('POINT(-1.551914 50.704271)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (547, 'Amon Dîn', 'watchtower', 120, '100% Gondorian', 'Construction of a signal-platform ordered in S.A. 3325 by Anárion of Gondor. Upgraded in the fifth century of the Third Age.. Part of Gondor''s northern communications network.. Amon Dîn was the first, counting from east to west, in a chain of seven beacon-towers. Its watch-fire relayed warning to Minas Anor of any attack on Gondor''s northern frontiers.', 'La construcción de una plataforma de señales fue ordenada en la S.E. 3325 por Anárion de Gondor. Mejorada en el siglo quinto de la Tercera Edad.. Parte de la red de comunicaciones septentrional de Gondor.. Amon Dîn era la primera, contando de este a oeste, de una cadena de siete torres de almenara. Su fuego de vigilancia transmitía a Minas Anor el aviso de cualquier ataque a las fronteras septentrionales de Gondor.', '7c9213e731d938b81aea872e8df58c2b', ST_GeomFromText('POINT(17.414725 43.745926)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (548, 'Buzdum Mazar', 'dwarven mine', 490, 'Dwarves', 'The greatest mine of Nan-i-Naugrim and the capital of the Broadbeam Dwarves since the Second Age. By the mid-Third Age, Edennogrod — the largely ruined Khazad above Nan-i-Naugrim — dominated the area. At the end of the Third Age it was governed by the feudal lord Grár, who bore the honorary title Mountain King among the Shire-folk.', 'La mina más grande de Nan-i-Naugrim y capital de los Enanos de Anchas Vigas desde la Segunda Edad. Hacia mediados de la Tercera Edad, Edennogrod — el Khazad en buena parte arruinado que se alza sobre Nan-i-Naugrim — dominaba la zona. Al final de la Tercera Edad la gobernaba el señor feudal Grár, que llevaba entre los de la Comarca el título honorífico de Rey de la Montaña.', '7ca62dfc23b7be2ef8254d8924249fdc', ST_GeomFromText('POINT(-7.283618 54.590338)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (549, 'Minas Brethil', 'city', 3000, '', 'Minas Brethil (S. Silver Birch Tower), capital of Celossien, was situated in the upper Serni valley and served as an agricultural center between the Glinduin and Serni rivers. After the Kin-strife it held some 4,000 inhabitants, a number halved by the Great Plague and only slowly recovered thereafter.', 'Minas Brethil (S. Torre del Abedul Plateado), capital de Celossien, se hallaba en el valle alto del Serni y funcionaba como centro agrícola entre los ríos Glinduin y Serni. Después de la Lucha entre Parientes tenía unos 4.000 habitantes, número que la Gran Plaga redujo a la mitad y que solo se recuperó lentamente.', '7df88f8d7e3218d96af25370a52d4ce1', ST_GeomFromText('POINT(15.13078 42.223616)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (550, 'Cithrenor', 'ruins', 12, '', 'Cithrenor is a ruined town, its streets grown over and its buildings collapsed to waist-height piles of dressed stone. A handful of travellers camp here when they must, but the place carries an atmosphere of abandonment that discourages lingering.', 'Cithrenor es un pueblo en ruinas, con las calles cubiertas de maleza y los edificios derrumbados en montones de piedra labrada que llegan a la cintura. Algún viajero acampa aquí cuando no tiene otra, pero el lugar tiene un aire de abandono que no invita a quedarse.', '8047934e8120045a7dfdd987a70b4a80', ST_GeomFromText('POINT(-3.529856 49.026391)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (551, 'Maegoth', 'ruins', '', 'Maegoth was a city once, but the traveller finds only rubble. Crumbling walls, broken towers and overgrown foundations stretch for some distance across the hillside — a reminder of a time when this region was more populous and prosperous.', 'Maegoth fue una ciudad, pero el viajero no encuentra más que escombros. Muros que se desmoronan, torres partidas y cimientos invadidos por la maleza se extienden un buen tramo por la ladera — recuerdo de un tiempo en que esta región estaba más poblada y era más próspera.', '8092b4e9ff96ef0fca43812a665b6a64', ST_GeomFromText('POINT(-1.537858 53.032579)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (552, 'Barad Eldanar', 'castle', 400, 'Sauron', 'An ancient Arnorian castle on the eastern edge of the Dyr Úvadan, ancestral home of House Eldanar — one of Elendil''s Faithful. One of the oldest Númenórean fortifications in northwestern Middle-earth. By c. T.A. 1325, the Angmarim seized it; the rightful lord Elenuil escaped through a secret tunnel and the family has dwelt in Fornost since. A well-armed Angmarim garrison now holds the walls.', 'Un antiguo castillo arnoriano en el borde oriental del Dyr Úvadan, hogar ancestral de la Casa Eldanar — una de las familias de los Fieles de Elendil. Es una de las fortificaciones numenóreanas más antiguas del noroeste de la Tierra Media. Hacia la T.E. 1325 los angmarim la tomaron; el señor legítimo, Elenuil, escapó por un túnel secreto, y desde entonces la familia habita en Fornost. Hoy una guarnición angmarim bien armada ocupa los muros.', '83b667b645b766f8d319f13ce83d8ca3', ST_GeomFromText('POINT(5.714704 54.61147)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (553, 'Enerond', 'ruins', 120, 'Gondor', 'Enerond is a ruined city on the east bank of the Lune, its stone buildings fallen and its population long since gone. It declined steadily through the Third Age; by T.A. 2050 there is not a soul living among the old walls.', 'Enerond es una ciudad en ruinas en la orilla oriental del Lhûn, con sus edificios de piedra caídos y su población desaparecida hace mucho. Decayó de manera constante a lo largo de la Tercera Edad; hacia la T.E. 2050 no vive un alma entre los muros viejos.', '847e48fd06a77bc060eecf08013ec386', ST_GeomFromText('POINT(-4.803929 54.812309)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (554, 'Haerlond', 'town', 390, '60% Gondorian, 40% Dunnish', 'Haerlond is a small Gondorian harbour-town at the tip of Andrast, its modest dock serving ships damaged rounding the treacherous cape. Originally a Númenórean settlement of the Second Age, it received a royal charter from King Turambar in T.A. 602. The fishermen here are skilled at patching hulls and provisioning storm-battered vessels; their village is small and windswept, with whitewashed walls and a single street running down to the landing.', 'Haerlond es un pequeño pueblo portuario gondoriano en la punta de Andrast, cuyo muelle modesto atiende a los barcos averiados al doblar el cabo traicionero. Asentamiento numenóreano en su origen, en la Segunda Edad, recibió fuero real del rey Turambar en la T.E. 602. Los pescadores de aquí tienen mano para remendar cascos y aprovisionar naves castigadas por las tormentas; su aldea es pequeña y batida por el viento, de muros encalados y una sola calle que baja hasta el embarcadero.', '850a1cb58a471a45f6dc25bffa830125', ST_GeomFromText('POINT(-2.935146 38.976766)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (555, 'Fanduin', 'city', 500, '', 'Fanduin had a fairly large population of 4,100 in T.A. 250, but its numbers declined through the middle Third Age and the settlement was eventually abandoned before the end of the Third Age.', 'Fanduin tuvo una población bastante grande, de 4.100 habitantes en la T.E. 250, pero sus números decayeron durante la parte media de la Tercera Edad y el asentamiento acabó abandonado antes del fin de la Edad.', '8606fc2022212421702bfc7856e27660', ST_GeomFromText('POINT(0.618315 52.568654)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (556, 'Pelargir', 'fortified city', 2500, 'Gondor', 'Pelargir (S. Garth of Royal Ships) was founded by the Faithful of Númenor in S.A. 2350 and became the chief harbour and oldest city of Gondor, built on the Anduin at the mouth of the Sirith. It served as the base of Gondor''s great fleet and was the kingdom''s primary port of trade, second city only to Minas Tirith.', 'Pelargir (S. Garth de las Naves Reales) fue fundada por los Fieles de Númenor en la S.E. 2350 y llegó a ser el puerto principal y la ciudad más antigua de Gondor, construida sobre el Anduin en la desembocadura del Sirith. Sirvió de base para la gran flota de Gondor y fue el puerto comercial principal del reino, segunda ciudad solo después de Minas Tirith.', '880eec93a3c2b8ebcf3a15446efc8c72', ST_GeomFromText('POINT(16.156195 41.256614)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (557, 'Metraith', 'town', 340, '70% Cardolani, 30% Eriadoran', 'Founded by Tarcil of Arnor as a summer residence, T.A. 514.. Seat of the Lords of Dol Tinare; a supply center and minor market for traffic on the Greenway.. The Princes of Tinare inhabit a large and crumbling mansion in Metraith.', 'Fundada por Tarcil de Arnor como residencia de verano, T.E. 514.. Asiento de los Señores de Dol Tinare; centro de abastecimiento y mercado menor para el tránsito del Camino Verde.. Los Príncipes de Tinare habitan en Metraith una mansión grande y ruinosa.', '8a30ed251c814ab07981a8f8297d81f0', ST_GeomFromText('POINT(1.30749 49.536729)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (558, 'Endil', 'watchtower', 24, '100% Gondorian', 'Endil is one of the chain of watch-towers maintained by the Prince of Dor-en-Ernil along the Belfalas coast, built by Anárion in the Second Age to warn of pirates and raiders. Its light is visible from ships approaching the rocky shoals; the signal is relayed along the chain to Dol Amroth within minutes. The garrison is small — a handful of men — but their position commands the most exposed stretch of the Belfalas coast.', 'Endil es una de las torres de vigilancia que el Príncipe de Dor-en-Ernil mantiene a lo largo de la costa de Belfalas, construida por Anárion en la Segunda Edad para dar aviso de piratas y saqueadores. Su luz se ve desde los barcos que se acercan a los bajíos rocosos; la señal se transmite por la cadena hasta Dol Amroth en minutos. La guarnición es pequeña — un puñado de hombres — pero su posición domina el tramo más expuesto de la costa de Belfalas.', '8c148f9d1af8d5cf47a5659fc57cb055', ST_GeomFromText('POINT(9.822337 40.148109)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (559, 'Tir Eiliant', 'manor', 30, 'Gondor', 'The lordly seat of Anfalas, traditional home of the provincial governor (Cáno). A stone manor house and associated buildings in a defensible position overlooking Anfalas; the Cáno''s household and administrative staff maintain it as the principal seat of authority for the coastal plain.', 'El asiento señorial de Anfalas, hogar tradicional del gobernador provincial (Cáno). Una casa señorial de piedra y los edificios anexos, en una posición defendible que domina Anfalas; la casa del Cáno y su personal administrativo la mantienen como sede principal de la autoridad en la llanura costera.', '8db29c09f4bbb933338abeb89a583e7a', ST_GeomFromText('POINT(1.927719 41.294802)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (560, 'Archet', 'village', 100, '80% Bree-men (Northman/Dunnish Mix), 20% Stoor Hobbit (Kuduk)', 'Archet lies on the edge of the Chetwood in Bree-land, founded by settlers from the main Bree community in T.A. 1420. It is a purely agricultural village, devoted to growing grain and vegetables for the local market. Low stone-and-timber farmhouses face the road; the Chetwood stands dark and close to the east. Archet folk are generally more suspicious of strangers than Bree itself, and the village has a quiet, self-contained character.', 'Archet queda en el linde del Bosque de Chet, en las Tierras de Bree, fundada por colonos venidos de la comunidad principal de Bree en la T.E. 1420. Es una aldea puramente agrícola, dedicada a cultivar cereal y verduras para el mercado local. Casas de labranza bajas, de piedra y madera, dan al camino; el Bosque de Chet se alza oscuro y cercano al este. La gente de Archet suele desconfiar de los forasteros más que la de Bree misma, y la aldea tiene un carácter callado y cerrado sobre sí.', '8ded0d2f712cc9da8128283409069cd1', ST_GeomFromText('POINT(1.345125 51.628198)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (562, 'Gundabad', 'dwarven mine', 2400, 'Orcs', 'Mount Gundabad was a sacred site of the Dwarves and an important enclave in the northern Misty Mountains. It was seized by Orcs multiple times and eventually became the capital of the northern Orc-realm, a constant threat to the free peoples of the north.', 'El Monte Gundabad era un sitio sagrado de los Enanos y un enclave importante del norte de las Montañas Nubladas. Fue tomado por los orcos varias veces y acabó convertido en la capital del reino orco septentrional, una amenaza constante para los Pueblos Libres del norte.', '8f218bbd2ef709fe97a98279b6093117', ST_GeomFromText('POINT(11.477501 54.99107)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (563, 'Caras Celairnen', 'town', 400, '85% Dúnadan, 15% Riverman', 'First settled around T.A. 740.. A regional market town in southwestern Arthedain.. Caras Celairnen is the westernmost center of purely Dúnadan culture in the North.', 'Poblada por primera vez alrededor de la T.E. 740.. Pueblo de mercado regional en el suroeste de Arthedain.. Caras Celairnen es el centro de cultura puramente dúnadan más occidental del Norte.', '8f5a68e82d9b9a94bfb81074f2fb2e3a', ST_GeomFromText('POINT(-3.759837 52.927546)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (564, 'Nadior', 'ruins', '', 'Ruined city. Nadior was a settlement of Ethir Gwathló in Cardolan, in a small bay on the Minhiriath coast about seventy miles west of the Gwathló mouths. It had a population of roughly 4,900 in T.A. 250, declining through the mid-Third Age until finally abandoned by T.A. 1640.', 'Ciudad en ruinas. Nadior era un asentamiento de Ethir Gwathló, en Cardolan, en una bahía pequeña de la costa de Minhiriath, unas setenta millas al oeste de las bocas del Gwathló. Tenía una población de unos 4.900 habitantes en la T.E. 250, que fue decayendo a mediados de la Tercera Edad hasta quedar abandonada hacia la T.E. 1640.', '9254774f94d07810d84b2ef9222dec09', ST_GeomFromText('POINT(-2.601318 46.65052)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (565, 'Fanuilond', 'town', 750, '100% Gondorian', 'Fanuilond is a Gondorian fishing village on the Ethir Anduin, occupied continuously since the early Third Age and repeatedly targeted by Corsair raids. Its prime location at the mouth of the Anduin keeps drawing people back despite the danger; the fishermen here are experienced and tough, and the harbour — though small — handles a surprising volume of river trade. The town''s walls have been rebuilt more than once.', 'Fanuilond es una aldea de pescadores gondoriana en el Ethir Anduin, ocupada sin interrupción desde comienzos de la Tercera Edad y blanco repetido de las incursiones de los Corsarios. Su posición inmejorable en la desembocadura del Anduin sigue trayendo gente de vuelta a pesar del peligro; los pescadores de aquí son experimentados y duros, y el puerto — pequeño como es — mueve un volumen sorprendente de comercio fluvial. Las murallas del pueblo se han reconstruido más de una vez.', '92d9b509c5a7e1e5217182f663f52897', ST_GeomFromText('POINT(13.114289 40.660615)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (567, 'Tirith Nindir', 'castle', 60, 'Gondor', 'An ancient Gondorian fortress built to protect and guard the approaches to the Dagorlad plain.', 'Una antigua fortaleza gondoriana construida para proteger y vigilar los accesos a la llanura de la Dagorlad.', '9359778ea1b205b6557d2baf08c3ab0a', ST_GeomFromText('POINT(17.905348 45.591355)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (568, 'Lond Angren', 'city', 2300, 'Gondor', 'Lond Angren (S. Iron Port) began as a small Númenórean outpost of the Second Age and grew into a city and lordship controlling western Enedwaith near the mouth of the River Angren.', 'Lond Angren (S. Puerto de Hierro) empezó como un pequeño puesto numenóreano de la Segunda Edad y creció hasta ser una ciudad y un señorío que controlaba el oeste de Enedwaith, cerca de la desembocadura del río Angren.', '93b9a677e74f4de70c374ef9b4d1f3d5', ST_GeomFromText('POINT(0.26102 45.144004)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (569, 'Dunlostir', 'town', 880, '90% Gondorian, 10% Dunman', 'Dunlostir is the centre of the cereal trade for central Calenardhon, with a market recorded since T.A. 808. Grain from the surrounding plains is gathered and stored here before being shipped east or south. The town''s granaries are its most prominent buildings — large stone structures that dwarf the modest houses around them. On market days the roads leading in are busy with carts and droves.', 'Dunlostir es el centro del comercio de cereal del centro de Calenardhon, con un mercado registrado desde la T.E. 808. El grano de las llanuras vecinas se junta y se guarda aquí antes de embarcarse hacia el este o el sur. Los graneros del pueblo son sus edificios más prominentes — grandes estructuras de piedra que empequeñecen las casas modestas de alrededor. Los días de mercado, los caminos de entrada se llenan de carros y de arreos de ganado.', '9419384092d93b36f57a999d75f061bd', ST_GeomFromText('POINT(8.671436 46.206903)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (570, 'Tir Lawen', 'city', 600, '', 'Tir Lawen is a Noldorin Elvish city in the northern wilds, its tall spires visible from the surrounding hills as a point of light in an otherwise dark landscape. Founded in the early Third Age as an Elvish refuge, it is one of the few places of Noldorin habitation outside Lindon and Imladris. The city''s stonework is of exceptional quality; its halls are bright and its people reserved toward mortal strangers.', 'Tir Lawen es una ciudad élfica noldorin de las tierras salvajes del norte; sus agujas altas se ven desde las colinas de alrededor como un punto de luz en un paisaje por lo demás oscuro. Fundada a comienzos de la Tercera Edad como refugio élfico, es uno de los pocos lugares de asentamiento noldorin fuera de Lindon e Imladris. La piedra labrada de la ciudad es de calidad excepcional; sus salones son luminosos y su gente, reservada con los forasteros mortales.', '96e3c8c5ca8e87d9f19586a2defc791a', ST_GeomFromText('POINT(-9.050462 51.986118)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (571, 'Onodrith', 'town', 1100, '95% Gondorian, 5% Dunnish', 'Onodrith grew around a ferry crossing of the Entwash in the tenth century of the Third Age, receiving a royal charter in T.A. 1240. It is a small market town and local administrative centre, handling most of the river traffic moving between Gondor''s northern and western provinces. Stone warehouses and timber wharves line the riverside; the ferryman''s charges are posted on a board at the landing.', 'Onodrith creció alrededor de un cruce en balsa del Entaguas en el siglo décimo de la Tercera Edad, y recibió fuero real en la T.E. 1240. Es un pueblo de mercado pequeño y centro administrativo local, que maneja casi todo el tránsito fluvial entre las provincias del norte y del oeste de Gondor. Depósitos de piedra y muelles de madera bordean la ribera; las tarifas del balsero están anotadas en un tablero junto al embarcadero.', '97426ecfc7ddec460434e0391aa40aee', ST_GeomFromText('POINT(11.433006 45.72867)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (572, 'Cor Angaladh', 'point of interest', 0, 'Silvan Elves', 'A ritual burial ground, now long disused. Once one of the most sacred sites of the Northmen, this place is now shadowed by the darkness of Mirkwood. Men of the north avoid it, believing it to be cursed.', 'Un terreno ritual de enterramiento, en desuso desde hace mucho. Antaño uno de los sitios más sagrados de los Hombres del Norte, hoy está ensombrecido por la oscuridad del Bosque Negro. Los hombres del norte lo evitan porque lo creen maldito.', '97e0564175cce6367da1abe875f4d424', ST_GeomFromText('POINT(19.715491 50.24128)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (573, 'Osgar', 'manor', 40, '', '98297a9393f615d3791c0ba38ac4bd4f', ST_GeomFromText('POINT(2.03246 42.157703)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (574, 'Dale', 'town', 570, '100% Northman', 'Dale is a handsome town of Urban Northmen set in a sheltered valley beneath the Lonely Mountain, seat of the Thyn and a manufacturing centre for the rural Northmen of the region. Its stone houses and workshops are famous for their fine toys and clockwork mechanisms; market-day brings traders from as far as Esgaroth and beyond. The mountain behind the town gives it a dramatic backdrop and a sense of permanence.', 'Valle es un pueblo hermoso de Hombres del Norte urbanos, asentado en un valle abrigado al pie de la Montaña Solitaria; es la sede del Thyn y un centro manufacturero para los Hombres del Norte rurales de la región. Sus casas de piedra y sus talleres son famosos por los juguetes finos y los mecanismos de relojería; el día de mercado trae comerciantes desde Esgaroth y más allá. La montaña que se alza detrás del pueblo le da un fondo imponente y una sensación de permanencia.', '9d8352b354ce40ca566050ea40fbc8c1', ST_GeomFromText('POINT(21.273306 53.880945)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (576, 'Rhosgobel', 'point of interest', 1, '100% Ista', 'Built by Radagast around T.A. 1100.. A place of healing and herb-lore; a refuge from Mirkwood; an observation post on Dol Guldur.. Rhosgobel is a simple place formed out of the boughs of a great furry oak tree.', 'Construido por Radagast hacia la T.E. 1100.. Lugar de curación y de saber de las hierbas; refugio frente al Bosque Negro; puesto de observación sobre Dol Guldur.. Rhosgobel es un lugar sencillo formado con las ramas de un gran roble velludo.', '9eb4aada9066b6970cc3fa4b0713f534', ST_GeomFromText('POINT(15.953922 50.443346)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (577, 'Lond Galen', 'city', 5000, 'Gondor', 'The capital of Anfalas and its largest town, set near the mouth of the Celgalen where the river meets the Bay of Belfalas. About 5,000 inhabitants work as merchants, artisans, sailors and officials; most also tend plots outside the town for their daily bread. The town''s major building is the governor''s small manor; a few noble townhouses stand taller than the usual one- or two-storey stone buildings. A fifteen-foot wall (rebuilt in T.A. 1652 after Corsair raids became endemic) encloses the settled area, and a small fort guards the southern approach.', 'La capital de Anfalas y su pueblo más grande, asentado cerca de la desembocadura del Celgalen, donde el río llega a la Bahía de Belfalas. Unos 5.000 habitantes trabajan como mercaderes, artesanos, marinos y funcionarios; casi todos atienden además parcelas fuera del pueblo para su pan diario. El edificio principal es la pequeña casa señorial del gobernador; unas pocas casonas nobles se alzan por encima de las habituales construcciones de piedra de uno o dos pisos. Un muro de quince pies (reconstruido en la T.E. 1652, cuando las incursiones de los Corsarios se volvieron endémicas) encierra la zona poblada, y un fuerte pequeño guarda el acceso sur.', '9fa4fdeaf24042021af167466a61eb0e', ST_GeomFromText('POINT(4.722165 41.290999)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (578, 'Esgaroth', 'town', 910, '90% Northman, 10% Mixed Mannish', 'Esgaroth — the Lake-town — is built on great timber platforms above the Long Lake, connected to land by a single bridge. Founded as a seasonal trading station in the early Third Age, it has grown into the chief market of northern Rhovanion, where goods from Dale, Erebor, the Woodland Realm and the wide plains are exchanged. The platforms creak pleasantly underfoot; smoke from cook-fires drifts across the water; the Master''s Hall rises in the centre of the floating town, its banner visible from the lakeshore.', 'Esgaroth — la Ciudad del Lago — está construida sobre grandes plataformas de madera por encima del Lago Largo, unida a tierra por un solo puente. Fundada como estación comercial de temporada a comienzos de la Tercera Edad, ha crecido hasta ser el mercado principal del norte de Rhovanion, donde se intercambian los productos de Valle, Erebor, el Reino del Bosque y las llanuras anchas. Las plataformas crujen con agrado bajo los pies; el humo de los fogones se arrastra sobre el agua; la Casa del Gobernador se alza en el centro del pueblo flotante, con su estandarte visible desde la orilla.', 'a309e72a5df0d83e90644ac100da32ae', ST_GeomFromText('POINT(21.777269 53.02214)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (579, 'Porosir', 'manor', 34, 'Gondor', 'A Gondorian castle and lordly manor in southwestern Ithilien, on the northern banks of the Poros. It is the western frontier seat of House Faron, whose domain guards this stretch of the borderlands. The castle is a working military manor of dressed stone, its courtyard always busy with horses and men moving on the Poros road.', 'Un castillo y casa señorial gondorianos en el suroeste de Ithilien, sobre las orillas septentrionales del Poros. Es el asiento fronterizo occidental de la Casa Faron, cuyo dominio guarda este tramo de las tierras de frontera. El castillo es una casa señorial militar en servicio, de piedra labrada, con el patio siempre movido por caballos y hombres que van y vienen por el camino del Poros.', 'a5bb5615f0cc150c33a7ad66fcfbbc3f', ST_GeomFromText('POINT(15.440753 40.605991)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (581, 'Tumnogoth Iaur', 'dwarven mine', 112, 'Dwarves', 'The Dwarves of Tumnogath were poor and secretive. Many of their young had emigrated to the distant Iron Hills, and the community stagnated over a few generations. The remaining Dwarven population consisted largely of treasure-seekers and travelling tinkers.', 'Los Enanos de Tumnogath eran pobres y reservados. Muchos de sus jóvenes habían emigrado a las lejanas Colinas de Hierro, y la comunidad se estancó en el lapso de unas pocas generaciones. La población enana que quedaba se componía en buena parte de buscadores de tesoros y de hojalateros ambulantes.', 'a89aa4a2e390d2650f651118a49c1f0c', ST_GeomFromText('POINT(-6.372691 49.954729)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (582, 'Carrock', 'point of interest', 'Beornings', 'Carrock was a great rocky islet in the Anduin, between Iach Iaur and Maethelburg, held in deep spiritual reverence by the Beornings who dwelt nearby. The Anduin was shallow here, allowing a ford near the Carrock, though the swift current made the crossing genuinely dangerous.', 'La Carroca era un gran islote rocoso del Anduin, entre Iach Iaur y Maethelburg, tenido en profunda reverencia espiritual por los beórnidas que vivían cerca. El Anduin era poco profundo aquí, lo que permitía un vado junto a la Carroca, aunque la corriente rápida volvía el cruce verdaderamente peligroso.', 'a93d0de04ea8b6508387274bbf869d77', ST_GeomFromText('POINT(15.064321 52.083825)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (583, 'Druabad', 'village', 206, '', 'a96509f98e363e3b03873960397c0cf8', ST_GeomFromText('POINT(5.446174 42.937788)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (584, 'Osgiliath', 'city', 2500, '90% Gondorian, 10% Mixed Mannish', 'Osgiliath was the founding capital of Gondor, built by Elendil''s sons on both banks of the Anduin at its widest point. Its great dome once housed a palantír; the Bridge of Osgiliath spanned the river in a single graceful arch. The city has suffered enormously — a great part was burned during the Kin-strife and the palantír was lost in the river — and by the mid-Third Age much of it stands abandoned or in ruins. The inhabited quarters on the western bank retain a ghost of former grandeur.', 'Osgiliath fue la capital fundacional de Gondor, construida por los hijos de Elendil en ambas orillas del Anduin, en su punto más ancho. Su gran cúpula albergó un palantír; el Puente de Osgiliath cruzaba el río en un solo arco grácil. La ciudad ha sufrido enormemente — buena parte se quemó durante la Lucha entre Parientes y el palantír se perdió en el río — y hacia mediados de la Tercera Edad mucho de ella está abandonado o en ruinas. Los barrios habitados de la orilla occidental conservan un fantasma de la grandeza anterior.', 'a999feb997c5cbac53d53ceb760be098', ST_GeomFromText('POINT(17.969459 43.351871)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (585, 'Tuckborough', 'town', 320, '', 'Tuckborough was the ancestral seat of the Took family, located in the Green Hill Country of Westfarthing. The surrounding area included the market center of Whitwell, the woodcraft village of Tuckburrow, and Dolwich, which supplied timber and granite to the southern Farthings.', 'Tuckborough era el asiento ancestral de la familia Tuk, en el País de las Colinas Verdes, en la Cuaderna del Oeste. La zona de alrededor incluía el centro de mercado de Whitwell, la aldea de artesanos de la madera de Tuckburrow, y Dolwich, que abastecía de madera y granito a las Cuadernas del sur.', 'b07dfd88fff335d40f4a6ff02e121d97', ST_GeomFromText('POINT(-1.324173 51.341565)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (586, 'Dol Caranthan', 'town', 320, '', 'A town of Anórien on the west bank of the Anduin, north of Cair Andros, seat of the local noble family of House Caranthôn. Its stone houses face the great river, and the ferry landing here sees regular traffic of soldiers and merchants. The Caranthôn family''s hall is the largest building in the settlement.', 'Un pueblo de Anórien en la orilla occidental del Anduin, al norte de Cair Andros, asiento de la familia noble local de la Casa Caranthôn. Sus casas de piedra dan al gran río, y el embarcadero de la balsa ve un tránsito regular de soldados y mercaderes. El salón de la familia Caranthôn es el edificio más grande del asentamiento.', 'b173ca30c3da9f732cc0d30c3dba9b2b', ST_GeomFromText('POINT(17.402856 44.594583)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (587, 'Nothva Rhaglaw', 'town', 840, '90% Hillman, 10% Dunnish', 'Nothva Rhaglaw is the only permanent Hillman town west of the Mitheithel — founded by Broggha of Rhudaur in T.A. 1639 as a trading centre and point of local justice. It is a rough, busy place by the standards of the region: a market where Hillmen, Dúnedain and various others conduct business under the rough authority of Broggha''s appointed men. The buildings are timber-and-daub longhouses; the market square is unpaved and muddy in rain.', 'Nothva Rhaglaw es el único pueblo permanente de los hombres de las colinas al oeste del Mitheithel, fundado por Broggha de Rhudaur en la T.E. 1639 como centro de comercio y sede de la justicia local. Para lo que se acostumbra en la región es un lugar tosco y movido: un mercado donde hombres de las colinas, dúnedain y gente de todo tipo hacen negocios bajo la autoridad ruda de los hombres designados por Broggha. Los edificios son casas largas de madera y barro; la plaza del mercado no está empedrada y se vuelve un barrial con la lluvia.', 'b2d97d738b6c8e1360c928f1f3978a23', ST_GeomFromText('POINT(5.969026 52.908717)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (588, 'Cameth Brin', 'citadel', 630, '60% Hillman, 37% Dunman, 3% Other', 'Captured and enhanced by Dúnedain, T.A. 162.. A stable center of administration for Rhudaur; domination of local Hillman tribes.. Currently, Cameth Brin serves as the seat of the Hillman King Broggha.', 'Tomada y mejorada por los dúnedain, T.E. 162.. Centro estable de administración para Rhudaur; dominación de las tribus locales de hombres de las colinas.. En la actualidad, Cameth Brin es la sede del rey Broggha, de los hombres de las colinas.', 'b45533711c7989e35801d15ea96e34b8', ST_GeomFromText('POINT(7.46718 52.537733)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (589, 'Faemar', 'town', 850, '', 'Faemar was a village set midway along the long, narrow Taur Galen, at a ford crossing the river. The steep valley downstream made farming impossible; villagers subsisted on wild game, berries, herbs, nuts, and wood for charcoal.', 'Faemar fue una aldea situada a mitad de camino a lo largo del largo y angosto Taur Galen, junto a un vado que cruzaba el río. El valle empinado río abajo hacía imposible la agricultura; los aldeanos vivían de la caza silvestre, de bayas, hierbas, nueces y de la madera para carbón.', 'b5e41a73df163d7a3bc0212280694b87', ST_GeomFromText('POINT(-2.750008 54.559393)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (590, 'Ambon Noirinyaron', 'ruins', '', 'Ambon Noirinyaron — once a grand Elvish mansion — is now little more than overgrown foundations and a few standing columns. The dressed stonework suggests a high Elvish craft; vines and moss cover what remains. The place has an air of melancholy stillness.', 'Ambon Noirinyaron — antaño una gran mansión élfica — no es hoy mucho más que cimientos invadidos por la maleza y unas pocas columnas en pie. La piedra labrada indica un oficio de los Altos Elfos; las lianas y el musgo cubren lo que queda. El lugar tiene un aire de quietud melancólica.', 'b721357fafe99eb73f5c980838e5ddf1', ST_GeomFromText('POINT(-2.111696 53.302321)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (591, 'Dol Amroth', 'city', 0, '90% Gondorian, 10% Mixed Mannish', 'Dol Amroth — named for King Amroth of Lórien who drowned offshore in T.A. 1981 — is the great coastal city and seat of the Prince of Dor-en-Ernil. Its white towers rise from a high cliff above the bay; the harbour below is one of Gondor''s finest, home to the warships and tall-masted trading vessels of the southern fleet. The city has an Elvish quality to its older quarters — graceful stonework and the lingering influence of the Elvish settlement that once stood here — while the newer docks ring with the noise of any busy port.', 'Dol Amroth — llamada así por el rey Amroth de Lórien, que se ahogó frente a esta costa en la T.E. 1981 — es la gran ciudad costera y el asiento del Príncipe de Dor-en-Ernil. Sus torres blancas se alzan desde un acantilado alto sobre la bahía; el puerto de abajo es uno de los mejores de Gondor, hogar de los navíos de guerra y de las naves mercantes de altos mástiles de la flota meridional. Los barrios más viejos de la ciudad tienen algo de élfico — piedra labrada con gracia y la influencia persistente del asentamiento élfico que hubo aquí — mientras que los muelles nuevos resuenan con el ruido de cualquier puerto activo.', 'b74257edfb64f85fb7085dc04ae70782', ST_GeomFromText('POINT(9.045753 41.368408)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (592, 'Little Delving', 'village', 120, '50% Harfoot, 25% Stoor, 25% Fallohide', 'Settled during the migration of Hobbits to the Shire, T.A. 1601-1610.. Agricultural community.. Located on the White Downs, Little Delving has a greater preponderance of smials.', 'Poblada durante la migración de los hobbits a la Comarca, T.E. 1601-1610.. Comunidad agrícola.. Situada en las Quebradas Blancas, Cavada Pequeña tiene una proporción mayor de smials.', 'b8e5b03dddef89acb43eb6b4c7704af1', ST_GeomFromText('POINT(-2.512654 51.660837)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (593, 'Lond-in-Telerrim', 'town', 546, 'Noldor', 'A Falathrin Elvish haven on the western coast, home to a community of Telerin Elves who raise sheep and work the sea. In the nearby Taur-in-Telerrim (''Wood of the Teleri'') persistent rumours circulate of a small drake lurking in the deep forest — though no search has ever found its lair. The haven''s whitewashed stone buildings face the water; the smell of lanolin and salt is everywhere.', 'Un puerto élfico falathrin de la costa occidental, hogar de una comunidad de Elfos teleri que cría ovejas y trabaja el mar. En el Taur-in-Telerrim (''Bosque de los Teleri'') cercano corren rumores persistentes sobre un dragón pequeño agazapado en lo profundo del bosque — aunque ninguna búsqueda ha dado nunca con su guarida. Los edificios de piedra encalada del puerto dan al agua; el olor a lanolina y a sal está en todas partes.', 'ba1d1a32cd234ff8a9fa85f54f447d3c', ST_GeomFromText('POINT(-6.863374 50.840027)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (595, 'Stock', 'village', 210, '55% Stoor, 20% Fallohide, 25% Harfoot', 'Stock sits in the fertile Baranduin valley, its well-tended fields producing some of the best mushrooms in the Shire — a fact the locals are quietly proud of. It is a comfortable Stoor-majority village of low stone-and-turf buildings near the river, settled in the early days of the Shire. Travellers on the road to the Bucklebury ferry pass through here, and the smell of fresh earth and mushroom beds is pleasant in damp weather.', 'Stock se asienta en el valle fértil del Baranduin, y sus campos bien trabajados producen algunos de los mejores hongos de la Comarca — un hecho del que los lugareños están calladamente orgullosos. Es una aldea acomodada, de mayoría Fuerte, de edificios bajos de piedra y turba cerca del río, poblada en los primeros días de la Comarca. Los viajeros que van camino a la balsa de Gamoburgo pasan por aquí, y el olor a tierra fresca y a bancales de hongos es agradable con el tiempo húmedo.', 'bcd8fc2e535e21125dcf84c78e30cfe8', ST_GeomFromText('POINT(-0.149413 51.43143)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (596, 'Bar-en-Dinnen', 'point of interest', 432, 'Gondor', 'Bar-en-Dinnen (S. Dwelling on the Dinnen) was a fishing village and river-trading town in southern Ithilien, about sixty miles south of Minas Tirith, at the junction of the Tinnen and Anduin rivers. As the only significant settlement in Harithilien north of Hyarpende, it was an important hub for river commerce between Ithilien and Lebennin.', 'Bar-en-Dinnen (S. Morada sobre el Dinnen) fue una aldea de pescadores y un pueblo de comercio fluvial en el sur de Ithilien, unas sesenta millas al sur de Minas Tirith, en la unión de los ríos Tinnen y Anduin. Al ser el único asentamiento de importancia de Harithilien al norte de Hyarpende, era un nudo importante del comercio fluvial entre Ithilien y Lebennin.', 'bf4f93c27a04a22a4cb95b6e9b2da0ce', ST_GeomFromText('POINT(17.723223 42.143878)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (597, 'Mirolos', 'city', 300, 'Noldor', 'Mirolos (S. Jewel-Dream; also Londalos) was a Noldor settlement founded by followers of the Sons of Fëanor in the first decade of the Second Age, the largest community in the Hûb Conath region. Founded by Maglor before his disappearance, it was burned during the Long Winter when a northern dragon entered the area.', 'Mirolos (S. Sueño de Joya; también Londalos) fue un asentamiento de los noldor fundado por seguidores de los Hijos de Fëanor en la primera década de la Segunda Edad, la comunidad más grande de la región de Hûb Conath. Fundada por Maglor antes de su desaparición, fue incendiada durante el Largo Invierno, cuando un dragón del norte entró en la zona.', 'c02aee9a0462b65512c662491f3b69f8', ST_GeomFromText('POINT(-9.56661 55.290304)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (598, 'Tir Lawen', 'city', 800, 'Noldor', 'c0c86553afc2adf9fb424a578f332bea', ST_GeomFromText('POINT(-11.063029 52.948017)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (599, 'Annon Baran', 'village', 300, '60% Eriadoran, 40% Cardolani (Dúnadan)', 'Settled around T.A. 1200.. Economic hub for western Cardolan; provides fish for region.. Despite its proximity to the Elven land of Harlindon, few of the Cardolani dare cross the river, fearing the spells of the Eldar.', 'Poblada alrededor de la T.E. 1200.. Nudo económico del oeste de Cardolan; provee pescado a la región.. A pesar de su cercanía a la tierra élfica de Harlindon, pocos de los cardolanos se atreven a cruzar el río, por temor a los hechizos de los Eldar.', 'c0da45757ceef624d48f9d947ae16305', ST_GeomFromText('POINT(-4.147863 48.98546)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (600, 'Forondir', 'ruins', '', 'Forondir has been a ruin for long enough that the locals no longer know its original name. Only broken walls and overgrown plazas remain of what must once have been a city of some importance.', 'Forondir es una ruina desde hace tanto que los lugareños ya no conocen su nombre original. De lo que debió de ser una ciudad de cierta importancia solo quedan muros partidos y plazas cubiertas de maleza.', 'c2392ab49a7d6e2b9754ceb14dfb2040', ST_GeomFromText('POINT(-3.382325 47.966594)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (601, 'Anhamar', 'point of interest', '', 'The highland above the Anghir Vale where Anghul fortress stands — bleak moorland and dark rock, swept by the winds that give Anghul its name. No settlement of note, only military outposts and the occasional patrol of the Witch-king''s men watching the No Man''s Land.', 'La tierra alta que se extiende sobre el Valle del Anghir, donde se alza la fortaleza de Anghul — páramo desolado y roca oscura, barridos por los vientos que le dan su nombre a Anghul. No hay asentamiento de importancia, solo puestos militares y alguna patrulla de los hombres del Rey Brujo vigilando la Tierra de Nadie.', 'c2f3aca4298632ac748eaa0343c9c2b9', ST_GeomFromText('POINT(-8.95062 50.767262)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (603, 'Hobbiton', 'town', 504, 'Hobbits', 'Hobbiton was a prominent Hobbit village in the Westfarthing of the Shire, north of the Great East Road. It was home to Bag End on the Hill — the residence of Bilbo Baggins and later Frodo Baggins.', 'Hobbiton era una aldea hobbit destacada de la Cuaderna del Oeste de la Comarca, al norte del Gran Camino del Este. Allí estaba Bolsón Cerrado, en la Colina — la residencia de Bilbo Bolsón y más tarde de Frodo Bolsón.', 'c4fc66c91d78dea4ab769322dae7aeda', ST_GeomFromText('POINT(-1.265933 51.58473)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (604, 'Pinnornost', 'fortress', 540, '', 'A border fortress of Anfalas guarding the path of the Len Lefnui at the mouth of the Nan-i-Feryth, named for its position on a pine-clad ridge. Pinnornost was built in T.A. 823 to hold the pass on the frontier with the Daen clans of Haerawreigion. A beacon tower communicates with a sister tower thirty miles east. By T.A. 2157 the garrison was judged too costly to maintain; the fortress was locked up and has slowly fallen into disrepair since.', 'Una fortaleza fronteriza de Anfalas que guarda el paso del Len Lefnui a la entrada del Nan-i-Feryth, llamada así por su posición en una loma cubierta de pinos. Pinnornost fue construida en la T.E. 823 para sostener el paso en la frontera con los clanes daen de Haerawreigion. Una torre de fuego se comunica con una torre hermana treinta millas al este. Hacia la T.E. 2157 se juzgó que la guarnición costaba demasiado mantenerla; la fortaleza fue cerrada y desde entonces se ha ido deteriorando poco a poco.', 'c56b60ec340561754e3980f516df9cf7', ST_GeomFromText('POINT(4.501772 43.140756)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (605, 'Vinyathrad', 'city', 800, '', 'Edenathrad (''New Ford'') is a ford and village north of the ancient Sarn Athrad on the Gelion. It replaced the older ford for practical traffic between Forlindon and the eastern lands. The village is a small settlement of stone and timber houses near the riverbank; Amboron is its chieftain. Traders and travellers cross here regularly.', 'Edenathrad (''Vado Nuevo'') es un vado y una aldea al norte del antiguo Sarn Athrad, sobre el Gelion. Reemplazó al vado más viejo para el tránsito práctico entre Forlindon y las tierras del este. La aldea es un asentamiento pequeño de casas de piedra y madera cerca de la ribera; Amboron es su jefe. Comerciantes y viajeros cruzan aquí con regularidad.', 'c63a0fa990a9481746f987be890a420a', ST_GeomFromText('POINT(-10.131963 53.290973)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, external_id, geom) VALUES (606, 'Caborlad', 'point of interest', '', 'c66de1535d5084394d382b401eb3ed69', ST_GeomFromText('POINT(8.681894 42.644397)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (607, 'Glanhir', 'fortified town', 1300, '85% Gondorian, 15% Dunnish', 'Received royal charter in T.A. 630, possibly constructed upon Second Age Elvish ruins.. A collecting point for local farmers; an economic center for west-central Gondor; a river port.. Situated at the confluence of the Morthond and Ringló Rivers, Glanhir is considered the Gateway to Anfalas.', 'Recibió fuero real en la T.E. 630, posiblemente construida sobre ruinas élficas de la Segunda Edad.. Punto de acopio de los granjeros del lugar; centro económico del centro-oeste de Gondor; puerto fluvial.. Situada en la confluencia de los ríos Morthond y Ringló, Glanhir se considera la Puerta de Anfalas.', 'c7058608fefce8f43ee84942255feb8b', ST_GeomFromText('POINT(9.614062 42.073163)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, external_id, geom) VALUES (608, 'Erynwaith', 'point of interest', '', 'c954bfcce69f4d05de5e64251168df37', ST_GeomFromText('POINT(-0.389766 45.155728)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (609, 'Amrelor', 'ruins', '', 'Amrelor is a ruin. Whatever purpose this settlement once served, it was abandoned long ago, and the dressed stone walls have been falling for generations. The site is avoided by locals, who consider it unlucky.', 'Amrelor es una ruina. Cualquiera haya sido el propósito de este asentamiento, quedó abandonado hace mucho, y los muros de piedra labrada llevan generaciones cayéndose. Los lugareños evitan el sitio porque lo tienen por lugar de mala suerte.', 'c978f08eddb9e7e5d44df0e1dd8ecf49', ST_GeomFromText('POINT(0.584601 47.809059)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (610, 'Dol Guldur', 'fortress', 250, '90% Orcish, 5% Troll, 5% Other', 'Dol Guldur — ''Hill of Sorcery'' — rises from the southern extremity of Mirkwood on the summit of Amon Lanc, an extinct cinder cone. Since around T.A. 1050 it has been occupied by a power called the Necromancer, who has filled the fortress with Orcs and Trolls and spread a shadow over the southern forest. The hill is wrapped in a permanent gloom; the trees around it are dead or twisted, and Mirkwood''s darkness is deepest in its shadow. No traveller ventures near willingly.', 'Dol Guldur — ''Colina de la Hechicería'' — se alza en el extremo meridional del Bosque Negro, en la cima del Amon Lanc, un cono de cenizas extinguido. Desde alrededor de la T.E. 1050 la ocupa un poder llamado el Nigromante, que ha llenado la fortaleza de orcos y trolls y ha extendido una sombra sobre el sur del bosque. La colina está envuelta en una penumbra permanente; los árboles de alrededor están muertos o retorcidos, y la oscuridad del Bosque Negro es más profunda a su sombra. Ningún viajero se acerca por su voluntad.', 'cba3c1d32999386b7650ada2d73f473c', ST_GeomFromText('POINT(15.813102 49.377965)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (612, 'Serelond', 'city', 1300, 'Gondor', 'A town of Anfalas on the Celgalen, with about 1,300 inhabitants in small industry, local trade and subsistence farming. Stone houses of one or two storeys line the streets; weekly market; annual fair. The town hall is the tallest building. A typical, orderly Gondorian provincial settlement.', 'Un pueblo de Anfalas sobre el Celgalen, con unos 1.300 habitantes dedicados a la industria pequeña, al comercio local y a la agricultura de subsistencia. Casas de piedra de uno o dos pisos bordean las calles; mercado semanal; feria anual. El edificio del concejo es el más alto. Un asentamiento provincial gondoriano típico y ordenado.', 'd051379b25c86cfac253bd6b01cea140', ST_GeomFromText('POINT(4.794315 41.460161)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (613, 'Dol Gwaer', 'fortress', 400, '', 'A lordly manor of the Nan Celgalen in western Anfalas, seat of a minor Gondorian noble family. Its stone hall and outbuildings sit in a wooded valley; the surrounding estate grows grain and raises sheep. A small household of retainers and tenants keeps the manor in order.', 'Una casa señorial del Nan Celgalen, en el oeste de Anfalas, asiento de una familia noble gondoriana menor. Su salón de piedra y las construcciones anexas se asientan en un valle arbolado; la hacienda de alrededor cultiva cereal y cría ovejas. Una casa pequeña de criados y arrendatarios mantiene el lugar en orden.', 'd23f71bd5455ab5a52471ba0e0682dbf', ST_GeomFromText('POINT(4.947357 42.98755)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (616, 'Lond Thalos', 'town', 700, '', 'Lond Thalos (S. Port of Thalos) served as both a medical and herbal community and as a timber port supplying wood to the shipyards of the Grey Havens.', 'Lond Thalos (S. Puerto de Thalos) funcionaba a la vez como comunidad médica y de herbolarios y como puerto maderero que abastecía de madera a los astilleros de los Puertos Grises.', 'd7b271fbd725a19c00232d158a1e71c4', ST_GeomFromText('POINT(-7.539279 51.414853)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (617, 'Scary', 'village', 130, '40% Harfoot, 35% Stoor, 25% Fallohide', 'Scary is a Hobbit mining and quarrying village in the rugged Eastfarthing, supplying most of the tin and copper ore used throughout the Shire. Its stone houses are sturdier than average for Hobbit settlements — the miners prefer solid construction — and the surrounding hills are pocked with mine shafts and quarry faces. The village has a slightly tougher character than most of the Shire: fewer flowers and more mud-boots.', 'Scary es una aldea hobbit de minería y cantería en la agreste Cuaderna del Este, que provee casi todo el mineral de estaño y de cobre que se usa en la Comarca. Sus casas de piedra son más recias que el promedio de los asentamientos hobbit — los mineros prefieren la construcción sólida — y las colinas de alrededor están picadas de pozos de mina y frentes de cantera. La aldea tiene un carácter algo más duro que el resto de la Comarca: menos flores y más botas de barro.', 'd91f5d2806938b5d5e0342181bfff661', ST_GeomFromText('POINT(-0.386569 51.76395)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (618, 'Hornburg', 'fortress', 1600, '100% Gondorian', 'Built soon after the War of the Last Alliance at the end of the Second Age.. Quarters for a large portion of Gondor''s army in Calenardhon; administration and protection of the lands from the Isen Fords to Calmirië.. ''Hornburg'' is a Westron name; most Gondorians refer to the citadel as Ostiras.', 'Construida poco después de la Guerra de la Última Alianza, al final de la Segunda Edad.. Acuartelamiento de buena parte del ejército de Gondor en Calenardhon; administración y protección de las tierras desde los Vados del Isen hasta Calmirië.. ''Cuernavilla'' es un nombre en oestron; la mayoría de los gondorianos llama a la ciudadela Ostiras.', 'db7308c49e9f0be82050b9f695ba8651', ST_GeomFromText('POINT(7.587706 45.859374)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (619, 'Hwalord', 'town', 520, 'Gondor', 'A town in the region, its stone houses and wharves serving the commerce of the surrounding area. Details of its exact character depend on the local economy and lord.', 'Un pueblo de la región, cuyas casas de piedra y muelles atienden el comercio de la zona de alrededor. Los detalles de su carácter dependen de la economía local y de su señor.', 'e11fba538e02b2f688cb4b67ef534ff3', ST_GeomFromText('POINT(-0.466877 44.654769)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (620, 'Elostirion', 'tower', 52, '33% Dúnadan, 66% Eriadoran', 'Built by Gil-galad as a gift to Elendil.. Home to one of the Palantíri.. Elostirion is the tallest and westernmost of the three White Towers in the Emyn Beraid.', 'Construida por Gil-galad como regalo para Elendil.. Alberga uno de los palantíri.. Elostirion es la más alta y la más occidental de las tres Torres Blancas de las Emyn Beraid.', 'e2bf97d453fbf8464e97036d01bec4d4', ST_GeomFromText('POINT(-5.219364 51.638056)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (621, 'Shedûn', 'castle', 940, '100% Angmarean (Mixed Mannish)', 'Shedûn is a Witch-king fortress overlooking the broad plains below Angmar, used for regional administration and as a mustering point for the Orc forces trained on the plain below. Its stone walls are of Angmarim construction — heavy and dark — and the view from the battlements encompasses a vast training ground where Orc companies drill with a grim efficiency.', 'Shedûn es una fortaleza del Rey Brujo que domina las llanuras anchas al pie de Angmar, usada para la administración regional y como punto de reunión de las fuerzas orcas que se instruyen en la llanura de abajo. Sus muros de piedra son de factura angmarim — pesados y oscuros — y la vista desde las almenas abarca un campo de instrucción vasto donde las compañías orcas ejercitan con una eficiencia siniestra.', 'e32e3dba06c560584d99f5162a2c4258', ST_GeomFromText('POINT(6.787443 54.830155)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (623, 'Bar Olchaldor', 'town', 348, '', 'e489b8b32e368a5305d8aa2099c2b4a3', ST_GeomFromText('POINT(15.996778 41.930038)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (624, 'Tharagdonrost', 'city', 800, 'Gondor', 'A city in the region whose size and character make it a significant centre of population and trade.', 'Una ciudad de la región cuyo tamaño y carácter la vuelven un centro importante de población y de comercio.', 'e5c97706503934aef315312d333b8692', ST_GeomFromText('POINT(-0.338978 40.06648)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (625, 'Moria', 'dwarven mine', 60000, '100% Naugrim', 'Moria — Khazad-dûm to the Dwarves — is the greatest Dwarven city ever built, delved beneath three peaks of the central Misty Mountains. In its heyday it housed tens of thousands; even now, with its population much reduced, the inhabited halls are vast and busy with the sound of hammers and the smell of forges. Travellers who have passed through its western gate describe colonnaded halls of astonishing size, veins of mithril visible in the rock face, and a beauty that is severe and magnificent at once.', 'Moria — Khazad-dûm para los Enanos — es la mayor ciudad enana jamás construida, cavada bajo tres picos del centro de las Montañas Nubladas. En su mejor momento albergó a decenas de miles; incluso ahora, con la población muy reducida, los salones habitados son vastos y están movidos por el sonido de los martillos y el olor de las forjas. Los viajeros que han pasado por su puerta occidental describen salones con columnatas de un tamaño asombroso, venas de mithril visibles en la roca, y una belleza a la vez severa y magnífica.', 'e743898b5429b1759f42f3eeedf353a1', ST_GeomFromText('POINT(9.173216 49.128243)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (626, 'Eruimar', 'village', 98, '', 'Eruimar (S. Lonely Home) sat at the foot of the Ramluin (S. Blue Wall), below the easternmost point where the Ered Luin foothills gave way to rocky cliffs. Despite its remote setting, distance rather than forest or enchantment created its isolation. The village held no more than thirty-five households; founded by the Dúnedain, most of its roughly 150 residents were River-men or Northmen by the mid-Third Age.', 'Eruimar (S. Hogar Solitario) se asentaba al pie del Ramluin (S. Muro Azul), bajo el punto más oriental donde las lomas de las Ered Luin daban paso a acantilados rocosos. A pesar de su emplazamiento remoto, su aislamiento venía de la distancia y no del bosque ni de encantamiento alguno. La aldea no tenía más de treinta y cinco casas; fundada por los dúnedain, hacia mediados de la Tercera Edad la mayoría de sus unos 150 habitantes eran Hombres del Río u Hombres del Norte.', 'e835ee53e05d2cfc5578bedc86581b87', ST_GeomFromText('POINT(-5.002044 53.408169)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (627, 'Halifirien', 'watchtower', 100, '100% Gondorian', 'Current tower completed in T.A. 529.. A link in Gondor''s chain of communications in Anórien.. Halifirien rests on the border of Anórien and Calenardhon.', 'La torre actual se terminó en la T.E. 529.. Eslabón de la cadena de comunicaciones de Gondor en Anórien.. Halifirien se asienta en el límite de Anórien y Calenardhon.', 'e901438cd57190a3a650728131f750ba', ST_GeomFromText('POINT(13.655401 44.526185)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (628, 'Derwath', 'village', 250, '20% Gondorian, 80% Dunman', 'Settled by Gondorian pioneers around T.A. 609.. An agricultural community; serves administrative roles in the sparsely populated Westmarch.. The village serves as headquarters to a detachment of rangers.', 'Poblada por pioneros gondorianos alrededor de la T.E. 609.. Comunidad agrícola; cumple funciones administrativas en la escasamente poblada Marca del Oeste.. La aldea sirve de cuartel general a un destacamento de montaraces.', 'eaf84f527feadbff51bfee980db3f493', ST_GeomFromText('POINT(6.088231 45.273966)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (629, 'Ostiras', 'town', 400, '', 'ec4f1479d90b8b2a23c1a63546f45010', ST_GeomFromText('POINT(1.248646 45.852942)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (630, 'Annon Wain', 'city', 2500, '', 'Annon Wain, in the upper Lefnui valley, was a local market center. To the north lay extensive mines whose ore was shipped downriver to Annúlond, while nearby firs from the Ered Nimrais supplied Gondor''s naval yards. The town itself was modest — merchant houses, simple dwellings, and riverside warehouses — with a population of roughly 2,500.', 'Annon Wain, en el valle alto del Lefnui, era un centro de mercado local. Al norte quedaban minas extensas cuyo mineral se embarcaba río abajo hacia Annúlond, mientras que los abetos cercanos de las Ered Nimrais abastecían a los astilleros navales de Gondor. El pueblo en sí era modesto — casas de mercaderes, viviendas sencillas y depósitos junto al río — con una población de unos 2.500 habitantes.', 'ed0fd50f861c8ccd1f7b1374b6c56a6f', ST_GeomFromText('POINT(2.668339 42.90054)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (631, 'Thoronbar', 'ruins', '', 'Thoronbar was a village that did not survive the troubles of the middle Third Age. Its ruins are modest: a handful of stone foundations and a broken well, half-buried in turf on the edge of an old track.', 'Thoronbar fue una aldea que no sobrevivió a los trastornos de mediados de la Tercera Edad. Sus ruinas son modestas: un puñado de cimientos de piedra y un pozo partido, medio enterrados en el pasto al borde de una senda vieja.', 'efc7cfee6d7f026f9b104f1dc82c5aa9', ST_GeomFromText('POINT(-2.408808 53.576487)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (632, 'Cerin Balgrist', 'ruins', '', 'Cerin Balgrist was once a city of consequence, but it has been a ruin for generations. The traveller finds only weathered stone, collapsed gateways and empty squares where a market presumably once met.', 'Cerin Balgrist fue en su momento una ciudad de importancia, pero lleva generaciones en ruinas. El viajero no encuentra más que piedra gastada, portales derrumbados y plazas vacías donde es de suponer que alguna vez hubo mercado.', 'f0d0e1a0ee8699729e955990523bc22c', ST_GeomFromText('POINT(-0.685963 54.322353)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (633, 'Cum Arelaid', 'ruins', 'Gondor', 'Ruins. An ancient burial complex of pre-Númenórean tumuli and stone-lined graves, sacred to the early peoples of the region.', 'Ruinas. Un antiguo complejo funerario de túmulos prenumenóreanos y tumbas revestidas de piedra, sagrado para los primeros pueblos de la región.', 'f2e70b1b048daf0397847538939dace3', ST_GeomFromText('POINT(4.688348 44.257728)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (634, 'Dunmardo', 'town', 111, '', 'A small Gondorian town or large village in central Anórien, seat of the county and ancestral holding of the noble family of the same name. Its Sindarin name means ''West-settlement''. Stone houses, a manor and a small market characterise this orderly provincial settlement.', 'Un pueblo gondoriano pequeño, o una aldea grande, en el centro de Anórien; asiento del condado y solar ancestral de la familia noble del mismo nombre. Su nombre sindarin significa ''asentamiento del oeste''. Casas de piedra, una casa señorial y un mercado pequeño caracterizan a este asentamiento provincial ordenado.', 'f535f1f9c5a9cc4092a0e881020a584b', ST_GeomFromText('POINT(16.458038 44.238871)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (635, 'Min-rimmon', 'watchtower', 75, '100% Gondorian', 'Current tower completed in T.A. 516.. A link in Gondor''s northern communications network.. The fifth beacon in the series was built on a mountain named Rimmon.', 'La torre actual se terminó en la T.E. 516.. Eslabón de la red de comunicaciones septentrional de Gondor.. La quinta almenara de la serie se construyó en una montaña llamada Rimmon.', 'f653065afba6a3d653b812c1d745ebdb', ST_GeomFromText('POINT(14.972117 44.364623)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (636, 'Ethraid Engrin', 'point of interest', '', 'The Fords of Isen were the main crossing point for those traversing the Gap of Rohan, with no bridge spanning the powerful river. The Rohirrim patrolled the area as their primary western gateway; Dunlending hillmen often seized the fords and demanded tolls. Three rows of broad flat stones crossed the waters, with graded horse-fords between them.', 'Los Vados del Isen eran el paso principal para quien atravesaba el Paso de Rohan, ya que ningún puente cruzaba el río caudaloso. Los rohirrim patrullaban la zona como su puerta occidental principal; los hombres de las colinas dunlendinos tomaban los vados a menudo y exigían peaje. Tres filas de piedras anchas y planas cruzaban las aguas, con vados graduados para los caballos entre una y otra.', 'faa489819ad48c1b1b1bb97ec8a4989b', ST_GeomFromText('POINT(7.493416 46.358231)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, external_id, geom) VALUES (637, 'Annodrun', 'ruins', 'Gondor', 'Annodrun was a city that did not survive the troubles of its age. Its ruins are extensive — collapsed walls, empty market squares and the stumps of old columns — but they are uninhabited and slowly disappearing under vegetation.', 'Annodrun fue una ciudad que no sobrevivió a los trastornos de su edad. Sus ruinas son extensas — muros derrumbados, plazas de mercado vacías y los tocones de columnas viejas — pero están deshabitadas y van desapareciendo lentamente bajo la vegetación.', 'fb3ba2c5b31fd725ba4a69888a9480a0', ST_GeomFromText('POINT(1.785819 40.782363)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (638, 'Melburg', 'city', 1200, 'Northmen', 'Maethelburg (Meeting Fort) controlled virtually all trade through the upper Anduin valley and produced large quantities of tin from the lower Hithaeglir mines. Travelers heading west stocked up before crossing the Misty Mountains; those arriving from the east rested here. Built on an artificial mound behind a massive timber palisade, it harbored an unusually high number of spies due to its proximity to Angmar and the Orc-holds of Gundabad.', 'Maethelburg (Fuerte del Encuentro) controlaba prácticamente todo el comercio del valle alto del Anduin y producía grandes cantidades de estaño de las minas bajas de las Hithaeglir. Los viajeros que iban al oeste se abastecían aquí antes de cruzar las Montañas Nubladas; los que llegaban del este descansaban en el pueblo. Construida sobre un montículo artificial detrás de una palizada de madera enorme, albergaba una cantidad inusualmente alta de espías por su cercanía a Angmar y a las fortalezas orcas de Gundabad.', 'fd53c3e33a8c151837e9703ed90efc50', ST_GeomFromText('POINT(14.879038 52.906108)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (639, 'Iach Sarn', 'town', 220, '', 'Iach Sarn clustered about the base of a limestone hill, surrounded by small farms and hardwood groves. On the south bank, just downstream of the main road, lay the ruins of an older village of earth-and-stone construction. Weathered steps led down a rubble embankment to the riverside docks, lined with unpainted ferries and fishing boats.', 'Iach Sarn se apiñaba al pie de una colina de caliza, rodeada de granjas pequeñas y de bosquecillos de madera dura. En la orilla sur, justo río abajo del camino principal, quedaban las ruinas de una aldea más antigua, de construcción de tierra y piedra. Unos escalones gastados bajaban por un terraplén de escombros hasta los muelles de la ribera, donde se alineaban balsas y botes de pesca sin pintar.', 'fe3eeab238fd22a00d7618e979b0b310', ST_GeomFromText('POINT(-0.586982 50.009316)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (640, 'Bar en Dagorath', 'fortress', 80, '', 'ff2232851941e9cd4928cae2dc656891', ST_GeomFromText('POINT(2.105156 55.136498)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (641, 'Carn Dûm', 'fortified town', 5000, '60% Angmarean, 40% Orcish', 'Carn Dûm sits at the northwestern tip of the Misty Mountains, the last great fortress of the Witch-king and the capital of Angmar. Its caverns and tunnels were originally delved by Dwarves; the Witch-king enlarged and fortified them enormously after T.A. 1300. Almost nothing is known of the interior — few of the Free Peoples who have approached it have returned. The mountain above it is perpetually dark with snow-cloud, and the road leading to the gate is guarded at every turn.', 'Carn Dûm se asienta en el extremo noroccidental de las Montañas Nubladas, última gran fortaleza del Rey Brujo y capital de Angmar. Sus cavernas y túneles fueron cavados en origen por Enanos; el Rey Brujo los amplió y fortificó enormemente después de la T.E. 1300. Casi nada se sabe de su interior — pocos de los Pueblos Libres que se han acercado han vuelto. La montaña que se alza encima está siempre oscura de nubes de nieve, y el camino que lleva a la puerta está vigilado en cada curva.', 'a90a43d1458f4bc23cafcc17a8951ca4', ST_GeomFromText('POINT(5.713727520310158 56.040605368313436)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, external_id, geom) VALUES (642, 'Estomar', 'city', 324, 'Noldor', '5324545435545', ST_GeomFromText('POINT(-9.641471810978715 56.4614552500048)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (873, 'Brandy Hall', 'town', 'The traditional Great Smial of the patriarch of the Brandybuck clan and Master of Buckland. Built by Gorhendad Oldbuck around T.A. 2340 after founding Buckland, and greatly expanded over generations by his descendants — most notably Gormadoc ''Deepdelver'' Brandybuck c. T.A. 2800. This vast complex of tunnels and rooms is delved entirely into Buck Hill, with three large front-doors, many side-doors, and about a hundred windows. The ancestral home of the Brandybuck family; childhood home of Frodo Baggins. Inhabitants: 100% Stoor Hobbit.', 'El Gran Smial tradicional del patriarca del clan Brandigamo y Señor de Los Gamos. Construido por Gorhendad Gamoviejo hacia la T.E. 2340, después de fundar Los Gamos, y muy ampliado a lo largo de generaciones por sus descendientes — sobre todo por Gormadoc ''Cavahonda'' Brandigamo, hacia la T.E. 2800. Este complejo vasto de túneles y habitaciones está cavado enteramente en la Colina de los Gamos, con tres puertas de entrada grandes, muchas puertas laterales y unas cien ventanas. Es el hogar ancestral de la familia Brandigamo y el hogar de la infancia de Frodo Bolsón.', 'c65fe8733f68ed0acf9d8657916491a7', ST_GeomFromText('POINT(-0.109475780513291 51.337187824592014)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (874, 'Newbury', 'town', 'A Buckland village, the only one set inland from the Brandywine. Before the completion of the High Hay, it occupied a fortified hilltop; the old tower has since been taken down. Today Newbury is a comfortable Hobbit settlement centred on Gorbuck Hall, delved into the hillside. The Hall keeps some almost-forgotten rooms as a Mathom House for relics of the wars against the Old Forest — old weapons, flame-arrows, and mouldy tomes. One or two Gorbucks in every generation study these things quietly, just in case.', 'Una aldea de Los Gamos, la única asentada tierra adentro desde el Brandivino. Antes de que se terminara el Seto Alto ocupaba una cima fortificada; la torre vieja se desmontó desde entonces. Hoy Newbury es un asentamiento hobbit acomodado, centrado en Gorbuck Hall, cavado en la ladera. El salón conserva algunas habitaciones casi olvidadas como Casa de los Mathoms, con reliquias de las guerras contra el Bosque Viejo — armas viejas, flechas incendiarias y tomos enmohecidos. Uno o dos Gorbuck de cada generación estudian esas cosas en silencio, por si acaso.', '26423f24ed502b4bcd43f6bb8c4fbfe5', ST_GeomFromText('POINT(0.110795383046252 51.445392173867724)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (875, 'Bankling', 'town', 'Known locally as ''Bankling'' and later Whitfurrows, this good-sized Hobbit town sits squarely on the Great East Road in the midst of the best farmland of the Eastfarthing. Heavy wagons cross the Scary Pike at Budge Ford to the north, while a fine wooden bridge takes lighter traffic to Waterbury across the river. The town is known for its corn and flax fields and for the Blushing Ivy Tavern, meeting place of the Brow, Pen and Scroll Society — a bookish Hobbit club with a taste for Elvish lore that gives them a reputation for peculiarity among their neighbours.', 'Conocido en la zona como ''Bankling'' y más tarde como Cauce Blanco, este pueblo hobbit de buen tamaño se asienta de lleno sobre el Gran Camino del Este, en medio de las mejores tierras de labranza de la Cuaderna del Este. Los carros pesados cruzan el Scary Pike por el Vado de Budge, al norte, mientras que un buen puente de madera lleva el tránsito liviano hasta Waterbury, al otro lado del río. El pueblo es conocido por sus campos de cereal y de lino y por la taberna de la Hiedra Ruborosa, lugar de reunión de la Sociedad de la Ceja, la Pluma y el Pergamino — un club hobbit de gente leída con gusto por el saber de los Elfos, lo que les da fama de raros entre sus vecinos.', '9123f084119aaf39753e9c22647f86e5', ST_GeomFromText('POINT(-0.281059651949529 51.57042208785768)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (876, 'Rushy', 'town', 'A riverside village in the Marish, where Rivermen and Stoor Hobbits live uneasily side by side. Euric Thuigildsun, the ancient white-haired patriarch of the local Riverman clans, eyes the new Stoor immigrants with cautious acceptance, hoping for commercial advantage. His rival Thuidimer of nearby Flynettle outmanoeuvres him regularly. Rumours of strange reptilian creatures seen on the marshland trails between Rushy and Flynettle add an uneasy note to an already tense village.', 'Una aldea de ribera en la Marjala, donde Hombres del Río y hobbits Fuertes conviven con cierta incomodidad. Euric Thuigildsun, el anciano patriarca de pelo blanco de los clanes de Hombres del Río del lugar, mira a los nuevos inmigrantes Fuertes con aceptación cautelosa, esperando alguna ventaja comercial. Su rival Thuidimer, de la vecina Flynettle, le gana la mano con regularidad. Los rumores sobre criaturas reptilianas extrañas vistas en las sendas del pantano entre Rushy y Flynettle agregan una nota inquietante a una aldea ya tensa.', '97a83eaeedfbbb530bd4d4e021dd40c6', ST_GeomFromText('POINT(-0.3063138415665 51.24559960169455)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (877, 'Standelf', 'town', 'A small hamlet in southern Buckland, close to the High Hay and the Old Forest. Originally built to house miners working the local delving (''Stangedelf''), it grew into a small Hobbit village of stockbreeders. Most inhabitants are a poorer branch of the Brandybuck clan; the Goldworthies, Gorbucks, Headstrongs and Puddyfoots are other families here. The Old Forest looms to the south.', 'Un caserío pequeño del sur de Los Gamos, cerca del Seto Alto y del Bosque Viejo. Construido en origen para alojar a los mineros que trabajaban la cava local (''Stangedelf''), creció hasta ser una aldea hobbit pequeña de criadores de ganado. La mayoría de sus habitantes son una rama más pobre del clan Brandigamo; los Goldworthy, los Gorbuck, los Headstrong y los Puddyfoot son las otras familias del lugar. El Bosque Viejo se cierne al sur.', 'ecb5d5c8e62a59b813f34f92c8a1a7b9', ST_GeomFromText('POINT(-0.212581431541162 51.23679752011409)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (878, 'Haysend', 'town', 'A small Hobbit village at the southern end of Buckland, where the High Hay meets the Brandywine''s marshy mouth. The Withywindle swamp begins just beyond; Bucklanders from Haysend, Breredon and Grindwall fish these swamps and can be hired to take travellers downriver. Buckland''s shirriffs gather here twice a week to patrol and maintain the High Hay. The settlement is small but watchful, its people accustomed to the odd noises that come from the Old Forest side of the river.', 'Una aldea hobbit pequeña en el extremo sur de Los Gamos, donde el Seto Alto llega a la desembocadura pantanosa del Brandivino. El pantano del Tornasauce empieza justo más allá; los gamunos de Haysend, Breredon y Grindwall pescan en esas ciénagas y se los puede contratar para llevar viajeros río abajo. Los oficiales de Los Gamos se reúnen aquí dos veces por semana para patrullar y mantener el Seto Alto. El asentamiento es pequeño pero está atento, y su gente está acostumbrada a los ruidos raros que llegan desde el lado del Bosque Viejo del río.', 'f2740ff0ee4e682dd42f14fe7788b420', ST_GeomFromText('POINT(-0.201530827107401 51.15005956562732)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (879, 'Flynettle', 'town', 'Flynettle in the mid-Third Age is a rough river-landing and fishing camp on the Anduin — nothing more than a landing stage and a handful of sheds used by riverboat crews. The old Deep Hallow House is a crumbling ruin on the bank, avoided by locals.', 'Flynettle, a mediados de la Tercera Edad, es un embarcadero tosco y un campamento de pesca sobre el Anduin — nada más que una plataforma de atraque y un puñado de galpones que usan las tripulaciones de los botes fluviales. La antigua Deep Hallow House es una ruina que se desmorona en la orilla, y los lugareños la evitan.', '660d56b4a55bdf2e6d25b67a7ab178bd', ST_GeomFromText('POINT(-0.327403633822201 51.14133364945998)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (880, 'Willowbottom', 'town', 'A village in the Eastfarthing of the Shire, near the Baranduin and the Overbourne Marshes. A secret ford used by Elven Wandering Companies lies near here. The village sits on the Elfwood stream close to where the Thistle Brook flows into the Shirebourn — a marshy, willow-edged landscape of low Hobbit cottages and kitchen gardens.', 'Una aldea de la Cuaderna del Este de la Comarca, cerca del Baranduin y de las Marismas de Overbourne. Un vado secreto que usan las Compañías Errantes de los Elfos queda por aquí cerca. La aldea se asienta sobre el arroyo Elfwood, cerca de donde el Thistle Brook desemboca en el Shirebourn — un paisaje pantanoso, orillado de sauces, de cabañas hobbit bajas y huertas.', '9a6e4f2203ee98ab95b6fcba6d34c6ab', ST_GeomFromText('POINT(-0.603914243396946 51.06923781163512)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (881, 'Pincup', 'town', 'A quiet Hobbit woodland village in the Southfarthing. The founding Pendle family are long gone; the Goodbodys are now the most prominent residents, though the Tooks are the main landowners. The village has a reputation for being an unusually secluded and woodsy sort of place, and Sîrrandrai Elvish artefacts occasionally turn up in local mathom collections.', 'Una aldea hobbit tranquila y arbolada de la Cuaderna del Sur. La familia Pendle, que la fundó, desapareció hace mucho; los Goodbody son hoy sus vecinos más prominentes, aunque los Tuk son los principales propietarios de la tierra. La aldea tiene fama de ser un lugar apartado y boscoso como pocos, y de tanto en tanto aparecen artefactos élficos sîrrandrai en las colecciones de mathoms del lugar.', 'fcde32bbf605a675b192c68054fc08e4', ST_GeomFromText('POINT(-1.116981814409183 51.22908454863549)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (882, 'Tookbank', 'town', 'A Hobbit market town in Tookland, associated with the Took family. Its market brings farmers and craftsmen from across the surrounding area on market days.', 'Un pueblo de mercado hobbit en la Tierra de los Tuk, asociado a la familia Tuk. Su mercado trae granjeros y artesanos de toda la zona en los días de feria.', '50e6d0af4c8566c0039a4e37af8e3492', ST_GeomFromText('POINT(-1.514257594710213 51.334302166134286)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (883, 'Whitwell', 'town', 'A small Hobbit village near Tuckborough in the Shire, known for its good wells and its quiet lanes. Taken over by the Tooks around T.A. 1620 and briefly notorious when residents started charging road tolls and detained a King''s Messenger — a stiff fine settled the matter. Paladin Took owns farmland here. The village is small and amiable, though Tooks from Whitwell are reportedly not always welcome at certain fords since the toll incident.', 'Una aldea hobbit pequeña cerca de Tuckborough, en la Comarca, conocida por sus buenos pozos y sus callejones tranquilos. Los Tuk la tomaron a su cargo alrededor de la T.E. 1620, y tuvo una notoriedad breve cuando sus habitantes empezaron a cobrar peaje en el camino y retuvieron a un Mensajero del Rey — una multa dura zanjó el asunto. Paladin Tuk tiene tierras de labranza aquí. La aldea es pequeña y amable, aunque se dice que a los Tuk de Whitwell no siempre los reciben bien en ciertos vados desde el incidente del peaje.', 'b3a13760464ed8b72113797943230c76', ST_GeomFromText('POINT(-1.633772169279555 51.336819792142244)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (884, 'Wood Junction', 'town', 'A Shire village in the Westfarthing, 15 miles west of Bywater on the Great East Road, where the Sarn Ford road meets the main road. Originally called Wood Junction in Arnorian times, later shortened to Waymoot by Hobbits. A natural stopping point: a comfortable inn and a few houses cluster at the crossroads, busy with traffic between Bywater and Bree.', 'Una aldea de la Comarca en la Cuaderna del Oeste, quince millas al oeste de Delagua sobre el Gran Camino del Este, donde el camino del Vado de Sarn se junta con el camino principal. Llamada en origen Wood Junction en tiempos arnorianos, los hobbits lo acortaron más tarde a Waymoot. Es una parada natural: una posada cómoda y unas pocas casas se agrupan en el cruce, con el movimiento del tránsito entre Delagua y Bree.', '50eb2bd6e21331eabe40b3822d3f357d', ST_GeomFromText('POINT(-1.548635046923086 51.465401238033515)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (885, 'Bywater', 'town', 'Settled as a crossroads village by Men of Arthedain in the early Third Age; later resettled during Hobbit migrations to the Shire, T.A. 1601-1610. An agricultural market village at the crossroads of the Great East Road, frequented by traders and travellers passing between Hobbiton and the East Farthing. Bywater lies just north of the Great East Road on the banks of a small pool, and is known for the Green Dragon Inn. Inhabitants (c. T.A. 1640): 50% Harfoot, 40% Fallohide, 10% Stoor; population approx. 360.', 'Poblada como aldea de cruce de caminos por Hombres de Arthedain a comienzos de la Tercera Edad; repoblada más tarde durante las migraciones hobbit a la Comarca, T.E. 1601-1610. Es una aldea agrícola y de mercado en el cruce del Gran Camino del Este, frecuentada por comerciantes y viajeros que van y vienen entre Hobbiton y la Cuaderna del Este. Delagua queda justo al norte del Gran Camino del Este, a orillas de un estanque pequeño, y es conocida por la posada del Dragón Verde.', '1e2601daa09bf65f5c8b09d63001711a', ST_GeomFromText('POINT(-1.13209469050118 51.5659580479751)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (886, 'Overhill', 'town', 'A new Hobbit village north of Screaming Hill, settled by the Fallohide Barleycorn clan and the Harfoot Beechkins, both of whom came to the Shire after being persecuted by brigands. The two clans share a suspicion of Big Folk that occasionally turns hostile; other Hobbits are uneasy about the disappearances of Men who venture into the angle between Baining Stream and Screaming Hill. In later, more peaceful times, Overhill becomes a comfortable farming community; the Bagginses own much of the surrounding land.', 'Una aldea hobbit nueva al norte de Screaming Hill, poblada por el clan Albo de los Barleycorn y los Pelosos Beechkin, que llegaron a la Comarca después de ser perseguidos por bandidos. Los dos clanes comparten una desconfianza hacia la Gente Grande que a veces se vuelve hostil; otros hobbits están incómodos con las desapariciones de Hombres que se aventuran en el ángulo entre el arroyo Baining y Screaming Hill. En tiempos posteriores, más apacibles, Overhill se vuelve una comunidad agrícola acomodada; los Bolsón son dueños de buena parte de la tierra de alrededor.', '5d85a4bd0836ee72c9a7e8f2c3a114a8', ST_GeomFromText('POINT(-1.278787595579377 51.66757438362121)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (887, 'Waterbury', 'town', 'A Hobbit village on the north bank of the Fairwater opposite Bankling, providing access to the Great East Road for miners of the Hills of Scary. It has outgrown its twin settlement as Hobbit migration increased. Later it evolves into the village of Budgeford.', 'Una aldea hobbit en la orilla norte del Fairwater, frente a Bankling, que da acceso al Gran Camino del Este a los mineros de las Colinas de Scary. Ha crecido más que su asentamiento gemelo a medida que aumentó la migración hobbit. Más tarde se convierte en la aldea de Budgeford.', 'fb5c6b2990b5c1f9dd1f7a9cfc696a21', ST_GeomFromText('POINT(-0.268820877556365 51.62395214709121)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (888, 'Woodhall', 'town', 'A Hobbit village in the Eastfarthing on the northern eaves of the Woody End, founded in T.A. 1612 by Harfoots of the Staghorn and Huckle clans on the site of an old Eriadorian village. The earlier settlement was destroyed in T.A. 1409 when Orc wolf-riders slaughtered its inhabitants. The new Hobbit village sits where those same apple orchards still bear fruit and mushrooms grow on shaded terraces. A glade of the Elven Wandering Companies lies nearby; Elves are sometimes seen passing through at dusk.', 'Una aldea hobbit de la Cuaderna del Este, en el linde norte del Boscaje, fundada en la T.E. 1612 por Pelosos de los clanes Staghorn y Huckle sobre el sitio de una vieja aldea eriadorana. El asentamiento anterior fue destruido en la T.E. 1409, cuando los orcos jinetes de lobos degollaron a sus habitantes. La aldea hobbit nueva se asienta donde esos mismos manzanares siguen dando fruto y los hongos crecen en terrazas sombreadas. Cerca hay un claro de las Compañías Errantes de los Elfos; a veces se ve pasar Elfos al anochecer.', '2e86b2f41901c239c3d12ef31492d5c7', ST_GeomFromText('POINT(-0.512120491248156 51.3231202577711)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (889, 'Longbottom', 'town', 'A Hobbit village in the Southfarthing, historically significant as the first place in the Shire where pipe-weed was cultivated. Around S.R. 1070 (T.A. 2670), Tobold Hornblower of Longbottom brought the pipe-weed plant from Bree and began growing it in his gardens, giving rise to the famous ''Longbottom Leaf'' strain. The village lies in a gentle valley of the Southfarthing and its fields are given over largely to pipe-weed cultivation, the primary industry of the region.', 'Una aldea hobbit de la Cuaderna del Sur, históricamente importante por ser el primer lugar de la Comarca donde se cultivó la hierba de pipa. Alrededor del C.C. 1070 (T.E. 2670), Tobold Corneta de Valle Largo trajo la planta desde Bree y empezó a cultivarla en sus jardines, dando origen a la famosa variedad ''Hoja de Valle Largo''. La aldea queda en un valle suave de la Cuaderna del Sur y sus campos están dedicados en buena parte al cultivo de la hierba de pipa, la industria principal de la región.', '6b4893099af8f5f03ba467cbc6af8752', ST_GeomFromText('POINT(-1.35611683385028 50.776765587848494)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (890, 'Brocken Borings', 'town', 'A Hobbit village on the western side of the Hills of Scary, centred on copper and tin mines, some dating to Dwarven miners of the Second Age. Hobbits here — chiefly the Bolger clan — use the old mine shafts as smials, ignoring old Riverman stories that the borings are haunted. There have been inexplicable noises, felt presences and glimpsed faces in the dark passages; in a small shed in the park, ''Neblin-nuggets'' — copper nodules roughly shaped like sleeping Dwarves — are displayed as curiosities. A remote and self-contained Hobbit community.', 'Una aldea hobbit del lado occidental de las Colinas de Scary, centrada en las minas de cobre y estaño, algunas de las cuales se remontan a los mineros enanos de la Segunda Edad. Los hobbits de aquí — sobre todo el clan Bolger — usan los pozos viejos como smials, sin hacer caso de las historias antiguas de los Hombres del Río sobre galerías encantadas. Ha habido ruidos inexplicables, presencias sentidas y caras vislumbradas en los pasadizos oscuros; en un galpón pequeño del parque se exhiben como curiosidades unas ''pepitas de neblin'' — nódulos de cobre con la forma aproximada de Enanos durmiendo. Una comunidad hobbit remota y cerrada sobre sí misma.', '59909f0afcb249dc1d193cbd1a0e997d', ST_GeomFromText('POINT(-0.60625755364758 51.81376537263118)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (891, 'Dwaling Bank', 'town', 'Originally ''Dwola''s Bank'', a streamside village with access to the Brandywine by a stream through a swamp — a relatively unguarded entry from Arthedain. In earlier times Rivermen here baked charcoal and kept quiet, aware of an Elvish community a few miles to the northwest. After Arthedain''s fall, a quiet resolution left the west bank of the Brandywine to the Shire-folk, and the village became a peaceful Hobbit settlement called Dwaling — a stopover for mild-mannered northlanders and a base for river traffic to Rood.', 'En origen ''Dwola''s Bank'', una aldea de ribera con acceso al Brandivino por un arroyo que atraviesa un pantano — una entrada relativamente desguarnecida desde Arthedain. En tiempos anteriores, los Hombres del Río de aquí hacían carbón y no llamaban la atención, sabiendo que había una comunidad élfica unas millas al noroeste. Después de la caída de Arthedain, un acuerdo discreto dejó la orilla occidental del Brandivino a los de la Comarca, y la aldea se convirtió en un asentamiento hobbit apacible llamado Dwaling — parada para gente tranquila del norte y base del tránsito fluvial hacia Rood.', 'be7ec50630795002f7dfbe5b68b303b0', ST_GeomFromText('POINT(-0.165902829267255 51.915630700513084)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (892, 'Combe', 'village', 200, '60% Bree-man, 40% Stoor Hobbit', 'Settled by farmers from Bree in T.A. 1415.. An economic center for those unwilling to trek to Bree; agriculture.. Combe is the most isolated of Bree-land''s villages.', 'Poblada por granjeros de Bree en la T.E. 1415.. Centro económico para quienes no quieren hacer el viaje a Bree; agricultura.. Combe es la más aislada de las aldeas de las Tierras de Bree.', '4a9997e9ddf3c8e1ec038768b7a20760', ST_GeomFromText('POINT(1.40430264139591 51.5959391023737)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (893, 'ruins', 'ruins', '31ff135719880201f7f9afee7e554f57', ST_GeomFromText('POINT(1.358170285176331 51.09140864638483)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (894, 'ruins', 'ruins', '4d7fb89cc5ed5d76e4d0397b3565f561', ST_GeomFromText('POINT(1.315079903477513 50.733689290698386)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (895, 'Nobottle', 'town', 'Nobottle was a small logging village just off the Fairwater road between Little Delving and Bywater. Its Cutters'' Guild was known throughout the Westfarthing.', 'Nobottle era una aldea maderera pequeña, apenas apartada del camino del Fairwater entre Cavada Pequeña y Delagua. Su Gremio de Taladores era conocido en toda la Cuaderna del Oeste.', '0f7c547ffd39849d99de94f2d8d06762', ST_GeomFromText('POINT(-2.077856391045377 51.71224362521898)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (896, 'Long Cleeve', 'town', 'The Shire community with the best access to the Hills of Evendim and the Utter North. Long Cleeve is a lively market town that trades in furs, ivory, antler and deer-hide brought in by Rangers, hill-folk and trappers from beyond the bounds. The Northwatch shirriffs — who carry bows and spears rather than the usual staves — are headquartered here. A coppice nearby shelters a monument to Bandobras Took, hero of the Battle of Greenfields, who is also the town''s most famous former resident.', 'La comunidad de la Comarca con mejor acceso a las Colinas de Evendim y al Norte Extremo. Long Cleeve es un pueblo de mercado animado que comercia en pieles, marfil, asta y cuero de ciervo traídos por Montaraces, gente de las colinas y tramperos de más allá de las fronteras. Aquí tienen su cuartel los oficiales de la Guardia del Norte, que llevan arcos y lanzas en lugar de los bastones de siempre. Un bosquecillo cercano guarda un monumento a Bandobras Tuk, héroe de la Batalla de los Campos Verdes y también el vecino más famoso que tuvo el pueblo.', '73762dd51334e0a11185fa1eab7054d8', ST_GeomFromText('POINT(-2.326247277612521 52.2294150659081)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (897, 'Greenfields', 'town', 'A market centre for the northern Shire, Greenfields also serves as a meeting place for traders from the Twilight Hills and beyond the bounds. When available, trout from Lake Evendim and pike from the upper Brandywine are sold here; fine woolens woven from North Moors sheep are a speciality, made in sizes for Big Folk as well as Hobbits. The town''s Chief Shirriff is tougher than most, dealing with Rangers, Rivermen and hill-trappers who drift in from the north. A coppice east of town shelters a monument to Bandobras Took''s victory over the Goblins of Mount Gram.', 'Centro de mercado del norte de la Comarca, Greenfields sirve además de punto de encuentro para los comerciantes de las Colinas del Crepúsculo y de más allá de las fronteras. Cuando hay, se venden aquí truchas del Lago Evendim y lucios del curso alto del Brandivino; los buenos géneros de lana tejidos con la oveja de los Páramos del Norte son una especialidad, y se hacen en tallas para la Gente Grande además de para hobbits. El Oficial Jefe del pueblo es más duro que la mayoría, porque tiene que tratar con Montaraces, Hombres del Río y tramperos de las colinas que bajan del norte. Un bosquecillo al este del pueblo guarda un monumento a la victoria de Bandobras Tuk sobre los trasgos del Monte Gram.', 'f08cda88f938c90378990ce27b111a25', ST_GeomFromText('POINT(-1.461565795128782 52.41560967590633)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (898, 'town', 'town', 'eba1cbbf1ab59addd3a8766ae556fe3f', ST_GeomFromText('POINT(1.369152987636412 52.957857622794236)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (899, 'Aran Nov', 'town', '35ee86da8a5ce2c05fb8ba1911cb8bee', ST_GeomFromText('POINT(1.404851532016717 52.72494897202548)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (900, 'Dol Occum', 'town', 'A hill-tower on the Men Formen in southern Arthedain, within the village of Occum. The tower is a Dúnedain watch-post commanding the road; the surrounding village of timber and stone houses provides the garrison with supplies. The name derives from an older Westron name meaning ''ox-valley'', and cattle are still the main wealth of the area.', 'Una torre de colina sobre el Men Formen, en el sur de Arthedain, dentro de la aldea de Occum. La torre es un puesto de vigilancia dúnadan que domina el camino; la aldea de alrededor, de casas de madera y piedra, provee de suministros a la guarnición. El nombre viene de un nombre más antiguo en oestron que significa ''valle de los bueyes'', y el ganado sigue siendo la riqueza principal de la zona.', '78d344dbf17b5dc48c3a7f6a9443bdac', ST_GeomFromText('POINT(1.349193122322411 52.255960176185184)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (901, 'ruins', 'ruins', '1a4938c506e6ed19ae0e66731c821538', ST_GeomFromText('POINT(5.048683001237521 51.559819248497654)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (902, 'ruins', 'ruins', 'f6c5dd2f7048657297f73329436d929c', ST_GeomFromText('POINT(6.643338425130473 51.63788293276029)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (903, 'Morva Tarth', 'town', 'The town of Móin Dúldachd (''Marsh of Mist'') shares its name with the surrounding peat bogs of northern Rhudaur. A single track threads the swamp; those who leave it risk hidden bogs that are virtually bottomless. The town itself is the centre of what economic life exists in the Ettendales, and its chief fortification — the Kaldabaurg — was once the citadel of Northman mercenaries who served the Dúnedain. A grim, isolated place.', 'El pueblo de Móin Dúldachd (''Ciénaga de la Niebla'') comparte su nombre con las turberas que lo rodean, en el norte de Rhudaur. Una sola senda atraviesa el pantano; quien la deja se arriesga a ciénagas ocultas que son prácticamente sin fondo. El pueblo en sí es el centro de la poca vida económica que hay en los Valles de los Trolls, y su fortificación principal — el Kaldabaurg — fue en su momento la ciudadela de mercenarios de los Hombres del Norte que sirvieron a los dúnedain. Un lugar sombrío y aislado.', 'c5e33dceafd0ba1254eb7021cfacf7e3', ST_GeomFromText('POINT(7.506295563454326 53.24595472167379)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (904, 'ruins', 'ruins', 'eafe43efbadb6b849703a7bf6c90cac2', ST_GeomFromText('POINT(10.787766882323357 52.84679801592142)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (905, 'Ahus', 'town', 'A rough village of the Fell-men in Angmar, near the fortress of Angsûl. Its squat stone-and-timber huts sit in the shadow of the Witch-kingdom''s northern hills, home to a tribe loyal to the Witch-king. The settlement smells of smoke and animal fat; life here is harsh and martial, and strangers are rarely welcome.', 'Una aldea tosca de los Hombres Crueles de Angmar, cerca de la fortaleza de Angsûl. Sus chozas bajas de piedra y madera se asientan a la sombra de las colinas septentrionales del reino del Rey Brujo, y allí vive una tribu leal a él. El asentamiento huele a humo y a grasa animal; la vida aquí es dura y guerrera, y a los forasteros rara vez se los recibe bien.', '2133416d1765a745d13af9eb9e352eab', ST_GeomFromText('POINT(6.028935284576269 55.620009748829524)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (906, 'Phaluran', 'town', 'A township of the Tulban district of Angmar, built in the mid-Third Age and home to about 3,500 at its peak. The settlement is a rough frontier place — dark timber houses in the shadow of the Angmar hills, its people bound by the Witch-king''s will. With the fall of Angmar, the town is eventually abandoned. By the late Third Age only ruins remain: dark and windswept, avoided by all.', 'Un municipio del distrito de Tulban, en Angmar, construido a mediados de la Tercera Edad y hogar de unos 3.500 habitantes en su mejor momento. El asentamiento es un lugar tosco de frontera — casas de madera oscura a la sombra de las colinas de Angmar, con su gente atada a la voluntad del Rey Brujo. Con la caída de Angmar, el pueblo termina abandonado. Hacia el final de la Tercera Edad solo quedan ruinas: oscuras, batidas por el viento y evitadas por todos.', '7e38a66a4f07efd9be8bc2c055503d9f', ST_GeomFromText('POINT(6.646131166678444 54.68454577015133)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (907, 'Tying Field', 'town', 'A Hobbit village in the Westfarthing, originally called Tying Field — home of the Gamwich, Gammidge and Roper families. The Gamwidge rope-walk is here, and the town''s trade in hemp rope is well known. A ford over the Flexen Stream gives access, though the surrounding Mistvale woods have an unsettling reputation. No inn at the ford.', 'Una aldea hobbit de la Cuaderna del Oeste, llamada en origen Tying Field — hogar de las familias Gamwich, Gammidge y Roper. Aquí está el cordelería de los Gamwidge, y el comercio de cuerda de cáñamo del pueblo es bien conocido. Un vado sobre el arroyo Flexen da acceso al lugar, aunque los bosques vecinos de Mistvale tienen una fama inquietante. En el vado no hay posada.', '65b8a07c66167e4eed1339ee906cf68c', ST_GeomFromText('POINT(-2.751444142252875 51.932871796216546)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (908, 'town', 'town', 'f0c84a451ee0bf4cc8b1ca1922e4c9fa', ST_GeomFromText('POINT(-4.642183553926161 51.60355254875421)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (909, 'Grimsly Dale', 'town', 'A Harfoot farming village located in a bend of the Fairwater River,quiet place, famous for its flowers . Although few remembered it , there had once been a scenic trail in the area that was a popular sidetrip on the Woodland Tour. Reason for its popularity could be discerned in the dense concentration of berry bushes and flowering plants along the riverside paths . The village got its name , however, from the bones of men and horses that also turned up along the trail . A large party of Dúnedain were ambushed here during the Scourging of T.A . 1409 ', 'Una aldea agrícola de Pelosos situada en un codo del río Fairwater, un lugar tranquilo y famoso por sus flores. Aunque pocos lo recordaban, hubo alguna vez en la zona un sendero de paisaje que era un desvío popular del Circuito del Bosque. La razón de esa popularidad se veía en la concentración densa de arbustos de bayas y de plantas en flor a lo largo de los caminos de la ribera. El nombre de la aldea, en cambio, viene de los huesos de hombres y de caballos que también aparecían junto al sendero: una partida grande de dúnedain fue emboscada aquí durante el Azote de la T.E. 1409.', '89d373cfa1cc533ebcf224a90453e632', ST_GeomFromText('POINT(-1.802421935625882 51.74103996842529)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (910, 'Rendwalk and The Briary', 'town', 'Waymoot (originally Wood Junction) is a Shire village in the Westfarthing on the Great East Road, 15 miles west of Bywater, where the main road from Sarn Ford joins the Great East Road. A natural stopping point for travellers; a modest inn and some houses cluster at the crossroads. The name changed from the Arnorian ''Wood Junction'' to the Hobbit ''Waymoot'' over the centuries.', 'Waymoot (en origen Wood Junction) es una aldea de la Comarca en la Cuaderna del Oeste, sobre el Gran Camino del Este, quince millas al oeste de Delagua, donde el camino principal que viene del Vado de Sarn se une al Gran Camino del Este. Es una parada natural para los viajeros: una posada modesta y algunas casas se agrupan en el cruce. El nombre pasó del arnoriano ''Wood Junction'' al hobbit ''Waymoot'' a lo largo de los siglos.', 'fe751621b3441d9f5270cb31b5a5bfcf', ST_GeomFromText('POINT(-2.152652789927937 50.89560176854078)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (911, 'Rond Morvin', 'manor', 'A secluded Arthadan manor in a river-valley west of the North Moors, close to the North Farthing of the Shire. Rond Morvin controls the ford where the Men Lindon crosses the Barluin Stream; it serves as a gathering point for local fairs and militia musters. The manor is a solid stone house with stables and barns, its household accustomed to hosting travellers and muster-parties.', 'Una casa señorial arthedana apartada, en un valle fluvial al oeste de los Páramos del Norte, cerca de la Cuaderna del Norte de la Comarca. Rond Morvin controla el vado donde el Men Lindon cruza el arroyo Barluin; funciona como punto de reunión para las ferias locales y las levas de la milicia. La casa es un edificio sólido de piedra con establos y graneros, y su gente está acostumbrada a alojar viajeros y partidas de leva.', '5187009655be70b5b86e5feac7225b8d', ST_GeomFromText('POINT(-3.127986781343948 52.49349526437371)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (912, 'Ron Hyarr', 'manor', '05390378a9b03062a446fd37d54c9ca8', ST_GeomFromText('POINT(-2.612400525867402 52.55343009105157)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (913, 'Telwaen', 'town', 'Once a large township of 5,000 in the Girithlin highlands of Minhiriath, called Thuilwaen (''Stained helmets''). By T.A. 1400 its population had collapsed and the town was abandoned. What remains today is a ruin amid the highland scrub, its stone walls tumbled and its lanes grown over. Locals do not linger.', 'Fue en su momento un municipio grande, de 5.000 habitantes, en las tierras altas de los Girithlin, en Minhiriath, llamado Thuilwaen (''Yelmos manchados''). Hacia la T.E. 1400 su población se había derrumbado y el pueblo quedó abandonado. Lo que queda hoy es una ruina entre la maleza de las tierras altas, con los muros de piedra caídos y los callejones cubiertos de vegetación. Los lugareños no se demoran ahí.', 'a6b070324a54f2919a1bc9c252dce3ad', ST_GeomFromText('POINT(-2.39537737237395 47.492400213632045)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (914, 'Dinach', 'town', 'A hilltop town in Mintyrnath, two days'' walk northwest of Tharbad. It sits on a strategic spur overlooking the junction of the Sendiel and Andeithel rivers, where an old Arnorian stone bridge still spans the water. In the mid-Third Age, Dinach is a rough waystation: a small garrison holds the old tower, and the stone buildings along the Men Formen shelter travellers, smugglers and agents of various factions. The low-lying fields along the river flood every spring.', 'Un pueblo de cima en Mintyrnath, a dos días de camino al noroeste de Tharbad. Se asienta en un espolón estratégico que domina la unión de los ríos Sendiel y Andeithel, donde un viejo puente arnoriano de piedra todavía cruza el agua. A mediados de la Tercera Edad, Dinach es una posta tosca: una guarnición pequeña ocupa la torre vieja, y los edificios de piedra a lo largo del Men Formen dan cobijo a viajeros, contrabandistas y agentes de una facción o de otra. Los campos bajos junto al río se inundan cada primavera.', 'cea8573a514b0db3d859b68c978b1e84', ST_GeomFromText('POINT(2.324096862485927 49.28939841701387)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (915, 'Vindacil', 'town', '4e34009af319cecbf925dfa46c15b7dd', ST_GeomFromText('POINT(3.505297853911119 48.67361014645488)', 4326));
