INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (928, 'manor', 'manor', '80c28af3905ca4e6aefcfe9fe6f009b0', ST_GeomFromText('POINT(-0.653112456812324 54.22865796974938)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (929, 'manor', 'manor', '0136ed6e661377ad91063cd8190d2a00', ST_GeomFromText('POINT(-2.116293337930732 53.869645519050046)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (930, 'Bauruin', 'ruins', 'Gobel Paurruin (''Village of the Firefist'') was once a thriving township on the Uialduin, about seventy miles northwest of Annúminas. At its height in the early Third Age it held some 3,600 inhabitants. By T.A. 1400 it was abandoned. What a traveller finds today is a ghost of moss-covered foundations and broken walls reclaimed by scrub and willow — locals call it a haunted place and do not linger after dark.', 'Gobel Paurruin (''Aldea del Puño de Fuego'') fue en su momento un municipio próspero sobre el Uialduin, unas setenta millas al noroeste de Annúminas. En su mejor momento, a comienzos de la Tercera Edad, tenía unos 3.600 habitantes. Hacia la T.E. 1400 estaba abandonado. Lo que el viajero encuentra hoy es un fantasma de cimientos cubiertos de musgo y muros partidos recuperados por la maleza y los sauces — los lugareños lo tienen por lugar encantado y no se quedan después del anochecer.', '9899ed13d73e0b58b624def471fd7567', ST_GeomFromText('POINT(-2.012310940287799 53.59577591554835)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (931, 'manor', 'manor', '1288814c3964d02f63905f2cf0d1287b', ST_GeomFromText('POINT(-1.990028997935742 53.40433269559471)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (932, 'Azaghâl''s Anvil', 'inn', '8c39448e7c69258c6c93117556c0be35', ST_GeomFromText('POINT(0.378046319813423 54.62042696646072)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (933, 'manor', 'manor', '047c7c4e70dd2290d17b4ec62d61f0aa', ST_GeomFromText('POINT(0.514213745298216 54.91180081036859)', 4326));
