INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (935, 'Rond Orro', 'manor', 'A manor in the region, its character and household determined by its local lord.', 'Una casa señorial de la región, cuyo carácter y cuya gente dependen del señor local.', 'e482620a843795dc5e4be45e9e563745', ST_GeomFromText('POINT(-2.032736054110517 52.853218651896334)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (936, 'Ralt''s Corner', 'inn', '4cf4d38a9f94a2053ae3a643f12c47bc', ST_GeomFromText('POINT(-2.124339594891196 53.19422888013508)', 4326));
