INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (950, 'manor', 'manor', 'b769f36d70cf709d5901676bfd21ae13', ST_GeomFromText('POINT(-10.724372648073002 51.002720127355516)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (951, 'Lildamar', 'town', 'A town in the region whose character is shaped by local geography and trade routes.', 'Un pueblo de la región, cuyo carácter está moldeado por la geografía del lugar y por las rutas de comercio.', '0afa0111fc8fe16dc74d33e526e09bac', ST_GeomFromText('POINT(-10.139348391506788 49.42880451498685)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (952, 'town', 'town', 'c0a7cd228052be946fde38f68925591c', ST_GeomFromText('POINT(-9.299397363922894 49.45926302421696)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (953, 'Linnuis', 'town', '0c1f8bf2005507bd37574af5151bd761', ST_GeomFromText('POINT(-3.035171153018341 47.25729219880642)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (954, 'Ilfin', 'town', 'Once a township of 3,100 on the coast of Cardolan, Dol Ilfin was abandoned by T.A. 1640 following the Great Plague and regional collapse. A traveller arriving here in the mid-Third Age finds only weather-beaten ruins on the coastal slope — empty windows in crumbling walls, and gulls nesting where people once lived.', 'Antaño un municipio de 3.100 habitantes en la costa de Cardolan, Dol Ilfin quedó abandonado hacia la T.E. 1640, tras la Gran Plaga y el derrumbe de la región. El viajero que llega aquí a mediados de la Tercera Edad no encuentra más que ruinas curtidas por el clima en la ladera costera — ventanas vacías en muros que se desmoronan, y gaviotas anidando donde antes vivía gente.', '09aad3bdfae7f11ae5981f4d0583574e', ST_GeomFromText('POINT(-1.518683694656744 46.85650782519681)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (955, 'Chalnen', 'town', 'A village that served as Saerlann''s northernmost outpost along the Minsiril. In troubled times it is a rough place, known to mercenaries as ''Vice-town'': a refuge for camp-followers, spies, deserters and opportunists. The local chieftain Cyllin does business with whoever pays. Stone huts and muddy lanes; a few alehouses that never close.', 'Una aldea que era el puesto más septentrional de Saerlann a lo largo del Minsiril. En tiempos revueltos es un lugar tosco, conocido entre los mercenarios como ''el pueblo del vicio'': refugio de gente de campamento, espías, desertores y oportunistas. Cyllin, el jefe del lugar, hace negocios con quien pague. Chozas de piedra y callejones de barro; unas pocas cervecerías que no cierran nunca.', '5c24b567891cc2dbe927c73df62b34df', ST_GeomFromText('POINT(-0.385675823467044 48.070219660060765)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (956, 'Carathel', 'town', '82b7f6c436a802ab742ad8e60f2d75c2', ST_GeomFromText('POINT(-2.542748501308971 48.877670933209046)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (957, 'Cor Wilishar', 'town', 'A Nandorin settlement built on a high crag above the Baranduin and the Nenglos. The village was abandoned in the years following the Great Plague and the collapse of Cardolan (c. T.A. 1700). By the mid-Third Age, travellers approaching the crag find only the stone footings of old platforms and the rusted remains of rope-ladders; the Nandor who once lived here are gone.', 'Un asentamiento nandorin construido sobre un risco alto por encima del Baranduin y el Nenglos. La aldea fue abandonada en los años que siguieron a la Gran Plaga y al derrumbe de Cardolan (hacia la T.E. 1700). A mediados de la Tercera Edad, los viajeros que se acercan al risco solo encuentran los apoyos de piedra de las plataformas viejas y los restos herrumbrados de las escalas de cuerda; los nandor que vivieron aquí ya no están.', 'ca0aee863131ced156bc3e8967ad51bd', ST_GeomFromText('POINT(-2.272569701256043 49.48651796209594)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (958, 'Argond', 'castle', 60, '50% Dunman/Eriadoran, 40% Cardolani, 10% Dúnadan', 'Finished by the Prince of Dol Calantir in T.A. 887.. A stronghold and administrative center for rural lordship.. Though it appears formidable, the Argond was not designed with defense in mind. Its questionable defensive arrangement has yet to stand the test of a full siege.', 'Terminado por el Príncipe de Dol Calantir en la T.E. 887.. Plaza fuerte y centro administrativo de un señorío rural.. Aunque parece formidable, el Argond no fue concebido pensando en la defensa. Su discutible disposición defensiva todavía no ha pasado la prueba de un sitio en regla.', '6ec7cdafef836d4596db02e9e426cf77', ST_GeomFromText('POINT(1.698405001134777 48.70254310541345)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (959, 'Undrond', 'town', 'Udûdhrond (''Deep-hidden vault'') was once a township of 4,300 on the west bank of the Gwathló, about eighty miles downriver from Tharbad. By the mid-Third Age its population had collapsed following the Great Plague and by T.A. 1970 the town was fully abandoned. What remains is a stretch of crumbling stone foundations along the riverbank, half-hidden by vegetation — a haunted silence where a busy market once stood.', 'Udûdhrond (''Bóveda oculta y profunda'') fue en su momento un municipio de 4.300 habitantes en la orilla occidental del Gwathló, unas ochenta millas río abajo de Tharbad. Hacia mediados de la Tercera Edad su población se había derrumbado tras la Gran Plaga, y para la T.E. 1970 el pueblo estaba abandonado por completo. Lo que queda es un tramo de cimientos de piedra desmoronados a lo largo de la ribera, medio ocultos por la vegetación — un silencio de lugar encantado donde antes había un mercado movido.', '92de3edf6a912695d755593861823454', ST_GeomFromText('POINT(1.855283014068735 48.225771330158274)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (960, 'Helegnel', 'village', 'Once a free town of Cardolan, Gobel Helegnel was a settlement of some 4,100 people in the early Third Age, lying in the central lands of Dol Tinereb about 110 miles west of Tharbad. By T.A. 1400 its population had dwindled and the town was abandoned. What a traveller finds in the mid-Third Age is a landscape of crumbling stone walls and empty hearths, slowly disappearing under woodland regrowth.', 'Antaño una ciudad libre de Cardolan, Gobel Helegnel fue un asentamiento de unas 4.100 personas a comienzos de la Tercera Edad, en las tierras centrales de Dol Tinereb, unas 110 millas al oeste de Tharbad. Hacia la T.E. 1400 su población había mermado y el pueblo quedó abandonado. Lo que el viajero encuentra a mediados de la Tercera Edad es un paisaje de muros de piedra que se desmoronan y hogares vacíos, desapareciendo poco a poco bajo el bosque que vuelve a crecer.', '69b4ce32c5ecf2d3dae6baef4469264f', ST_GeomFromText('POINT(1.436941646244846 47.9638250125099)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (961, 'Erynwaith', 'town', 'd0d5165b778e4e7958b9b85ca7afe505', ST_GeomFromText('POINT(-0.549090420273252 44.93627356025649)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (962, 'Gwahilmoth', 'town', 'A township of Dol Caladir in Minhiriath, about sixty miles west of Tharbad in the central Baranduinean lowlands. In its prime (T.A. 250) it held some 5,000 souls. However by the mid-Third Age its population had dwindled sharply following the Great Plague and regional instability, and the settlement is largely abandoned by T.A. 1640. A traveller finds a melancholy landscape of empty stone foundations and overgrown lanes where grass pushes through the old cobbles.', 'Un municipio de Dol Caladir, en Minhiriath, unas sesenta millas al oeste de Tharbad, en las tierras bajas centrales del Baranduin. En su mejor momento (T.E. 250) tuvo unas 5.000 almas. Sin embargo, hacia mediados de la Tercera Edad su población había mermado mucho, tras la Gran Plaga y la inestabilidad de la región, y para la T.E. 1640 el asentamiento está abandonado en buena parte. El viajero encuentra un paisaje melancólico de cimientos de piedra vacíos y callejones cubiertos de maleza, donde el pasto empuja entre los adoquines viejos.', '29a4b126976fdccab9c4ed7c88397f9f', ST_GeomFromText('POINT(1.241933560722772 48.61114857042575)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (963, 'Dol Ninden', 'town', 'Dol Nendin (''Hill of Silent Water'') is a settlement in Minhiriath that has changed hands in regional conflicts among the Lords Allied and the Cardolandrim. The town sits on a prominent hill above a quiet tributary, its stone walls bearing the scars of past assaults. In peaceful times it is a modest market centre for the surrounding farmland.', 'Dol Nendin (''Colina del Agua Silenciosa'') es un asentamiento de Minhiriath que ha cambiado de manos en los conflictos de la región entre los Señores Aliados y los cardolandrim. El pueblo se asienta en una colina prominente sobre un afluente tranquilo, y sus muros de piedra llevan las marcas de asaltos pasados. En tiempos de paz es un centro de mercado modesto para las tierras de labranza de alrededor.', '3a69b6cc15d82b466745c6d8a3611f36', ST_GeomFromText('POINT(0.082779354044081 48.29032459528381)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (964, 'town', 'town', '0e1093ca53f16c458c0ecf13de85e251', ST_GeomFromText('POINT(-2.72032569650505 48.48710591824464)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (965, 'Dodind''s Tavern', 'inn', '41855b66d361dcb17f916166c7e57894', ST_GeomFromText('POINT(-7.332055541051707 49.765156129584796)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (966, 'The Zant Shield', 'inn', 'd620864097aa2c283e7cf6a951bf7782', ST_GeomFromText('POINT(-7.176333230867754 49.427246516371504)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (967, 'The Aglahad Blade', 'inn', '0f38276d8edc194d6c669c84167d8c9b', ST_GeomFromText('POINT(-7.189874301318533 49.62208646772963)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (968, 'manor', 'manor', '88cbb23a7d63cd8f11de2696f294fbc2', ST_GeomFromText('POINT(-6.566985060582721 49.68345360877144)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (969, 'Caras Denethora', 'village', '5ef05d4e0b3e2b097a90ccf712703c43', ST_GeomFromText('POINT(-6.420290130699287 49.433117691244256)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (970, 'Dremant Inn', 'inn', 'a6e7dbee08275ead0781039fe12755ba', ST_GeomFromText('POINT(-7.808249851904086 49.60307619397752)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (971, 'manor', 'manor', 'e627c5e94513dacbcda181613bfb4a05', ST_GeomFromText('POINT(-6.95290556842991 49.88454396722463)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (972, 'The Bril Forge', 'inn', '70f134498597eda6d86a936df545843a', ST_GeomFromText('POINT(-6.445115426525713 49.803042711380705)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (974, 'The Éadcwén Mare', 'inn', 'ab37006cce9931a5d0fefa06a909747e', ST_GeomFromText('POINT(-6.307447876942798 49.51230978759738)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (975, 'manor', 'manor', '5a8e3a00c7a8d68e386bd306eb383b5d', ST_GeomFromText('POINT(-6.801332894078707 49.70084105801921)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (976, 'Caras Denethora', 'village', 'An Elvish flet-village of central Harlindon, founded before the rising of the Sun by Danitharo — last king of the Green Elves. Hidden in the trackless ancient woods, it survived the Orc hunts of the First Age unscathed. In the Third Age it looks much as it did at the end of the First Age: wooden platforms and walkways built high among old trees, connected by rope-bridges, visible only when the lanterns are lit at dusk.', 'Una aldea élfica de flets del centro de Harlindon, fundada antes de la salida del Sol por Danitharo — último rey de los Elfos Verdes. Oculta en los bosques antiguos y sin senderos, sobrevivió sin daño a las cacerías de los orcos en la Primera Edad. En la Tercera Edad se ve muy parecida a como estaba al final de la Primera: plataformas y pasarelas de madera construidas en lo alto entre árboles viejos, unidas por puentes de cuerda, visibles solo cuando encienden los faroles al anochecer.', '93bb0145796ef989b735c30c57ada751', ST_GeomFromText('POINT(-7.532914752738256 49.01636703990321)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (977, 'Bar-i-Dinuviel', 'village', 'A fishing village on the coast of Dor Tinuviel, its name meaning ''Home of the Nightingale''. Stone houses with fishing nets hung to dry face a sheltered cove; the people here fish the coastal waters and trade their catch. The village is small and tranquil, known mainly to sailors navigating this stretch of coast.', 'Una aldea de pescadores en la costa de Dor Tinuviel; su nombre significa ''Hogar del Ruiseñor''. Casas de piedra con las redes tendidas a secar dan a una cala abrigada; la gente de aquí pesca en las aguas costeras y comercia con lo que saca. La aldea es pequeña y tranquila, conocida sobre todo por los marinos que navegan este tramo de costa.', '8cd324e78bb439fd5727488315a76b7a', ST_GeomFromText('POINT(-6.972918220725228 48.760747581562775)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (978, 'Rond Rhandir', 'village', 'A village on the northern side of Ram Galen, with about fifty families and 300 inhabitants. Most are farmers — liegemen, tenants or small freeholders growing grain and hay. All houses are single-storey stone buildings of one or two rooms, except for the slightly larger two-storey house of the local noble. In winter, the men go to the nearby woods to cut timber, floating logs downstream to mills in the Morthond valley. A market fair is held outside the village after the sheep-shearing.', 'Una aldea del lado norte del Ram Galen, con unas cincuenta familias y 300 habitantes. Casi todos son granjeros — vasallos, arrendatarios o pequeños propietarios que cultivan cereal y heno. Todas las casas son de piedra, de un piso y una o dos habitaciones, salvo la casa algo más grande, de dos pisos, del noble del lugar. En invierno los hombres van a los bosques cercanos a cortar madera y bajan los troncos flotando hasta los molinos del valle del Morthond. Después de la esquila se hace una feria de mercado fuera de la aldea.', '38a2f9e1b1dba85cdb2dcc8f4843832b', ST_GeomFromText('POINT(7.139960081413626 42.8889300426459)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (979, 'Corgonin', 'town', 'A small town beside a tributary of the Morthond in the eastern Pinnath Gelin, Corgonin takes its name — ''Circle of Stones'' — from a mysterious monument on a nearby knoll: a tall black obelisk surrounded by a ring of twelve grey menhirs. No one knows its origin, and the locals largely avoid it, though straying sheep occasionally wander inside. The town itself is a major winter gathering point for the Mesta sheep-droves; the wool trade dominates spring life, with shearers filling every house and a great fair held outside the walls.', 'Un pueblo pequeño junto a un afluente del Morthond, en el este de Pinnath Gelin. Corgonin toma su nombre — ''Círculo de Piedras'' — de un monumento misterioso en un montículo cercano: un obelisco negro y alto rodeado por un anillo de doce menhires grises. Nadie conoce su origen, y los lugareños lo evitan en general, aunque de tanto en tanto alguna oveja perdida se mete dentro. El pueblo en sí es un punto de reunión importante en invierno para los arreos de ovejas de la Mesta; el comercio de la lana domina la vida en primavera, con los esquiladores llenando todas las casas y una gran feria fuera de los muros.', 'd39427c3ecdaf2b26d3dc778e7f3cd75', ST_GeomFromText('POINT(8.176895341117282 42.31115493851449)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (980, 'town', 'town', '190c825b7d11ff951b9900ef26568f27', ST_GeomFromText('POINT(7.36257363959774 41.67941226638539)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (981, 'Tirith Cobas', 'town', 'An Elvish tower on the western shore of Lond Cobas, founded by Celeborn the Wise as an outpost of Edhellond. It rises atop a tall hill and serves as a lighthouse for passing ships, communicating with Tirith Aear on Dol Amroth across the water by light signals. The tower is used as a meeting place and retreat by the leaders of Edhellond''s kindreds. A traveller approaching by sea sees the light long before the tower itself becomes visible.', 'Una torre élfica en la orilla occidental de Lond Cobas, fundada por Celeborn el Sabio como puesto avanzado de Edhellond. Se alza en la cima de una colina alta y sirve de faro para los barcos que pasan, comunicándose por señales de luz con Tirith Aear, en Dol Amroth, al otro lado del agua. La torre la usan como lugar de reunión y de retiro los líderes de los linajes de Edhellond. El viajero que llega por mar ve la luz mucho antes de que la torre misma se haga visible.', '3bcf02da4072227cedde6d5fd6e4ef5d', ST_GeomFromText('POINT(8.598183234329197 41.62295655254813)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, external_id, geom) VALUES (982, 'Rendûl', 'fortified town', 980, '60% Gondorian, 40% Dunnish', 'Occupied by Gondor since at least T.A. 954, granted a royal charter in T.A. 1187.. Regional trading post on the River Morthond; a defense against Dunnish insurrection.. Rendûl is perhaps the best base for exploration of the interior of Anfalas.', 'Ocupada por Gondor desde por lo menos la T.E. 954; recibió fuero real en la T.E. 1187.. Puesto comercial regional sobre el río Morthond; defensa frente a la insurrección dunlendina.. Rendûl es quizá la mejor base para explorar el interior de Anfalas.', '40413711e840fcd21fd4ca8baa709ead', ST_GeomFromText('POINT(8.57815180508654 43.5070406552782)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (983, 'Nineryn', 'town', 'The Nineryn (''Wetwoods'') are two adjoining, marshy woodlands gathering about the upper Morthond. Foot travel through them is difficult due to the boggy ground; the woods are generally avoided by travellers and claimed as a private hunting preserve by the Lord of Mornan. Poaching is heavily fined. No settlement exists here — the Nineryn are a landmark and a warning to those who leave the road.', 'Los Nineryn (''Bosques Húmedos'') son dos bosques pantanosos contiguos que se juntan alrededor del curso alto del Morthond. Caminar por ellos es difícil por lo cenagoso del terreno; los viajeros los evitan por lo general, y el Señor de Mornan los reclama como coto de caza privado. La caza furtiva se multa con dureza. Aquí no hay asentamiento alguno — los Nineryn son un mojón y una advertencia para quien deja el camino.', '407c900373c7b84fd8645dfe5173129f', ST_GeomFromText('POINT(9.116860465244953 44.13098920852048)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (984, 'Dol Faeren', 'town', 'A Gondorian mountain-town set on a lower foothill of the Dwimorberg overlooking the Morthond Vale. Its stone houses cling to the slope; the people here are farmers and shepherds who work the high pastures. The shadow of the haunted Dwimorberg gives the place a subdued quality; locals keep to old customs and do not speak lightly of the heights above.', 'Un pueblo gondoriano de montaña asentado en una loma baja del Dwimorberg, con vista al Valle del Morthond. Sus casas de piedra se agarran a la pendiente; la gente de aquí son granjeros y pastores que trabajan los pastos altos. La sombra del Dwimorberg encantado le da al lugar un aire contenido; los lugareños se atienen a las costumbres viejas y no hablan a la ligera de las alturas que tienen encima.', '33dc871b7cbb15e4c2a91e9f0be1d1f1', ST_GeomFromText('POINT(9.613039494338228 44.808792945141505)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (985, 'Andram', 'town', '6f87148cfbc679d60cf2b96bd472d1bc', ST_GeomFromText('POINT(11.247743584545619 40.811760972482716)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, external_id, geom) VALUES (986, 'Rul', 'town', 'A town in the region, its stone houses and market serving local farming communities.', 'Un pueblo de la región, cuyas casas de piedra y cuyo mercado atienden a las comunidades agrícolas del lugar.', '9c5ad456482ba2f55dd15dfae0f00a8a', ST_GeomFromText('POINT(22.71094111482394 42.04051328181626)', 4326));
INSERT INTO locations (id, name, location_type, external_id, geom) VALUES (987, 'Estomar', 'town', '51eaec63902d3ff62e258b2afab5b768', ST_GeomFromText('POINT(-12.043793815810359 54.45190209721756)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1045, 'Tolfalas', 'town', 'The island of Tolfalas is a large, remote island guarding the mouth of the Anduin, its geography ranging from rugged coastal cliffs to sheltered inlets. The principal settlement (Gobel Tolfalas) sits at the end of a long firth on the southeastern coast, around a haven that has served as a Gondorian naval base since T.A. 759. Stone houses climb the ridge above the firth; the warden''s small keep overlooks the water. The island''s isolation and strategic position make it a place of passing sailors and military men more than settled farmers.', 'La isla de Tolfalas es una isla grande y remota que guarda la desembocadura del Anduin, con una geografía que va de acantilados costeros agrestes a ensenadas abrigadas. El asentamiento principal (Gobel Tolfalas) queda en el extremo de una ría larga de la costa sudoriental, alrededor de un puerto que sirve de base naval gondoriana desde la T.E. 759. Casas de piedra suben por la loma sobre la ría; el torreón pequeño del guardián domina el agua. El aislamiento y la posición estratégica de la isla la vuelven un lugar de marinos de paso y de hombres de armas más que de granjeros asentados.', ST_GeomFromText('POINT(12.155424336886963 38.83683290538081)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1046, 'Ostara', 'town', 'A small Gondorian town of southeastern Belfalas, considered part of the County of Eregost. Its stone houses face the inland hills; the town serves as a minor administrative centre and market for the surrounding farmland and small estates.', 'Un pueblo gondoriano pequeño del sudeste de Belfalas, considerado parte del Condado de Eregost. Sus casas de piedra miran a las colinas del interior; el pueblo funciona como centro administrativo menor y como mercado de las tierras de labranza y las haciendas pequeñas de alrededor.', ST_GeomFromText('POINT(10.994689211936706 39.71179194827498)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1047, 'Eregost', 'town', 'A harbour-town in southeastern Belfalas and chief settlement of the County of Eregost. Its stone quays face the open waters of the Bay of Belfalas; fishing boats and small trading vessels keep the harbour busy. The town''s houses are whitewashed stone with tiled roofs, and the smell of salt and tar is constant.', 'Un pueblo portuario del sudeste de Belfalas y asentamiento principal del Condado de Eregost. Sus muelles de piedra dan a las aguas abiertas de la Bahía de Belfalas; los botes de pesca y las naves mercantes pequeñas mantienen el puerto movido. Las casas del pueblo son de piedra encalada con techos de teja, y el olor a sal y a alquitrán es constante.', ST_GeomFromText('POINT(11.12220976309949 40.01940894137091)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1048, 'Sarlond', 'town', 'A small Gondorian town on the Cape of Sarlond in northeastern Belfalas, between Thonfalas and Eregost. Its stone houses and small harbour face the open waters of the bay; fishing and coastal trade are the main activities. The cape gives good shelter from westerly storms.', 'Un pueblo gondoriano pequeño en el Cabo de Sarlond, en el nordeste de Belfalas, entre Thonfalas y Eregost. Sus casas de piedra y su puerto pequeño dan a las aguas abiertas de la bahía; la pesca y el comercio de cabotaje son las actividades principales. El cabo da buen abrigo frente a las tormentas del oeste.', ST_GeomFromText('POINT(11.662654003741771 40.350524210017404)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1049, 'Thonfalas', 'town', 'A small coastal town in easternmost Belfalas, on the western part of the Gilrain-Serni bay. Its stone fishermen''s houses face the water; the bay provides good anchorage and rich fishing. The town is a quiet, salt-wind-scoured settlement dependent on the sea.', 'Un pueblo costero pequeño en el extremo oriental de Belfalas, en la parte occidental de la bahía del Gilrain y el Serni. Sus casas de pescadores, de piedra, dan al agua; la bahía ofrece buen fondeadero y pesca abundante. El pueblo es un asentamiento callado, curtido por el viento salado, que depende del mar.', ST_GeomFromText('POINT(11.802319369301012 40.59304416667464)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1050, 'Nargond', 'town', 'A township of Belfalas on the coastal road, roughly halfway between Ráma and Endil. It is the chief settlement of the county of the same name — a modest Gondorian town of stone houses, fishing boats and small trading vessels. The coastal road keeps it connected to the wider economy of Belfalas.', 'Un municipio de Belfalas sobre el camino de la costa, más o menos a mitad de camino entre Ráma y Endil. Es el asentamiento principal del condado del mismo nombre — un pueblo gondoriano modesto de casas de piedra, botes de pesca y naves mercantes pequeñas. El camino de la costa lo mantiene conectado con la economía más amplia de Belfalas.', ST_GeomFromText('POINT(9.825750826277838 40.59765509195068)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1051, 'Rama', 'town', 'A town of Gondor or the coastal region whose character and economy reflect the local geography.', 'Un pueblo de Gondor, o de la región costera, cuyo carácter y cuya economía reflejan la geografía del lugar.', ST_GeomFromText('POINT(9.599583993463288 40.93128500109434)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1052, 'Bar Algund', 'town', 'A small town of western Belfalas, lying close to the great seat of Dol Amroth and within the same Grithion. Bar Algund''s stone houses and small harbour face the Bay of Belfalas; the town relies on fishing and on trade with the Prince''s court nearby.', 'Un pueblo pequeño del oeste de Belfalas, cercano a la gran sede de Dol Amroth y dentro del mismo Grithion. Las casas de piedra y el puerto pequeño de Bar Algund dan a la Bahía de Belfalas; el pueblo vive de la pesca y del comercio con la corte del Príncipe, ahí cerca.', ST_GeomFromText('POINT(9.211428654258464 41.14256950163231)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1053, 'Galibur', 'village', 280, '100% Dunnish', 'Settled during Númenórean expansion in Gondor, circa S.A. 2500.. An important Dunnish ritual site in central Belfalas peninsula.. Ruins dating to the time of the Daen Coentis lie just north of town.', 'Poblada durante la expansión numenóreana en Gondor, hacia la S.E. 2500.. Sitio ritual dunlendino importante en el centro de la península de Belfalas.. Justo al norte del pueblo hay ruinas que se remontan a los tiempos de los Daen Coentis.', ST_GeomFromText('POINT(10.60605515125012 40.820328686075634)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1054, 'Emlin', 'town', 'A small fishing village in the southernmost Angle of Lossarnach, where the river Erui meets the great Anduin. Its stone houses and wooden wharves face the confluence; the people here are fishermen who work the rich waters where the rivers meet. Flat-bottomed boats and nets are spread on every bank.', 'Una aldea pequeña de pescadores en el Ángulo más meridional de Lossarnach, donde el río Erui llega al gran Anduin. Sus casas de piedra y sus muelles de madera dan a la confluencia; la gente de aquí son pescadores que trabajan las aguas ricas del encuentro de los ríos. Hay botes de fondo plano y redes tendidas en cada orilla.', ST_GeomFromText('POINT(17.444037290867254 41.81776630329182)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1055, 'Bar Erui', 'town', 'A mountain hamlet of no more than thirty-five households in the foothills of the Blue Mountains, known as Eruimar or ''Lonely Home''. Though remote, it is easy enough to spot from a distance. Founded as a Dúnedain trading post for trappers and mountaineers, it retains that character in the mid-Third Age, with a small Laughing Brook running through the settlement. The tavern here can fill a long evening with wild tales from the hills.', 'Un caserío de montaña de no más de treinta y cinco casas en las lomas de las Montañas Azules, conocido como Eruimar u ''Hogar Solitario''. Aunque es remoto, se lo divisa con facilidad desde lejos. Fundado como puesto comercial dúnadan para tramperos y montañeses, conserva ese carácter a mediados de la Tercera Edad, con un arroyo pequeño, el Laughing Brook, que atraviesa el asentamiento. La taberna del lugar puede llenar una noche larga con relatos salvajes de las colinas.', ST_GeomFromText('POINT(17.242812557772904 42.05394305494517)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1056, 'Imloth Melui', 'town', 'Imloth Melui (''Sweet flower-valley'') is a fertile valley in Lossarnach dotted with small settlements, orchards and herb-gardens. Its principal settlement is Arnach, seat of Forlong the Fat, Lord of Lossarnach. The valley is famous for its roses and healing herbs; a traveller riding through in spring is struck by the colour and fragrance of the terraced slopes. The Hall of the Gentle Hand and the Hall of Lady Vanyalos are known throughout southern Gondor for their healers.', 'Imloth Melui (''Valle de las flores dulces'') es un valle fértil de Lossarnach salpicado de asentamientos pequeños, huertos y jardines de hierbas. Su asentamiento principal es Arnach, sede de Forlong el Gordo, Señor de Lossarnach. El valle es famoso por sus rosas y por sus hierbas curativas; al viajero que pasa a caballo en primavera lo golpea el color y el perfume de las laderas en terrazas. La Casa de la Mano Suave y la Casa de la Dama Vanyalos son conocidas en todo el sur de Gondor por sus sanadores.', ST_GeomFromText('POINT(16.801591374823325 42.58882090246783)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1057, 'Barad Othnir', 'town', 'A castle and small settlement in northeastern Harithilien, perched on a rocky spur of the western Ephel Dúath. Its tower overlooks the main road below, commanding a view of traffic between Ithilien and Mordor. The castle walls are of dark mountain stone. A small garrison and their families live in the shadow of the keep.', 'Un castillo y un asentamiento pequeño en el nordeste de Harithilien, encaramados en un espolón rocoso del oeste de las Ephel Dúath. Su torre domina el camino principal de abajo y controla la vista del tránsito entre Ithilien y Mordor. Los muros del castillo son de piedra oscura de montaña. Una guarnición pequeña y sus familias viven a la sombra del torreón.', ST_GeomFromText('POINT(18.7738226823858 42.985646316004306)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1058, 'Rianbar', 'town', 'A town of Harithilien, situated south of the Emyn Arnen along the river Dinnen. Its stone houses and market square serve the southern Ithilien farmlands; the Dinnen valley is known for its olive groves and herb gardens, and the town''s small harbour handles river traffic to and from Pelargir.', 'Un pueblo de Harithilien, situado al sur de las Emyn Arnen, sobre el río Dinnen. Sus casas de piedra y su plaza de mercado atienden a las tierras de labranza del sur de Ithilien; el valle del Dinnen es conocido por sus olivares y sus jardines de hierbas, y el puerto pequeño del pueblo maneja el tránsito fluvial desde y hacia Pelargir.', ST_GeomFromText('POINT(18.287231679035013 42.3630800791496)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1059, 'Tir Ethraid', 'town', 1030, '85% Gondorian, 15% Haradan', 'Settled by Gondorians, circa T.A. 930.. Maintain watch over the Crossings of Poros; a trading site; a defense against Haradan incursions.. Tir Ethraid is the frequent target of Haradan raids, but King Tarondor has pledged a good deal of gold to strengthen the town''s resources.', 'Poblada por gondorianos hacia la T.E. 930.. Mantener la vigilancia sobre los Cruces del Poros; sitio de comercio; defensa frente a las incursiones haradanas.. Tir Ethraid es blanco frecuente de las incursiones haradanas, pero el rey Tarondor ha comprometido bastante oro para reforzar los recursos del pueblo.', ST_GeomFromText('POINT(18.071734031143524 40.43043169432147)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1060, 'Aludor', 'town', 'A small town in southwestern Harithilien, set halfway between Hyarpendë and Tir Ethraid on the road through the region. The town is notable as the seat of House Alagdor, one of Ithilien''s ancient noble families, whose home castle Târik-Ûriyat rises on a rocky spur above the surrounding fields and olive groves. Stone houses with tiled roofs line the main road; the air carries the scent of herbs and cultivated terraces.', 'Un pueblo pequeño del suroeste de Harithilien, a mitad de camino entre Hyarpendë y Tir Ethraid, sobre el camino que atraviesa la región. Es notable por ser el asiento de la Casa Alagdor, una de las familias nobles antiguas de Ithilien, cuyo castillo solar, Târik-Ûriyat, se alza en un espolón rocoso sobre los campos y los olivares de alrededor. Casas de piedra con techos de teja bordean el camino principal; el aire trae olor a hierbas y a terrazas cultivadas.', ST_GeomFromText('POINT(17.151897319624798 40.66003195949049)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1061, 'Bar Nepos', 'town', 'A small town and watchtower at the mouth of the river Nethos in southwestern Harithilien, home of the noble house of Nethos. The tower overlooks the river confluence and the road to Pelargir. The town''s houses are compact and stone-built; the watchtower is the tallest structure for miles.', 'Un pueblo pequeño con torre de vigilancia en la desembocadura del río Nethos, en el suroeste de Harithilien, solar de la casa noble de Nethos. La torre domina la confluencia y el camino a Pelargir. Las casas del pueblo son compactas y de piedra; la torre es la estructura más alta en muchas millas.', ST_GeomFromText('POINT(16.859136563949292 40.20720744415561)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1062, 'Bar Morvegil', 'town', 'A small town of Harithilien on a tributary of the Poros, once known as Bar Miruvor (''House of Precious-juice'') and renamed Bar Morvegil (''House of the Black-sword'') when the local noble family took a martial crest. Its stone houses and small river-wharf serve travellers on the Poros road; orchards and herb-gardens cover the gentle slopes around it.', 'Un pueblo pequeño de Harithilien sobre un afluente del Poros, conocido en otro tiempo como Bar Miruvor (''Casa del Jugo Precioso'') y rebautizado Bar Morvegil (''Casa de la Espada Negra'') cuando la familia noble del lugar adoptó un blasón guerrero. Sus casas de piedra y su muelle fluvial pequeño atienden a los viajeros del camino del Poros; huertos y jardines de hierbas cubren las laderas suaves de alrededor.', ST_GeomFromText('POINT(15.837569166073639 40.31566815280704)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1063, 'Hyarpendë', 'town', 'The most important trading town of Harithilien, Hyarpendë (''South Slope'' in Quenya) sits on the east bank of the Anduin opposite Pelargir, at the northern end of the Hyarmentie road. A ferry runs every two hours across to Pelargir, usually packed with merchants, horses and goods. The town has grown from a lazy village into a bustling commercial centre: merchants deal in horses and mules, a coach line runs south along the Poros, and the Five Falcons inn feeds the weary (at high prices). At the town centre stands a thirty-foot Númenórean obelisk marking the road''s end.', 'El pueblo comercial más importante de Harithilien, Hyarpendë (''Ladera del Sur'' en quenya) se asienta en la orilla oriental del Anduin, frente a Pelargir, en el extremo norte del camino Hyarmentie. Cada dos horas cruza una balsa hasta Pelargir, casi siempre cargada de mercaderes, caballos y mercancías. El pueblo pasó de aldea perezosa a centro comercial movido: los mercaderes tratan en caballos y mulas, una línea de diligencias baja hacia el sur por el Poros, y la posada de los Cinco Halcones da de comer al cansado (a precios altos). En el centro del pueblo se alza un obelisco numenóreano de treinta pies que marca el final del camino.', ST_GeomFromText('POINT(16.339469670247333 41.0834098893621)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1064, 'Sindamos', 'manor', 'A lordly manor in western Harithilien, the main settlement of the county of Glorel. Known in Sindarin as Thindamost (''Grey ascending house''), it sits on a gentle slope above the Ithilien farmlands. The manor house is a Gondorian stone hall with outbuildings and enclosed gardens; the surrounding county is known for olives and herbs.', 'Una casa señorial del oeste de Harithilien, asentamiento principal del condado de Glorel. Conocida en sindarin como Thindamost (''Casa gris que asciende''), se asienta en una ladera suave sobre las tierras de labranza de Ithilien. La casa es un salón gondoriano de piedra con construcciones anexas y jardines cerrados; el condado de alrededor es conocido por sus olivas y sus hierbas.', ST_GeomFromText('POINT(17.525082905112818 41.644181518800565)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1065, 'Trenas', 'manor', 'The seat of Tolfalas'' royal warden and the island''s principal settlement (also known as Gobel Tolfalas). Located at the end of a long southeastern firth, with a haven for warships. Stone houses cluster at the foot of a ridge; the warden''s small keep stands on the slope above. The town grew from a military base into a modest civilian settlement during the Third Age, though it remains a place of soldiers and sailors more than merchants.', 'El asiento del guardián real de Tolfalas y el asentamiento principal de la isla (conocido también como Gobel Tolfalas). Queda en el extremo de una ría larga del sudeste, con un puerto para navíos de guerra. Las casas de piedra se apiñan al pie de una loma; el torreón pequeño del guardián se alza en la pendiente de arriba. El pueblo pasó de base militar a asentamiento civil modesto durante la Tercera Edad, aunque sigue siendo un lugar de soldados y marinos más que de mercaderes.', ST_GeomFromText('POINT(18.251671159266273 42.02665847289581)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1066, 'Methir', 'village', 500, '70% Gondorian, 30% Haradan', 'Settled by Gondorians, circa T.A. 970.. A trading center in Harondor, supplying and catering to coastal traffic approaching the Ethir Anduin.. Methir was recently sacked by raiding Haradrim, and the town has yet to recover its role as a way-station for river traffic.', 'Poblada por gondorianos hacia la T.E. 970.. Centro de comercio en Harondor, que abastece y atiende al tránsito costero que se acerca al Ethir Anduin.. Methir fue saqueada hace poco por haradrim en incursión, y el pueblo todavía no ha recuperado su papel de posta para el tránsito fluvial.', ST_GeomFromText('POINT(13.919258724954991 39.90820412818191)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1067, 'Mindo-o-Galad', 'watchtower', ST_GeomFromText('POINT(-2.365252052355574 53.31091547166315)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1068, 'Tir Bronadui', 'manor', 'A Noldor Elvish settlement on the northern coast of Lothlann — the only Elvish community in these chill lands. Originally a village with a tall lamp-house guiding lost sea-farers, it grew into a purely military outpost guarding the route around the Ered Luin into Lothlann and Forlindon. Its stone watchtower is visible for miles along the grey coastline; the Noldor here are few, disciplined and watchful. After the destruction of Angmar (T.A. 1975) the garrison was largely lost trying to rescue Arvedui, and the survivors departed south.', 'Un asentamiento élfico de los noldor en la costa septentrional de Lothlann — la única comunidad élfica de estas tierras frías. En origen fue una aldea con una lampistería alta que guiaba a los navegantes perdidos, y creció hasta ser un puesto puramente militar que guarda la ruta que rodea las Ered Luin hacia Lothlann y Forlindon. Su torre de vigilancia de piedra se ve a millas de distancia a lo largo de la costa gris; los noldor de aquí son pocos, disciplinados y vigilantes. Después de la destrucción de Angmar (T.E. 1975) la guarnición se perdió casi por completo intentando rescatar a Arvedui, y los sobrevivientes partieron hacia el sur.', ST_GeomFromText('POINT(-10.439223367744457 55.88520485402478)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1069, 'Annost', 'watchtower', ST_GeomFromText('POINT(-9.527275348496316 54.21506154089465)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1070, 'Sarn Athrad', 'town', 'Sarn Athrad (''Stone Ford'') is the ancient stony ford of the Dwarves over the river Gelion near the influx of the Rathloriel, across which the old Dwarf Road from the Blue Mountains entered East Beleriand. It was here that the Battle of Sarn Athrad was fought between Elves and Dwarves of Nogrod in the First Age. By the mid-Third Age the old ford has been replaced by Edenathrad a little further north; the original ford is a quiet and wild place, remembered in legend but little-visited.', 'Sarn Athrad (''Vado de Piedra'') es el antiguo vado pedregoso de los Enanos sobre el río Gelion, cerca de la desembocadura del Rathloriel, por el que el viejo Camino de los Enanos entraba desde las Montañas Azules a Beleriand Oriental. Aquí se libró en la Primera Edad la Batalla de Sarn Athrad entre los Elfos y los Enanos de Nogrod. Hacia mediados de la Tercera Edad el vado viejo ha sido reemplazado por Edenathrad, un poco más al norte; el vado original es un lugar tranquilo y salvaje, recordado en la leyenda pero poco visitado.', ST_GeomFromText('POINT(-9.788293220140886 52.95741922729997)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1071, 'lovithil', 'manor', ST_GeomFromText('POINT(-10.720558759301552 52.565874754297745)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1072, 'Tol Ramdal', 'watchtower', 'A small island east of the Gulf of Lhûn in southern Forlindon, serving as the main harbour for High Elves setting out on sea-journeys to southern lands. The island''s small stone quay and beacon-tower are maintained by a handful of Elves; the air here carries the salt of the open sea and the faint music of those about to sail west.', 'Una isla pequeña al este del Golfo de Lhûn, en el sur de Forlindon, que sirve de puerto principal para los Altos Elfos que emprenden viajes por mar a las tierras del sur. El muelle pequeño de piedra y la torre de almenara de la isla los mantiene un puñado de Elfos; el aire trae aquí la sal del mar abierto y la música tenue de quienes están por partir hacia el oeste.', ST_GeomFromText('POINT(-11.160772360967522 51.63047749446025)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1073, 'Vorondrast', 'watchtower', 'A watchtower in Forlindon, maintained as part of the system of watch-posts guarding the coasts and passes of this northwestern Elvish realm. Stone-built and exposed to the elements; a small garrison keeps watch.', 'Una torre de vigilancia de Forlindon, mantenida como parte del sistema de puestos que guardan las costas y los pasos de este reino élfico del noroeste. Es de piedra y está expuesta a los elementos; una guarnición pequeña hace la guardia.', ST_GeomFromText('POINT(-11.740340792510981 52.3938814207865)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1074, 'Amon Ereb', 'watchtower', 'A lone hill of gentle but commanding slopes in southern Forlindon, the highest point between the Ramdal and the Gelion. In the Third Age, the tower of Car Sidh (''House of Peace'') crowns its summit — seat of Rhiannon, a Mithren noblewoman who patronises the largest house of Eldarin healers in Forlindon. About two hundred Elves dwell here; their halls are bright and ordered, and the terraced slopes bear the faint traces of much older First-Age earthworks. The hill is a landmark visible for miles across the flat southern lands.', 'Una colina solitaria de laderas suaves pero dominantes en el sur de Forlindon, el punto más alto entre el Ramdal y el Gelion. En la Tercera Edad, la torre de Car Sidh (''Casa de la Paz'') corona su cima — asiento de Rhiannon, una noble mithren que patrocina la mayor casa de sanadores eldarin de Forlindon. Allí viven unos doscientos Elfos; sus salones son luminosos y ordenados, y las laderas en terrazas conservan las marcas tenues de terraplenes mucho más antiguos, de la Primera Edad. La colina es un mojón visible a millas de distancia a través de las tierras llanas del sur.', ST_GeomFromText('POINT(-10.237892692904689 51.65796643407067)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1075, 'Rhomros', 'manor', 'Rhomros (''Loudfoam'') is a town in Galfalas where the Tauron (Celos) river meets the Bay of Lune. Timber cut from the forests of Forlindon is floated downstream here for ship construction; a small shipyard and sawmill dominate the waterfront. Low stone and timber houses face the bay; the smell of resin and sawdust hangs in the air.', 'Rhomros (''Espuma Sonora'') es un pueblo de Galfalas donde el río Tauron (Celos) llega a la Bahía de Lune. La madera cortada en los bosques de Forlindon baja flotando hasta aquí para la construcción de naves; un astillero pequeño y un aserradero dominan la ribera. Casas bajas de piedra y madera dan a la bahía; el olor a resina y a aserrín queda flotando en el aire.', ST_GeomFromText('POINT(-8.006369655528761 51.78831139179079)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1076, 'Mindon Bron', 'watchtower', 'A watchtower at Caranthir''s Pass in Forlindon, maintained by the Rangers of Lindon to guard the route against intruders coming around the Ered Luin. A small garrison keeps the beacon burning; the tower is a plain stone structure on a windswept ridge with a view of the pass below.', 'Una torre de vigilancia en el Paso de Caranthir, en Forlindon, mantenida por los Montaraces de Lindon para guardar la ruta de los intrusos que vienen rodeando las Ered Luin. Una guarnición pequeña mantiene encendida la almenara; la torre es una estructura de piedra sin adornos en una loma batida por el viento, con vista al paso de abajo.', ST_GeomFromText('POINT(-8.079277149305724 53.69483588129134)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1077, 'Amon Draug', 'point of interest', 'The highest hill in Forlindon, Amon Draug, sat near the mid-point of the Emyn Cûn hills, where the Gelion began. It was possible to see Belegaer from it’s summit.', 'Amon Draug, la colina más alta de Forlindon, se hallaba cerca del punto medio de las colinas Emyn Cûn, donde nacía el Gelion. Desde su cima era posible ver el Belegaer.', ST_GeomFromText('POINT(-11.241786086245078 54.28181404265275)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1078, 'Talanobel', 'town', 'A Nando-Sinda village ruled by descendants of the Guest-elves of Arthorien, Ithilbor''s line. Its name means ''Flet-town''; buildings are set on platforms in the trees above the rapids of a nearby stream which the villagers use for small industries. Light filters through the canopy and the sound of water is constant.', 'Una aldea nando-sinda gobernada por los descendientes de los Elfos Huéspedes de Arthorien, el linaje de Ithilbor. Su nombre significa ''Pueblo de los Flets''; los edificios están asentados en plataformas en los árboles, por encima de los rápidos de un arroyo cercano que los aldeanos usan para sus industrias pequeñas. La luz se filtra por la bóveda de hojas y el sonido del agua es constante.', ST_GeomFromText('POINT(-8.602161750883086 50.77731095498936)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1079, 'Cebir Luin', 'ruins', 'A steep rocky hill south of the Pinnath Luin in Forlindon, site of a battle in S.A. 1700. The hill''s flanks are honeycombed with old Dwarven excavations. By the Third Age it is a ruin: overgrown earthworks, dark dripping tunnels, and travellers passing below glancing up at the jagged stone crest with unease.', 'Una colina rocosa y empinada al sur de las Pinnath Luin, en Forlindon, escenario de una batalla en la S.E. 1700. Sus flancos están agujereados por excavaciones enanas antiguas. Para la Tercera Edad es una ruina: terraplenes cubiertos de maleza, túneles oscuros que gotean, y viajeros que pasan abajo y miran hacia la cresta de piedra dentada con inquietud.', ST_GeomFromText('POINT(-4.121496894915944 49.984710647829694)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1080, 'Tawarobel', 'village', 'The chief settlement of Dor Lelvin, belonging to the manor of Bar Erui at the end of the Ramb Luin. A village of about 150 individuals, mostly mortals with a small Elvish presence; the manor was long associated with Gildor Inglorion''s line. Stone and timber houses sit at the edge of an old Elven estate whose gardens and orchards are still tended with Elvish care.', 'El asentamiento principal de Dor Lelvin, perteneciente a la casa señorial de Bar Erui, en el extremo del Ramb Luin. Una aldea de unas 150 personas, en su mayoría mortales, con una presencia élfica pequeña; la casa señorial estuvo largo tiempo asociada al linaje de Gildor Inglorion. Casas de piedra y madera se asientan al borde de una vieja hacienda élfica cuyos jardines y huertos todavía se atienden con cuidado élfico.', ST_GeomFromText('POINT(-5.948079891192394 52.919803642661755)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1081, 'Barad Caranthit', 'ruins', 'A rocky hilltop in Forlindon south of the Pinnath Luin, honeycombed with old Dwarven excavations. The site of a battle in S.A. 1700 where a band of Dwarves and Elves made a last stand against Orcs. By the Third Age it is a ruin: crumbling walls and overgrown earthworks visited only by the bold or the curious. Old stories say one survivor escaped to rouse a Dwarven host — the tunnels go deeper than they look.', 'Una cima rocosa de Forlindon, al sur de las Pinnath Luin, agujereada por excavaciones enanas antiguas. Es el escenario de una batalla en la S.E. 1700, donde una partida de Enanos y Elfos resistió hasta el final frente a los orcos. Para la Tercera Edad es una ruina: muros que se desmoronan y terraplenes cubiertos de maleza, visitados solo por los audaces o los curiosos. Las historias viejas dicen que un sobreviviente escapó para levantar una hueste enana — los túneles van más profundo de lo que parecen.', ST_GeomFromText('POINT(-6.883275105532636 56.04439167916222)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1082, 'Luithen', 'village', 'A village in Forlindon or the Blue Mountains area, small and quiet; details of its inhabitants and economy are not well documented in current records.', 'Una aldea de Forlindon o de la zona de las Montañas Azules, pequeña y tranquila; los detalles de sus habitantes y de su economía no están bien documentados en los registros actuales.', ST_GeomFromText('POINT(-4.830112141215316 49.54394786522112)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1083, 'Entamundo', 'town', 'A town in the region, its character shaped by local geography and economy.', 'Un pueblo de la región, cuyo carácter está moldeado por la geografía y la economía del lugar.', ST_GeomFromText('POINT(2.563137038649836 48.6927128341211)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1084, 'Alclud', 'village', ST_GeomFromText('POINT(-0.248407562149831 47.195886057386254)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1085, 'Cithiel', 'town', 'Once a great township of 4,400 on the Baranduin in Minhiriath. By T.A. 1400 the old town was abandoned. The site has since been resettled on a smaller scale by Eriadorian tribesmen, who call it Cuncan — a rough cluster of timber-and-daub buildings amid the foundations of the much larger earlier settlement.', 'Fue en su momento un municipio grande, de 4.400 habitantes, sobre el Baranduin, en Minhiriath. Hacia la T.E. 1400 el pueblo viejo estaba abandonado. Desde entonces el sitio ha sido repoblado a menor escala por tribus eriadoranas, que lo llaman Cuncan — un grupo tosco de construcciones de madera y barro entre los cimientos del asentamiento anterior, mucho más grande.', ST_GeomFromText('POINT(-2.428358283544628 49.31850008112172)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1086, 'Silent Castle', 'ruins', 'Bar Airlossiel (''Home of the Lonely Snow-maiden''), also known as the Silent Castle, is an ancient Elvish tower in a forgotten corner of southern Sîrgala. Its original community of Silvan Elves and Arthadan refugees pledged fealty to a half-Elven mage, Airlossiel the Quiet, who transformed into one of the Houseless after a morgul-wound in T.A. 1409. Her spirit remains bound to the tower''s foundations; the haven became almost eerily peaceful thereafter, and few visitors leave with a full account of what they experienced. Rangers occasionally send incurably wounded men here; some return years later, cured but confused.', 'Bar Airlossiel (''Hogar de la Doncella Solitaria de la Nieve''), conocido también como el Castillo Silencioso, es una antigua torre élfica en un rincón olvidado del sur de Sîrgala. Su comunidad original de Elfos Silvanos y refugiados arthedanos juró lealtad a una maga medio elfa, Airlossiel la Callada, que se convirtió en una de los Sin Casa tras una herida de morgul en la T.E. 1409. Su espíritu sigue atado a los cimientos de la torre; desde entonces el refugio quedó envuelto en una paz casi inquietante, y pocos visitantes se van con un relato completo de lo que vivieron. Los Montaraces mandan aquí de tanto en tanto a hombres con heridas incurables; algunos vuelven años después, curados pero confundidos.', ST_GeomFromText('POINT(-2.713613170308578 50.158211634982955)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1087, 'Parth Ainatir', 'point of interest', 'Parth Aertirith (S."Sward of the Holy Watch") was an Elvish camping glade on the border of Sîrgala and Harlindon.The Place was forsaken by the Elves after a great tragedy, the juvenile and drunk Elcaldil of Girithlin, heir of Girithlin, had harassed an elven girl and was thrown down by Glorfindel Goldenhair, after which the House Girithlin thought of it''s family and fate as cursed.', 'Parth Aertirith (S. ''Prado de la Guardia Sagrada'') era un claro élfico de acampada en el límite de Sîrgala y Harlindon. Los Elfos abandonaron el lugar después de una gran desgracia: Elcaldil de Girithlin, joven y ebrio heredero de los Girithlin, acosó a una muchacha élfica y fue derribado por Glorfindel el de los Cabellos de Oro, tras lo cual la Casa Girithlin tuvo a su familia y a su destino por maldito.', ST_GeomFromText('POINT(-3.241505115625056 49.610776794368)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1088, 'Endrist', 'ruins', 'Once a populous township of 4,600 in western Siragale, known in its heyday as Enedhriss. By the early Third Age it was already in decline; by T.A. 1400 it had been fully abandoned. A traveller today finds only the ghostly outlines of old foundations under the scrub of the Pinnath Luin''s lower slopes — no fire, no voice, only the wind through broken stone.', 'Antaño un municipio populoso de 4.600 habitantes en el oeste de Siragale, conocido en su mejor momento como Enedhriss. A comienzos de la Tercera Edad ya estaba en decadencia; hacia la T.E. 1400 había sido abandonado por completo. El viajero encuentra hoy solo el trazado fantasmal de los cimientos viejos bajo la maleza de las laderas bajas de las Pinnath Luin — ni fuego, ni voz, solo el viento entre la piedra partida.', ST_GeomFromText('POINT(-2.383984129906068 49.69500962840932)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1089, 'Bag end', 'point of interest', 'Built by Bungo Baggins into the Hill above Hobbiton''s Bagshot Row as a wedding gift for his wife Belladonna Took, c. T.A. 2890. The most luxurious Hobbit-hole in the Westfarthing, entered through a perfectly round green door with a bright brass knob. Inside, all rooms are on a single level: bedrooms, kitchens, pantries, studies, wardrobes and dining-rooms arranged along a comfortable tunnel-passage. The best rooms face the garden and meadow to the west. Home of Bilbo Baggins and later his heir Frodo Baggins.', 'Construido por Bungo Bolsón dentro de la Colina, sobre el Bolsón de Tirada de Hobbiton, como regalo de casamiento para su mujer, Belladonna Tuk, hacia la T.E. 2890. Es el agujero-hobbit más lujoso de la Cuaderna del Oeste, y se entra por una puerta verde perfectamente redonda con un pomo de bronce brillante. Dentro, todas las habitaciones están en un mismo nivel: dormitorios, cocinas, despensas, estudios, guardarropas y comedores dispuestos a lo largo de un pasillo-túnel confortable. Las mejores habitaciones dan al jardín y al prado, al oeste. Hogar de Bilbo Bolsón y más tarde de su heredero, Frodo Bolsón.', ST_GeomFromText('POINT(-1.244931105219367 51.62852208381378)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1090, 'Bareketta', 'castle', 320, '100% Dúnadan', 'Bareketta is a handsome estate on the eastern shore of Nenuial, the primary seat of the Eketta family — one of the two most powerful noble clans in Arthedain. It was built with beauty as much as defence in mind: graceful stone towers look out over the lake, and the gardens between the walls are carefully tended. The estate is comfortable and well-staffed; those granted admittance find a household that takes hospitality seriously.', 'Bareketta es una hacienda hermosa en la orilla oriental del Nenuial, asiento principal de la familia Eketta — uno de los dos clanes nobles más poderosos de Arthedain. Fue construida pensando tanto en la belleza como en la defensa: torres gráciles de piedra miran sobre el lago, y los jardines entre los muros se atienden con cuidado. La hacienda es cómoda y tiene mucho servicio; a quien se le permite entrar encuentra una casa que se toma la hospitalidad en serio.', ST_GeomFromText('POINT(-0.469623980342106 53.493819717355144)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1091, 'Kuska', 'village', 390, '100% Angmarean (Mixed Mannish: Dunnish, Brygath Easterling, Estaravë)', 'Kuska sits in the Angmar Gap three miles west of Barad Morkai, founded by Angmar''s forces to keep the fortress supplied. The village is a grim place: timber barracks and storehouses surrounded by a rough palisade, populated almost entirely by the mixed Mannish people — Dunnish, Brygath Easterlings, Estaravë — who serve the Witch-king''s armies. Provisions are moved constantly up the road to Morkai; Kuska''s only purpose is to feed the war machine above it.', 'Kuska se asienta en el Paso de Angmar, tres millas al oeste de Barad Morkai, fundada por las fuerzas de Angmar para mantener abastecida la fortaleza. La aldea es un lugar sombrío: barracas y depósitos de madera rodeados por una palizada tosca, poblados casi por completo por la gente humana mezclada — dunlendinos, orientales brygath, estaravë — que sirve a los ejércitos del Rey Brujo. Los suministros suben sin parar por el camino hacia Morkai; el único propósito de Kuska es alimentar la máquina de guerra que tiene encima.', ST_GeomFromText('POINT(6.520577494896312 55.048951053981135)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1092, 'Ost Galad', 'town', 'An Elvish settlement in the Emyn Lûm area of Mirkwood, known as Ost Galadh (''Tree Fortress''). In the mid-Third Age its population is about 1,200. The settlement is built among the great forest trees, with platforms and walkways of Silvan Elvish craft connecting the living quarters above the ground. The trees here are ancient and vast; a traveller arriving from outside Mirkwood is struck by the quality of the light filtering through the canopy and the utter silence of the undergrowth.', 'Un asentamiento élfico de la zona de las Emyn Lûm, en el Bosque Negro, conocido como Ost Galadh (''Fortaleza de los Árboles''). A mediados de la Tercera Edad su población es de unos 1.200. El asentamiento está construido entre los grandes árboles del bosque, con plataformas y pasarelas de oficio élfico silvano que unen las viviendas por encima del suelo. Los árboles de aquí son antiguos y enormes; al viajero que llega de fuera del Bosque Negro lo golpean la calidad de la luz que se filtra por la bóveda de hojas y el silencio absoluto de la maleza.', ST_GeomFromText('POINT(17.024039948514115 54.203242899740815)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1093, 'Celebannon', 'village', 110, '95% Silvan Elvish, 5% Sinda', 'Celebannon is a small but elegant Elvish village on the banks of the Taurduin in Mirkwood, founded in the early Third Age as a point of contact between the Elves of the Woodland Realm and the surrounding folk of Rhovanion. Its buildings are finely made — carved wood and white stone among the trees — and the Elves here are more accustomed to the presence of travellers than most of their kin. A small market operates occasionally where Elvish goods can be obtained at fair prices.', 'Celebannon es una aldea élfica pequeña pero elegante en las orillas del Taurduin, en el Bosque Negro, fundada a comienzos de la Tercera Edad como punto de contacto entre los Elfos del Reino del Bosque y la gente de los alrededores de Rhovanion. Sus edificios están finamente hechos — madera tallada y piedra blanca entre los árboles — y los Elfos de aquí están más acostumbrados a la presencia de viajeros que la mayoría de los suyos. De tanto en tanto funciona un mercado pequeño donde se pueden conseguir productos élficos a precios justos.', ST_GeomFromText('POINT(20.319857781755008 53.400661286504764)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1094, 'Cairg Dinas', 'village', ST_GeomFromText('POINT(-3.122325604648317 47.69541097248639)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1095, 'Limmon', 'village', ST_GeomFromText('POINT(8.620391946119799 42.66736596240788)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1096, 'Calenin', 'village', ST_GeomFromText('POINT(8.310991762662013 42.44778466202531)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1097, 'Doldorth', 'village', 'A village in Gondor''s Ithilien region, a modest settlement of stone farmhouses surrounded by the herb-gardens and orchards for which Ithilien is famed. The traveller arriving here in spring or summer is struck by the fragrance of flowering herbs and the orderly terraces climbing the hillside. Life is quiet; the people grow herbs, olives and grain.', 'Una aldea de la región de Ithilien, en Gondor; un asentamiento modesto de casas de labranza de piedra rodeadas por los jardines de hierbas y los huertos por los que Ithilien es famosa. Al viajero que llega en primavera o en verano lo golpea el perfume de las hierbas en flor y las terrazas ordenadas que suben por la ladera. La vida es tranquila; la gente cultiva hierbas, olivas y cereal.', ST_GeomFromText('POINT(6.712816738648292 42.868599310618215)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1098, 'Ost-in-edhil', 'ruins', 0, 'N/A', 'Ost-in-Edhil was the great Elvish city of Eregion, founded in the Second Age by Galadriel and Celeborn and later the home of Celebrimbor the smith, who forged the Great Rings here. Its ruins still show the elegant stonework of the Gwaith-i-Mírdain craftsmen; broken archways and carved lintels half-buried in ivy suggest a settlement of rare sophistication. Nothing now inhabits those fallen halls but wind and the memory of what was lost when Sauron brought the city to ruin.', 'Ost-in-Edhil fue la gran ciudad élfica de Eregion, fundada en la Segunda Edad por Galadriel y Celeborn y más tarde hogar de Celebrimbor el herrero, que forjó aquí los Grandes Anillos. Sus ruinas todavía muestran la piedra elegante de los artesanos Gwaith-i-Mírdain; arcos partidos y dinteles tallados medio enterrados en la hiedra sugieren un asentamiento de una sofisticación poco común. Hoy no habita esos salones caídos más que el viento y la memoria de lo que se perdió cuando Sauron llevó la ciudad a la ruina.', ST_GeomFromText('POINT(6.10677238379667 48.654335533996736)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1099, 'Cillien', 'village', 145, '100% Dunman', 'Cillien is a Dunnish village in the hills of Enedwaith, the focal point for the scattered families of Clan Eogbann. Its most notable building is the Healer''s Hall — a timber longhouse where the clan''s healers practise their craft, serving anyone in the region who makes the journey here. The village itself is small and self-contained, its longhouses arranged in a rough circle around a shared fire-pit.', 'Cillien es una aldea dunlendina de las colinas de Enedwaith, el punto de reunión de las familias dispersas del Clan Eogbann. Su edificio más notable es la Casa del Sanador — una casa larga de madera donde los sanadores del clan practican su oficio y atienden a cualquiera de la región que haga el viaje hasta aquí. La aldea es pequeña y cerrada sobre sí misma, con sus casas largas dispuestas en un círculo tosco alrededor de un fogón común.', ST_GeomFromText('POINT(6.948790388251328 48.286409902662065)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1100, 'Pillars of Stone', 'ruins', ST_GeomFromText('POINT(5.146369766489915 48.698512237463206)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1101, 'Minas Melosse', 'point of interest', ST_GeomFromText('POINT(5.89693339932258 50.07763268808455)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1102, 'Beanach', 'town', ST_GeomFromText('POINT(6.061802976570391 47.938733290407235)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1103, 'Dun Fidach', 'town', 'What was once a Dúnadan fortress called Amon Mîn (''Hill between the gaps'') — a watch-post commanding the Greenway in Dor Wathui — has long since been abandoned. The Rangers of the North maintained it briefly after Arnor''s dissolution, but eventually left it to decay. The Dunlendings call the ruins ''Dinas Gwydd''; a small Ranger campsite occasionally shelters here.', 'Lo que fue una fortaleza dúnadan llamada Amon Mîn (''Colina entre los pasos'') — un puesto de vigilancia que dominaba el Camino Verde en Dor Wathui — está abandonado desde hace mucho. Los Montaraces del Norte lo mantuvieron un tiempo breve después de la disolución de Arnor, pero al final lo dejaron caer. Los dunlendinos llaman a las ruinas ''Dinas Gwydd''; de tanto en tanto un campamento pequeño de Montaraces se refugia aquí.', ST_GeomFromText('POINT(5.894414480295413 47.74072678929605)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1104, 'Dun Udrost', 'town', 'Echad Dagoras (''Dagoras'' Camp'') is an old Elvish ruin south of Eregion, some sixty miles southeast of Ost-in-Edhil. The Rangers of the North use it as a temporary camp; the local Dunlendings call it Dinas Yddryst or Dol Du (''Dark toll'') and shun the place. A few broken stone walls and foundation courses amid scrub — eerie in atmosphere.', 'Echad Dagoras (''Campamento de Dagoras'') es una vieja ruina élfica al sur de Eregion, unas sesenta millas al sudeste de Ost-in-Edhil. Los Montaraces del Norte la usan como campamento temporario; los dunlendinos del lugar la llaman Dinas Yddryst o Dol Du (''Peaje oscuro'') y evitan el sitio. Unos pocos muros de piedra partidos e hiladas de cimiento entre la maleza — de atmósfera inquietante.', ST_GeomFromText('POINT(6.650490349003736 48.18247825976938)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1105, 'Creatrach', 'town', 'In the Coit Cerdd on the borders of Dunfearn stands the ruin of an old Gondorian watchtower called Harndirion (''Southwatch''). The Rangers of the North maintain a semi-permanent camp here among the ancient stones. The local Dunlendings call it Craig-y-Din (''Castle Rock'') and give it a wide berth.', 'En el Coit Cerdd, en los límites de Dunfearn, se alza la ruina de una vieja torre de vigilancia gondoriana llamada Harndirion (''Guardia del Sur''). Los Montaraces del Norte mantienen aquí un campamento semipermanente entre las piedras antiguas. Los dunlendinos del lugar la llaman Craig-y-Din (''Roca del Castillo'') y le pasan bien lejos.', ST_GeomFromText('POINT(6.673436505868934 47.79239491928146)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1106, 'Gwâl Draig', 'town', 'A Dunlending village in Dunfearn that grew up around an ancient Temple of Justice, built c. T.A. 1200. The original temple — shaped like a great stone bull''s head, sixty feet tall — now forms the core of a village called Gwâl Draig, home of the Draig-lûth tribe, descendants of the temple''s original adherents. The tribe still bears the Dragon Turukulon as their symbol. The village is a rough settlement of timber houses around the old stone temple; guards in white robes and armed with wide-bladed axes watch the entrance.', 'Una aldea dunlendina de Dunfearn que creció alrededor de un antiguo Templo de la Justicia, construido hacia la T.E. 1200. El templo original — con forma de gran cabeza de toro de piedra, de sesenta pies de alto — es hoy el núcleo de una aldea llamada Gwâl Draig, hogar de la tribu Draig-lûth, descendientes de los primeros fieles del templo. La tribu todavía lleva al Dragón Turukulon como símbolo. La aldea es un asentamiento tosco de casas de madera alrededor del templo viejo de piedra; unos guardias con túnicas blancas y hachas de filo ancho vigilan la entrada.', ST_GeomFromText('POINT(7.123181180426845 47.82321709794124)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1107, 'Odharn', 'town', ST_GeomFromText('POINT(6.412033209800232 47.70016559791756)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1108, 'Daithen', 'town', 'A Dunnish clan-hold in Dunfearn near the Misty Mountains, its name meaning ''Ancient Fire''. A rough highland village of timber longhouses and livestock pens, ruled by chieftain Menu with the counsel of the local conjurer Selyf Hen. Smoke from fires hangs low in the valley on cold mornings.', 'Un solar de clan dunlendino en Dunfearn, cerca de las Montañas Nubladas, cuyo nombre significa ''Fuego Antiguo''. Una aldea tosca de tierras altas, de casas largas de madera y corrales de ganado, gobernada por el jefe Menu con el consejo del hechicero local Selyf Hen. En las mañanas frías el humo de los fuegos queda bajo en el valle.', ST_GeomFromText('POINT(6.345912011797685 47.4271125180754)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1109, 'Carnach', 'town', 'Ost-Dunhoth was once a township of some 3,200 people in Enedhwaith. By T.A. 1400 its population had drained away entirely. What remains is a field of overgrown ruins — broken walls of old stone half-buried in scrub and grass, with no permanent inhabitants. Local Dunlendings call the place cursed and do not build here.', 'Ost-Dunhoth fue en su momento un municipio de unas 3.200 personas en Enedhwaith. Hacia la T.E. 1400 su población se había vaciado por completo. Lo que queda es un campo de ruinas cubiertas de maleza — muros partidos de piedra vieja medio enterrados en el pasto y los matorrales, sin habitantes permanentes. Los dunlendinos del lugar tienen el sitio por maldito y no construyen aquí.', ST_GeomFromText('POINT(5.744117152828357 47.297529196555374)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1110, 'Golgoch', 'town', ST_GeomFromText('POINT(6.609187266646376 48.007766147957156)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1111, 'Ehuir', 'village', ST_GeomFromText('POINT(4.517626056922889 45.69435931474646)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1112, 'Vervain', 'village', ST_GeomFromText('POINT(5.660664258362598 45.61320566169143)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1113, 'Morven', 'village', ST_GeomFromText('POINT(5.922100751602134 46.02442597016015)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1114, 'Edhellond', 'town', 2400, '80% Silvan Elvish, 20% Sinda', 'Founded by Elves fleeing the Ruin of Beleriand early in the Second Age.. A departure point for Elves leaving Middle-earth.. Edhellond is situated upon a jagged islet at the mouth of the River Morthond.', 'Fundada por Elfos que huían de la Ruina de Beleriand a comienzos de la Segunda Edad.. Punto de partida para los Elfos que dejan la Tierra Media.. Edhellond está situada sobre un islote dentado en la desembocadura del río Morthond.', ST_GeomFromText('POINT(9.215384430306086 41.59827021988721)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1115, 'Maenthirost', 'town', 'A town in the Shire or northern Eriador whose character reflects the modest farming communities of the region.', 'Un pueblo de la Comarca o del norte de Eriador, cuyo carácter refleja las comunidades agrícolas modestas de la región.', ST_GeomFromText('POINT(1.315264892540348 54.59761685770499)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1116, 'Witeburg', 'town', 'A small Rohirric settlement near the Hornburg, in the Deeping Coomb about four miles beyond Helm''s Deep and over a mile northwest of the Juggler''s Hall. Its name, ''Castle of Torment'', comes from the oddly shaped hill on which it sits — the Witeberg. Wooden walls and timber longhouses; the men here are farmers and fighters in the Rohirric style, big-boned and hardy, their hall hung with weapons and horse-gear.', 'Un asentamiento rohírrico pequeño cerca de Cuernavilla, en la Hondonada del Bajo, unas cuatro millas más allá del Abismo de Helm y a más de una milla al noroeste de la Casa del Malabarista. Su nombre, ''Castillo del Tormento'', viene de la colina de forma extraña sobre la que se asienta: el Witeberg. Muros de madera y casas largas de tablones; los hombres de aquí son granjeros y peleadores al estilo rohírrico, de huesos grandes y resistentes, con el salón colgado de armas y arreos de caballo.', ST_GeomFromText('POINT(8.154563988062607 45.38829476087444)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1117, 'Calmirië', 'fortified town', 1200, '80% Gondorian, 20% Dunnish', 'Settled by Gondorian Dúnedain in the early Third Age, granted charter by Atanatar II of Gondor in T.A. 1220.. An economic focus and market town for the province of Calenardhon; the seat of regional administration.. Calmirië is the largest and most cosmopolitan town of the Gondorian territory of Calenardhon.', 'Poblada por dúnedain gondorianos a comienzos de la Tercera Edad; recibió fuero de Atanatar II de Gondor en la T.E. 1220.. Foco económico y pueblo de mercado de la provincia de Calenardhon; sede de la administración regional.. Calmirië es el pueblo más grande y más cosmopolita del territorio gondoriano de Calenardhon.', ST_GeomFromText('POINT(11.052107547861164 44.98777699193615)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1118, 'Calost', 'town', 'A village of Anórien straddling the Calenen stream on the Great North Road, about thirty miles from Calenhad and twelve from Min-Rimmon. The ancient stone bridge over the Calenen is still in excellent repair. Stone houses on the western bank cluster around the Traveller''s Rest Inn, a well-regarded stopping point for anyone on the road. A mill draws from the river; market days bring peasants from surrounding villages.', 'Una aldea de Anórien que se extiende a ambos lados del arroyo Calenen, sobre el Gran Camino del Norte, unas treinta millas de Calenhad y doce de Min-Rimmon. El antiguo puente de piedra sobre el Calenen sigue en excelente estado. Las casas de piedra de la orilla occidental se agrupan alrededor de la posada del Descanso del Viajero, una parada bien considerada por cualquiera que ande por el camino. Un molino toma agua del río; los días de mercado traen campesinos de las aldeas de alrededor.', ST_GeomFromText('POINT(12.299727156058921 44.86176315879172)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1119, 'Astirian', 'village', 'The ancestral manor of House Astorion, a noble Gondorian family of Anórien, on the fringes of the Mouths of the Entwash north of Min-Rimmon. The manor is a solid Gondorian country house of dressed stone, surrounded by extensive farmlands and pastures. The Astorion family has held these lands since the early Third Age; their hall stands as a quiet landmark on the flat green plain.', 'La casa señorial ancestral de la Casa Astorion, una familia noble gondoriana de Anórien, en los bordes de las Bocas del Entaguas, al norte de Min-Rimmon. La casa es una sólida residencia gondoriana de campo, de piedra labrada, rodeada de tierras de labranza y pastos extensos. La familia Astorion tiene estas tierras desde comienzos de la Tercera Edad; su salón se alza como un mojón callado en la llanura verde y plana.', ST_GeomFromText('POINT(15.545072449264742 44.83558896115036)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1120, 'Bar Duilin', 'town', 'A town of Anórien situated on the Anduin opposite the island fortress of Cair Andros. Its location makes it a natural waystation for soldiers, messengers and supplies crossing to and from the fortress; a garrison camp and a river-landing dominate the waterfront. Stone houses and wooden barracks line the main road leading to the ferry.', 'Un pueblo de Anórien situado sobre el Anduin, frente a la fortaleza isleña de Cair Andros. Su ubicación lo vuelve una posta natural para los soldados, los mensajeros y los suministros que cruzan hacia la fortaleza y desde ella; un campamento de guarnición y un embarcadero dominan la ribera. Casas de piedra y barracas de madera bordean el camino principal que baja hasta la balsa.', ST_GeomFromText('POINT(17.661204530157647 44.14004071824639)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1121, 'Dim Lamedon', 'town', 'A town of Lamedon in Gondor, lying in the valley of the Lamedon river below steep hills. The name ''Dim Lamedon'' references the shadowed character of the valley; the settlement is a modest Gondorian market town of stone houses with slate roofs, serving the scattered farms and pastures of the surrounding uplands.', 'Un pueblo de Lamedon, en Gondor, en el valle del río Lamedon, al pie de colinas empinadas. El nombre ''Dim Lamedon'' alude al carácter umbrío del valle; el asentamiento es un pueblo de mercado gondoriano modesto, de casas de piedra con techos de pizarra, que atiende a las granjas y los pastos dispersos de las tierras altas de alrededor.', ST_GeomFromText('POINT(13.115531819348437 42.781053655198875)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1122, 'Tumladen', 'town', 'A town of Gondor in the Lamedon or Lebennin region, a modest Gondorian settlement of stone houses serving the surrounding farming communities.', 'Un pueblo de Gondor en la región de Lamedon o Lebennin, un asentamiento gondoriano modesto de casas de piedra que atiende a las comunidades agrícolas de alrededor.', ST_GeomFromText('POINT(13.747158156868476 42.68137651336026)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1123, 'Bar-Lymen', 'point of interest', 'A self-governing township and Grithion of Lebennin on the middle Gilrain, its name meaning ''Home of the Blue Way''. Stone houses and a small market serve the surrounding farmland. Its autonomy as a Grithion gives it a slightly more independent character than the usual Gondorian village.', 'Un municipio autónomo y Grithion de Lebennin, sobre el curso medio del Gilrain; su nombre significa ''Hogar del Camino Azul''. Casas de piedra y un mercado pequeño atienden a las tierras de labranza de alrededor. Su autonomía como Grithion le da un carácter algo más independiente que a la aldea gondoriana corriente.', ST_GeomFromText('POINT(13.535042129327076 42.15793386224273)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1124, 'Bar Gilraen', 'town', 'A small town of Lebennin on the lower Gilrain, several leagues northeast of Linhir. It is the seat of the noble family of Bar Gilraen, who hold the surrounding county. Neat stone houses with flat or tiled roofs face a central square; the Gilrain''s fertile banks support grain-growing and some wool trade.', 'Un pueblo pequeño de Lebennin sobre el curso bajo del Gilrain, varias leguas al nordeste de Linhir. Es el asiento de la familia noble de Bar Gilraen, que tiene el condado de alrededor. Casas de piedra prolijas, con techos planos o de teja, dan a una plaza central; las orillas fértiles del Gilrain sostienen el cultivo de cereal y algo de comercio de lana.', ST_GeomFromText('POINT(13.691221460854322 41.91543979242482)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1125, 'Diniath', 'town', 'A village in the County of Gilrain in southwestern Lebennin, the main settlement of the small barony of the same name. Stone houses and a small market square line the road; the surrounding farmland and fishing on the Gilrain tributary support a modest population.', 'Una aldea del Condado de Gilrain, en el suroeste de Lebennin, asentamiento principal de la baronía pequeña del mismo nombre. Casas de piedra y una plaza de mercado pequeña bordean el camino; las tierras de labranza de alrededor y la pesca en el afluente del Gilrain sostienen una población modesta.', ST_GeomFromText('POINT(12.270652951393377 40.985680068474274)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1126, 'Bar Annuland', 'town', ST_GeomFromText('POINT(13.674276861522001 41.083513694510664)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1127, 'Lindon', 'town', 'An Elvish coastal settlement in Lindon, one of the last Elvish domains in the west of Middle-earth. The settlement is small and quiet — elegant timber-and-stone buildings half-hidden among trees near the shore, maintained by Elves who prefer the company of the sea to that of Men. A traveller is struck by the orderliness and beauty of everything here: tools put away neatly, gardens tended with obvious care, and always somewhere in the background the sound of music or quiet voices.', 'Un asentamiento élfico costero en Lindon, uno de los últimos dominios élficos del occidente de la Tierra Media. Es pequeño y tranquilo — edificios elegantes de madera y piedra medio ocultos entre los árboles cerca de la orilla, mantenidos por Elfos que prefieren la compañía del mar a la de los Hombres. Al viajero le llama la atención el orden y la belleza de todo lo que hay aquí: las herramientas guardadas con prolijidad, los jardines atendidos con cuidado evidente, y siempre, en algún lugar del fondo, el sonido de música o de voces calladas.', ST_GeomFromText('POINT(14.301150576455248 41.08018609168526)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1128, 'Lalornen', 'town', 'A town of Lebennin on the middle Serni, halfway between Brethil and Linhir. A modest Gondorian market town of stone houses, it serves the farming communities of the Serni valley and acts as a waystation on the road between the two larger settlements.', 'Un pueblo de Lebennin sobre el curso medio del Serni, a mitad de camino entre Brethil y Linhir. Es un pueblo de mercado gondoriano modesto, de casas de piedra, que atiende a las comunidades agrícolas del valle del Serni y funciona como posta en el camino entre los dos asentamientos mayores.', ST_GeomFromText('POINT(14.5795769794468 41.491203940931356)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1129, 'Dol Calimir', 'town', 'A town of Lebennin on a small tributary of the Serni, halfway between Minas Brethil and Pelargir. Its position on this route makes it a regular stopping point for travellers. Stone houses and a small inn; in recent years the town has been fortified with a new outer wall.', 'Un pueblo de Lebennin sobre un afluente pequeño del Serni, a mitad de camino entre Minas Brethil y Pelargir. Su posición en esta ruta lo vuelve una parada habitual para los viajeros. Casas de piedra y una posada pequeña; en los últimos años el pueblo se fortificó con un muro exterior nuevo.', ST_GeomFromText('POINT(15.57488310345749 41.68432393525742)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1130, 'Barfalas', 'town', 'A small fishing village in Lebennin on the Anduin, southwest of Pelargir. Stone houses with fishing nets hung to dry face a sheltered cove; the people here fish the river and trade their catch at the nearest market. The village is small and tranquil.', 'Una aldea pequeña de pescadores en Lebennin, sobre el Anduin, al suroeste de Pelargir. Casas de piedra con las redes tendidas a secar dan a una cala abrigada; la gente de aquí pesca en el río y vende lo que saca en el mercado más cercano. La aldea es pequeña y tranquila.', ST_GeomFromText('POINT(15.885149223521815 41.119181509105715)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1131, 'Arnbad', 'town', 'A small town in eastern Methed Lebennin, seat of the surrounding Grithion of the same name. Its name — ''Royal Path'' in Sindarin — hints at an old road that once ran through its centre. Stone houses and a modest market hall ring a crossroads shaded by plane trees; the surrounding farmland yields grain and olives.', 'Un pueblo pequeño del este de Methed Lebennin, asiento del Grithion del mismo nombre. Su nombre — ''Senda Real'' en sindarin — deja ver un camino viejo que alguna vez pasaba por su centro. Casas de piedra y una casa de mercado modesta rodean un cruce a la sombra de unos plátanos; las tierras de labranza de alrededor dan cereal y olivas.', ST_GeomFromText('POINT(15.201729716218498 41.266272310261506)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1132, 'Pellas', 'town', 'A small Gondorian town or village in eastern Lebennin, about twenty-five miles northeast of Pelargir in the County of Landor. Also known as Barath Tâlhir, it is a freehold estate of House Tâlhir, a local knightly family. Stone houses and a modest manor; grain and livestock are the main produce of the estate.', 'Un pueblo o aldea gondoriana pequeña del este de Lebennin, unas veinticinco millas al nordeste de Pelargir, en el Condado de Landor. Conocida también como Barath Tâlhir, es una hacienda libre de la Casa Tâlhir, una familia de caballeros del lugar. Casas de piedra y una casa señorial modesta; el cereal y el ganado son la producción principal de la hacienda.', ST_GeomFromText('POINT(16.539711503431587 41.55459782743415)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1133, 'Minas Airnach', 'town', 'A town of western Lebennin in Gondor, whose stone houses and small market serve the farming communities of the surrounding river valley.', 'Un pueblo del oeste de Lebennin, en Gondor, cuyas casas de piedra y cuyo mercado pequeño atienden a las comunidades agrícolas del valle fluvial de alrededor.', ST_GeomFromText('POINT(16.479045517744957 41.995710026601884)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1134, 'Bar Luindol', 'town', 'A small town of Lossarnach, situated along a tributary of the Erui a few leagues south of Minas Arthoron on the Rathon Gondor. It is the ancestral seat of the noble family of Bar Luindol. Its stone houses and cultivated terraces benefit from the rich soil of Lossarnach.', 'Un pueblo pequeño de Lossarnach, situado sobre un afluente del Erui, unas leguas al sur de Minas Arthoron, en el Rathon Gondor. Es el asiento ancestral de la familia noble de Bar Luindol. Sus casas de piedra y sus terrazas cultivadas se benefician del suelo rico de Lossarnach.', ST_GeomFromText('POINT(16.719628251727585 42.266084960178034)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1135, 'Echorost', 'town', 'A fortified village of southwestern Lossarnach at the confluence of the Celos and the Sirith, the chief settlement of the county of Enedhîr. Its name — ''Ring-fort'' — reflects its circular defensive layout: stone walls and a central square that serves as market and muster ground. The surrounding farmland of Lossarnach is rich; the village exports grain, wool and the famous roses of the valley.', 'Una aldea fortificada del suroeste de Lossarnach, en la confluencia del Celos y el Sirith, asentamiento principal del condado de Enedhîr. Su nombre — ''Fuerte del Anillo'' — refleja su trazado defensivo circular: muros de piedra y una plaza central que sirve de mercado y de campo de reunión. Las tierras de labranza de Lossarnach son ricas; la aldea exporta cereal, lana y las famosas rosas del valle.', ST_GeomFromText('POINT(15.870012711995875 42.51707934327671)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1136, 'Barad Dur', 'fortress', 'Raised by Sauron, circa S.A. 1000.. Domination of the plateau of Gorgoroth.. Built on a spur of the Ered Lithui, and fashioned by the power of Sauron''s Ruling Ring, Barad-dûr consisted of a great central tower with nine radial towers connected to it by fortified bridges. No stronger fortress ever existed in Middle-earth. Once the seat of Sauron''s power, Barad-dûr fell when Isildur cut the Ring from Sauron''s hand. Orcs and Trolls now control the area, and no Man has visited Barad-dûr since the Plague.', 'Levantada por Sauron hacia la S.E. 1000.. Dominio de la meseta de Gorgoroth.. Construida en un espolón de las Ered Lithui y labrada por el poder del Anillo Soberano de Sauron, Barad-dûr consistía en una gran torre central con nueve torres radiales unidas a ella por puentes fortificados. Nunca existió en la Tierra Media una fortaleza más fuerte. Antaño asiento del poder de Sauron, Barad-dûr cayó cuando Isildur cortó el Anillo de la mano de Sauron. Los orcos y los trolls controlan hoy la zona, y ningún Hombre ha visitado Barad-dûr desde la Plaga.', ST_GeomFromText('POINT(21.456739666583342 44.250923912144174)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1137, 'Barad Wath', 'castle', 'Gondor began construction on the tower after the fall of Sauron, but abandoned it to conserve resources.. Monitoring traffic between Nurn and Gorgoroth.. The tower rests high in the Eregwath, providing a view for many leagues in many directions.', 'Gondor empezó a construir la torre después de la caída de Sauron, pero la abandonó para no gastar recursos.. Vigilancia del tránsito entre Nurn y Gorgoroth.. La torre se asienta en lo alto del Eregwath y da una vista de muchas leguas en muchas direcciones.', ST_GeomFromText('POINT(21.456966514449896 42.44558701172102)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1138, 'Danwaith', 'town', ST_GeomFromText('POINT(-4.475943181526394 48.69499314721522)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1139, 'Hyarlindunt', 'town', 'A town in northern Forlindon, its position and character shaped by the cold winds of the northern coast and the sparse population of these lands.', 'Un pueblo del norte de Forlindon, cuya posición y cuyo carácter están moldeados por los vientos fríos de la costa septentrional y por la población escasa de estas tierras.', ST_GeomFromText('POINT(-4.624105749297354 48.842909358271754)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1140, 'Burh Beorills', 'town', 'The seat of the Berilas clan along the Men Rómen in the hills of Duil Rewinion, known in Rohirric as Berilabaurg or ''Little-bears'' Town''. A stockaded Northman settlement of timber halls and longhouses; its cattle-pens and storehouses sit behind a wooden palisade. The Berilas are tough hill-folk; their hall is hung with bear-skins and old weapons.', 'El asiento del clan Berilas a lo largo del Men Rómen, en las colinas de Duil Rewinion, conocido en rohírrico como Berilabaurg o ''Pueblo de los Ositos''. Un asentamiento empalizado de los Hombres del Norte, de salones y casas largas de madera; sus corrales de ganado y sus depósitos quedan detrás de una palizada de madera. Los Berilas son gente ruda de las colinas; su salón está colgado de pieles de oso y de armas viejas.', ST_GeomFromText('POINT(21.927226132808812 47.51460949965142)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1141, 'Angrenost', 'citadel', 3000, '100% Gondorian', 'Angrenost — known to later ages as Isengard — is a Gondorian fortified complex in the Gap of Calenardhon, its defences centred on the indestructible tower of Orthanc. A vast circular wall one mile in diameter encloses the Orthanc and its surrounding grounds; no siege weapon has ever damaged either the tower or the ring-wall. The fortress administers the northwestern approaches to Gondor and maintains a watch on all movement through the Gap.', 'Angrenost — conocida en edades posteriores como Isengard — es un complejo fortificado gondoriano en el Paso de Calenardhon, con sus defensas centradas en la torre indestructible de Orthanc. Un muro circular enorme, de una milla de diámetro, encierra el Orthanc y los terrenos de alrededor; ninguna máquina de sitio ha dañado nunca ni la torre ni el muro anular. La fortaleza administra los accesos noroccidentales a Gondor y mantiene vigilancia sobre todo movimiento por el Paso.', ST_GeomFromText('POINT(7.669299713818591 47.09796179869919)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1142, 'Tir Serni', 'town', 'A town and castle of Lebennin on the lower Serni, about 45 miles east of Linhir. Its position on the Serni makes it a waystation for river traffic; the castle overlooks the water from a low promontory. The town''s stone houses and small market serve the Serni valley farmers.', 'Un pueblo y un castillo de Lebennin sobre el curso bajo del Serni, unas 45 millas al este de Linhir. Su posición sobre el Serni lo vuelve una posta del tránsito fluvial; el castillo domina el agua desde un promontorio bajo. Las casas de piedra del pueblo y su mercado pequeño atienden a los granjeros del valle del Serni.', ST_GeomFromText('POINT(14.027355981402826 41.33515014810564)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1143, 'Ostigrurth', 'fortress', 'Built by Sauron in the mid-Second Age.. Control of traffic in the Den Nurn; the manufacture of finished products; small-scale trade.. Ostigurth is situated at the head of a small canyon on the southern edge of Gorgoroth.', 'Construida por Sauron a mediados de la Segunda Edad.. Control del tránsito en el Den Nurn; manufactura de productos terminados; comercio en pequeña escala.. Ostigurth está situada en la cabecera de un cañón pequeño, en el borde meridional de Gorgoroth.', ST_GeomFromText('POINT(22.875519871496607 42.977404711698476)', 4326));
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es, geom) VALUES (1144, 'Minas Dûrlith', 'tower', 'Orcs (?)', 'Crafted by Sauron sometime during the Second Age.. Control of the plain known as Gaer Dûrlith.. Minas Dûrlith is one of the few Sauronic strongholds to survive the invasion of Mordor by the Last Alliance of Elves and Men.', 'Labrada por Sauron en algún momento de la Segunda Edad.. Control de la llanura conocida como Gaer Dûrlith.. Minas Dûrlith es una de las pocas plazas fuertes de Sauron que sobrevivieron a la invasión de Mordor por la Última Alianza de Elfos y Hombres.', ST_GeomFromText('POINT(23.365203450960628 44.218531095573496)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1145, 'Cirith Gorgor', 'point of interest', 'Cirith Gorgor (S. "Haunted Pass") was a high pass where the mountain ranges of the Ered Lithui and Ephel Dúath met in the far north-western corner of Mordor. The pass opened out into the mountain vale of Udûn, and was guarded from the beginning of the Third Age by the Towers of the Teeth. When Sauron returned to Mordor c. TA 2951 the Morannon was rebuilt across the Pass.', 'Cirith Gorgor (S. ''Paso Encantado'') era un paso alto donde las cadenas de las Ered Lithui y las Ephel Dúath se juntaban en el extremo noroccidental de Mordor. El paso se abría al valle montañoso de Udûn y estuvo guardado desde el comienzo de la Tercera Edad por las Torres de los Dientes. Cuando Sauron volvió a Mordor, hacia la T.E. 2951, el Morannon fue reconstruido cerrando el Paso.', ST_GeomFromText('POINT(19.273144741103273 45.28455594441935)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1146, 'Cirith Ungol', 'fortress', 124, '97% Gondorian, 3% Mixed Mannish', 'Cirith Ungol is a Gondorian fortress high in the Ephel Dúath, built to watch the Morgai and the Plateau of Gorgoroth from a commanding vantage point. Its towers stand on a narrow pass above the road into Mordor; the view from its battlements encompasses a vast dark landscape of ash and broken rock. The garrison is small and dwindling — King Tarondor has considered abandoning the post — but for now, the Gondorian flag still flies above the gate.', 'Cirith Ungol es una fortaleza gondoriana en lo alto de las Ephel Dúath, construida para vigilar el Morgai y la meseta de Gorgoroth desde una posición dominante. Sus torres se alzan en un paso angosto sobre el camino que entra en Mordor; la vista desde sus almenas abarca un paisaje vasto y oscuro de ceniza y roca partida. La guarnición es pequeña y va mermando — el rey Tarondor ha considerado abandonar el puesto — pero por ahora la bandera de Gondor sigue ondeando sobre la puerta.', ST_GeomFromText('POINT(19.49113858706461 43.55763235778517)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1147, 'Núrumurl', 'town', 'A town in the Mordor borderlands or Nurn region, its character shaped by proximity to the dark power of that land. Life here is hard and closely controlled.', 'Un pueblo de las tierras de frontera de Mordor, o de la región de Nurn, cuyo carácter está moldeado por la cercanía del poder oscuro de esa tierra. La vida aquí es dura y está estrechamente controlada.', ST_GeomFromText('POINT(21.08551492330894 40.548706263081066)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es, geom) VALUES (1148, 'Barad Harn', 'town', 560, '70% Haradan, 30% Gondorian', 'Founded in T.A. 1256 on the ruins of a previous town destroyed by a hurricane.. Support for the local trade and fishing industry; a locus for Gondorian power in Harondor.. The southernmost outpost of exclusively Gondorian authority. As might be expected, Haradan raids upon this outpost are frequent and brutal. The Governor commits much of his finances to keeping the walls around Barad Harn secure.', 'Fundada en la T.E. 1256 sobre las ruinas de un pueblo anterior destruido por un huracán.. Apoyo al comercio y a la industria pesquera del lugar; foco del poder gondoriano en Harondor.. Es el puesto más meridional de autoridad exclusivamente gondoriana. Como cabe esperar, las incursiones haradanas sobre este puesto son frecuentes y brutales. El Gobernador destina buena parte de sus finanzas a mantener seguras las murallas de Barad Harn.', ST_GeomFromText('POINT(13.233507436729269 38.456224230998565)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1149, 'Carondor', 'castle', ST_GeomFromText('POINT(3.284193630903393 54.46168168536261)', 4326));
INSERT INTO locations (id, name, location_type, geom) VALUES (1150, 'Minas Foros', 'castle', ST_GeomFromText('POINT(1.068779671341359 54.90154914317711)', 4326));
INSERT INTO locations (id, name, location_type, description, description_es, geom) VALUES (1151, 'Barad Formen', 'tower', 'A tower of the northern Shire or Arthedain region, its function as a beacon or garrison post defining its character. A plain stone structure on elevated ground.', 'Una torre del norte de la Comarca o de la región de Arthedain, cuyo carácter lo define su función de almenara o de puesto de guarnición. Es una estructura de piedra sin adornos en terreno elevado.', ST_GeomFromText('POINT(1.462763793844177 54.83816740052848)', 4326));
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1159, 'Aglarond', 'cavern', 20, '100% Gondorian (Dúnadan)', 'A second entry for Aglarond — the cavern refuge and storehouse in the White Mountains used by the garrison at Ostiras. Its gem-deposits and storage halls are maintained in readiness for emergencies.', 'Una segunda entrada para Aglarond — la caverna que sirve de refugio y depósito en las Montañas Blancas para la guarnición de Ostiras. Sus yacimientos de gemas y sus salones de almacenamiento se mantienen listos para una emergencia.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1160, 'Amrûnaur', 'fortress', 180, '100% Gondorian', 'A second fortification in the Dor-en-Ernil pass bearing the same name as Amrûnaur to the south — a commanding position on a rocky shelf, with lightning rods on its towers and a watchful garrison that monitors movement through the mountain route.', 'Una segunda fortificación en el paso de Dor-en-Ernil con el mismo nombre que el Amrûnaur del sur — una posición dominante en una plataforma rocosa, con pararrayos en las torres y una guarnición atenta que vigila el movimiento por la ruta de la montaña.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1161, 'Andrath', 'ruins', 0, 'N/A', 'Andrath was founded in T.A. 860 by Thorondur of Cardolan and served as the administrative seat of the Prince of Dol Tinare; it has been ruined and rebuilt many times. Most recently it was sacked by King Broggha''s Hillmen. The ruins that remain are a palimpsest of different building periods — Arnorian stonework, Cardolani additions, and hasty Hillman repairs — now largely abandoned.', 'Andrath fue fundada en la T.E. 860 por Thorondur de Cardolan y sirvió como sede administrativa del Príncipe de Dol Tinare; ha sido arruinada y reconstruida muchas veces. La última vez fue saqueada por los hombres de las colinas del rey Broggha. Las ruinas que quedan son un palimpsesto de períodos de construcción distintos — piedra arnoriana, agregados cardolanos y remiendos apurados de los hombres de las colinas — hoy abandonadas en buena parte.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1162, 'Angsûl', 'fortress', 200, '90% Angmarean, 10% Orcish', 'Completed by the Witch-king in T.A. 1349.. Control of traffic into and out of Angmar.. The Witch-king keeps a large garrison stationed in Angsûl to watch for spies attempting to penetrate Angmar''s central plateau.', 'Terminada por el Rey Brujo en la T.E. 1349.. Control del tránsito de entrada y de salida de Angmar.. El Rey Brujo mantiene una guarnición numerosa apostada en Angsûl para detectar a los espías que intentan penetrar la meseta central de Angmar.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1163, 'Ardûmir', 'fortress', 310, '40% Coastal People, 30% Haradan, 25% Corsair, 5% Black Númenórean', 'Built by Númenórean colonists, circa S.A. 3290.. A rural stronghold for a Captain of Umbar; administration of the surrounding lands; guards entry into the Bay of Umbar.. The castle''s eastern curtain wall drops directly into the lake that partially surrounds Ardûmir.', 'Construido por colonos numenóreanos hacia la S.E. 3290.. Plaza fuerte rural de un Capitán de Umbar; administración de las tierras de alrededor; guarda la entrada a la Bahía de Umbar.. El lienzo oriental de la muralla del castillo cae directamente en el lago que rodea en parte a Ardûmir.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1164, 'Argonath', 'point of interest', 0, 'N/A', 'The Argonath are two colossal figures of Isildur and Anárion carved into the cliffs flanking the chasm at the northern entrance to Nen Hithoel, completed in T.A. 1340 by Romendacil II to mark Gondor''s northern border. The figures stand with raised hands in a gesture of forbiddance toward the north; their faces are stern and ancient-seeming even for statues only centuries old. Travellers approaching by river fall silent when they come into view — the scale is humbling.', 'Los Argonath son dos figuras colosales de Isildur y Anárion talladas en los acantilados que flanquean el desfiladero de la entrada norte del Nen Hithoel, terminadas en la T.E. 1340 por Rómendacil II para marcar la frontera septentrional de Gondor. Las figuras se alzan con las manos levantadas en un gesto de prohibición hacia el norte; sus rostros son severos y parecen antiguos incluso para estatuas de apenas unos siglos. Los viajeros que se acercan por el río se quedan callados cuando aparecen a la vista — la escala humilla.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1165, 'Barad-dûr', 'ruins', 0, 'N/A', 'Barad-dûr was Sauron''s great stronghold on a spur of the Ered Lithui, fashioned by the power of the One Ring. Its ruin after the Last Alliance was total — the ring-energies that sustained it departed with Sauron''s defeat — yet even the broken remains are vast and dark, far larger than any other structure in Mordor. No one inhabits the ruins; they are avoided even by Orcs, who feel the absence of their master''s presence as a wound.', 'Barad-dûr fue la gran plaza fuerte de Sauron en un espolón de las Ered Lithui, labrada por el poder del Anillo Único. Su ruina tras la Última Alianza fue total — las energías del Anillo que la sostenían se fueron con la derrota de Sauron — y sin embargo hasta los restos partidos son vastos y oscuros, mucho más grandes que cualquier otra construcción de Mordor. Nadie habita las ruinas; hasta los orcos las evitan, porque sienten la ausencia de la presencia de su amo como una herida.');
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es) VALUES (1166, 'Barad-wath', 'ruins', 'Orcs (?)', 'Barad Wath is an unfinished Gondorian tower built to monitor traffic between Nurn and Gorgoroth, begun after the fall of Sauron and abandoned when resources ran short. Its dark stone walls rise only partway to their intended height; the scaffolding marks are still visible. The structure stands as a monument to Gondor''s ambitions in Mordor — imposing in outline but hollow inside, increasingly neglected.', 'Barad Wath es una torre gondoriana inconclusa, construida para vigilar el tránsito entre Nurn y Gorgoroth; se empezó después de la caída de Sauron y se abandonó cuando faltaron los recursos. Sus muros de piedra oscura llegan solo a mitad de la altura prevista, y todavía se ven las marcas de los andamios. La estructura queda como monumento a las ambiciones de Gondor en Mordor — imponente en su silueta pero hueca por dentro, y cada vez más descuidada.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1167, 'Barak-shathur', 'village', 240, '100% Naugrim', 'Founded by settlers from Azanulinbar-dûm c. T.A. 1490.. Exploitation of the mineral resources of the Iron Hills.. The Khuzdul name of the stronghold is thought to mean ''Axe Mountain'' in the Westron.', 'Fundada por colonos de Azanulinbar-dûm hacia la T.E. 1490.. Explotación de los recursos minerales de las Colinas de Hierro.. Se cree que el nombre khuzdul de la plaza fuerte significa ''Montaña del Hacha'' en oestron.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1168, 'Bar-en-tinnen', 'village', 240, '100% Gondorian', 'A second Bar-en-tinnen settlement entry (see id=1183) — a village on the east bank of the Anduin around a mill on the Sir Tinnen, providing fish and farm-produce trade for inland communities.', 'Una segunda entrada del asentamiento de Bar-en-tinnen (ver id=1183) — una aldea en la orilla oriental del Anduin, alrededor de un molino sobre el Sir Tinnen, que provee de pescado y de productos de granja a las comunidades del interior.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1169, 'Bar Lithyrn', 'village', 1000, '70% Donaen, 30% Gondorian', 'A duplicate entry for Bar Lithyrn — a Gondorian silver-mining village on the northern Ered Lithui, in slow decline as the ore veins thin (see id=1184).', 'Una entrada duplicada de Bar Lithyrn — una aldea gondoriana de minería de plata en el norte de las Ered Lithui, en decadencia lenta a medida que se agotan las vetas de mineral (ver id=1184).');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1170, 'Belegost', 'ruins', 0, 'N/A', 'Belegost was one of the two great Dwarf-cities of the Ered Luin, founded before the Sun and Moon first rose. It was destroyed at the end of the First Age when the mountains were broken in the War of Wrath. Its ruins lie buried deep beneath fallen rock and centuries of debris; a few bold Dwarven explorers have recently begun probing the outer passages in hopes of recovering ancestral artefacts, but the deeper halls remain inaccessible.', 'Belegost fue una de las dos grandes ciudades enanas de las Ered Luin, fundada antes de que se alzaran el Sol y la Luna. Fue destruida al final de la Primera Edad, cuando las montañas se quebraron en la Guerra de la Cólera. Sus ruinas yacen enterradas muy hondo, bajo la roca caída y siglos de escombros; unos pocos exploradores enanos audaces han empezado hace poco a tantear los pasadizos exteriores con la esperanza de recuperar objetos de sus antepasados, pero los salones más profundos siguen inaccesibles.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1171, 'Bottoms Bridge', 'village', 85, '95% Northman, 5% Dúnadan', 'Bottoms Bridge is a small Northman village on a low island at the edge of the Gladden Marshes, founded in the mid-Third Age to supply traders using the Anduin. Its timber bridges connect it to the bank; the sound of the river is constant and the smell of marsh-grass and damp wood is ever-present. The few dozen inhabitants live by fishing and by managing the river traffic that passes through.', 'Bottoms Bridge es una aldea pequeña de los Hombres del Norte en una isla baja al borde de los Campos Gladios, fundada a mediados de la Tercera Edad para abastecer a los comerciantes que usan el Anduin. Sus puentes de madera la unen con la orilla; el sonido del río es constante y el olor a pasto de ciénaga y a madera húmeda está siempre presente. Sus pocas docenas de habitantes viven de la pesca y de manejar el tránsito fluvial que pasa por ahí.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1172, 'Bridge Of Stonebows', 'bridge', 0, 'N/A', 'Built by Arthedain, T.A. 1102.. Passage across the River Baranduin on the Great East Road.. The King of Arthedain grants the Hobbits the right to collect a toll, which they keep at a modest few copper coins.', 'Construido por Arthedain, T.E. 1102.. Paso sobre el río Baranduin en el Gran Camino del Este.. El Rey de Arthedain concede a los hobbits el derecho a cobrar un peaje, que ellos mantienen en unas pocas monedas de cobre.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1173, 'Buhr Ailgra', 'fortified town', 220, '100% Northman', 'Founded by Éothraim, circa T.A. 1380.. Defense against Easterling attacks, a trading center for Eothraim.. Buhr Ailgra is one of the few permanent settlements of the Eothraim, who follow the migrations of their herds through the plains of Rhovanion. The town is a simple settlement of thatch and turf houses surrounded by a stout earthen rampart.', 'Fundada por los Éothraim hacia la T.E. 1380.. Defensa frente a los ataques de los Hombres del Este; centro de comercio de los Eothraim.. Buhr Ailgra es uno de los pocos asentamientos permanentes de los Eothraim, que siguen las migraciones de sus rebaños por las llanuras de Rhovanion. El pueblo es un asentamiento sencillo de casas de paja y turba, rodeado por un recio terraplén de tierra.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1174, 'Aglarond', 'cavern', 20, '100% Gondorian (Dúnadan)', 'Aglarond is a system of extensive caverns in the northern slopes of the White Mountains, currently used as a refuge and storehouse for the garrison at nearby Ostiras. First sheltered by Númenórean settlers long ago, the caves have never been fully explored — deeper galleries glitter with untouched gem deposits that serve as an emergency financial reserve for Gondor''s kings. The entrance is carefully guarded and not advertised.', 'Aglarond es un sistema de cavernas extensas en las laderas septentrionales de las Montañas Blancas, usado en la actualidad como refugio y depósito por la guarnición de la vecina Ostiras. Dieron cobijo por primera vez a colonos numenóreanos hace mucho, y nunca han sido exploradas por completo — las galerías más profundas brillan con yacimientos de gemas intactos que sirven de reserva financiera de emergencia para los reyes de Gondor. La entrada está bien guardada y no se anuncia.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1175, 'Amrûnaur', 'fortress', 180, '100% Gondorian', 'Amrûnaur is a Gondorian castle on a rocky shelf projecting from the mountain called Thoredarb by the Eredrim, commanding the central pass of Dor-en-Ernil. The fortress is notable for its lightning rods — iron spikes mounted on the towers to deflect the violent storms that frequently pass through the pass. The Dunnish population of the surrounding hills views the garrison with wariness; the castle in turn keeps a close eye on movement through the pass.', 'Amrûnaur es un castillo gondoriano sobre una plataforma rocosa que sobresale de la montaña que los eredrim llaman Thoredarb, y domina el paso central de Dor-en-Ernil. La fortaleza es notable por sus pararrayos — púas de hierro montadas en las torres para desviar las tormentas violentas que pasan seguido por el paso. La población dunlendina de las colinas de alrededor mira a la guarnición con recelo; el castillo, a su vez, sigue de cerca el movimiento por el paso.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1176, 'Andrath', 'ruins', 0, 'N/A', 'A second ruined Andrath entry — the same site as id=1161, the administrative centre of Cardolan repeatedly sacked and rebuilt. In the mid-Third Age it is another ruin, its stones reused by whoever currently occupies the area.', 'Una segunda entrada de la Andrath en ruinas — el mismo sitio que el id=1161, el centro administrativo de Cardolan, saqueado y reconstruido una y otra vez. A mediados de la Tercera Edad es otra ruina más, con sus piedras reutilizadas por quien ocupe la zona en ese momento.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1177, 'Angsûl', 'fortress', 200, '90% Angmarean, 10% Orcish', 'Completed by the Witch-king in T.A. 1349.. Control of traffic into and out of Angmar.. The Witch-king keeps a large garrison stationed in Angsûl to watch for spies attempting to penetrate Angmar''s central plateau.', 'Terminada por el Rey Brujo en la T.E. 1349.. Control del tránsito de entrada y de salida de Angmar.. El Rey Brujo mantiene una guarnición numerosa apostada en Angsûl para detectar a los espías que intentan penetrar la meseta central de Angmar.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1178, 'Ardûmir', 'fortress', 310, '40% Coastal People, 30% Haradan, 25% Corsair, 5% Black Númenórean', 'Built by Númenórean colonists, circa S.A. 3290.. A rural stronghold for a Captain of Umbar; administration of the surrounding lands; guards entry into the Bay of Umbar.. The castle''s eastern curtain wall drops directly into the lake that partially surrounds Ardûmir.', 'Construido por colonos numenóreanos hacia la S.E. 3290.. Plaza fuerte rural de un Capitán de Umbar; administración de las tierras de alrededor; guarda la entrada a la Bahía de Umbar.. El lienzo oriental de la muralla del castillo cae directamente en el lago que rodea en parte a Ardûmir.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1179, 'Argonath', 'point of interest', 0, 'N/A', 'Finished in T.A. 1340 by Romendacil II.. Designation of the northern boundary of Gondor.. Carved rocks flanking the chasm at the northern entrance to Nen Hithoel. The figures represent Isildur and Anárion. Since the time of Romendacil II, Gondor''s northern border has moved even farther north, making the pillars obsolete. Nonetheless, they are a magnificent spectacle.', 'Terminados en la T.E. 1340 por Rómendacil II.. Señalamiento del límite septentrional de Gondor.. Rocas talladas que flanquean el desfiladero de la entrada norte del Nen Hithoel. Las figuras representan a Isildur y a Anárion. Desde los tiempos de Rómendacil II, la frontera norte de Gondor se ha corrido aún más al norte, con lo que los pilares quedaron obsoletos. Aun así, son un espectáculo magnífico.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1180, 'Barad-dûr', 'ruins', 0, 'N/A', 'Raised by Sauron, circa S.A. 1000.. Domination of the plateau of Gorgoroth.. Built on a spur of the Ered Lithui, and fashioned by the power of Sauron''s Ruling Ring, Barad-dûr consisted of a great central tower with nine radial towers connected to it by fortified bridges. No stronger fortress ever existed in Middle-earth. Once the seat of Sauron''s power, Barad-dûr fell when Isildur cut the Ring from Sauron''s hand. Orcs and Trolls now control the area, and no Man has visited Barad-dûr since the Plague.', 'Levantada por Sauron hacia la S.E. 1000.. Dominio de la meseta de Gorgoroth.. Construida en un espolón de las Ered Lithui y labrada por el poder del Anillo Soberano de Sauron, Barad-dûr consistía en una gran torre central con nueve torres radiales unidas a ella por puentes fortificados. Nunca existió en la Tierra Media una fortaleza más fuerte. Antaño asiento del poder de Sauron, Barad-dûr cayó cuando Isildur cortó el Anillo de la mano de Sauron. Los orcos y los trolls controlan hoy la zona, y ningún Hombre ha visitado Barad-dûr desde la Plaga.');
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es) VALUES (1181, 'Barad-wath', 'ruins', 'Orcs (?)', 'Gondor began construction on the tower after the fall of Sauron, but abandoned it to conserve resources.. Monitoring traffic between Nurn and Gorgoroth.. The tower rests high in the Eregwath, providing a view for many leagues in many directions.', 'Gondor empezó a construir la torre después de la caída de Sauron, pero la abandonó para no gastar recursos.. Vigilancia del tránsito entre Nurn y Gorgoroth.. La torre se asienta en lo alto del Eregwath y da una vista de muchas leguas en muchas direcciones.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1182, 'Barak-shathur', 'village', 240, '100% Naugrim', 'Founded by settlers from Azanulinbar-dûm c. T.A. 1490.. Exploitation of the mineral resources of the Iron Hills.. The Khuzdul name of the stronghold is thought to mean ''Axe Mountain'' in the Westron.', 'Fundada por colonos de Azanulinbar-dûm hacia la T.E. 1490.. Explotación de los recursos minerales de las Colinas de Hierro.. Se cree que el nombre khuzdul de la plaza fuerte significa ''Montaña del Hacha'' en oestron.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1183, 'Bar-en-tinnen', 'village', 240, '100% Gondorian', 'Bar-en-tinnen is a small village on the east bank of the Anduin, grown up around a mill on the Sir Tinnen stream. Founded around T.A. 1512, it provides inland communities with fish and serves as a modest trading point for local farmers. The mill wheel turns constantly; the smell of grain and river-mud is constant.', 'Bar-en-tinnen es una aldea pequeña en la orilla oriental del Anduin, crecida alrededor de un molino sobre el arroyo Sir Tinnen. Fundada hacia la T.E. 1512, provee de pescado a las comunidades del interior y funciona como punto modesto de comercio para los granjeros del lugar. La rueda del molino gira sin parar; el olor a grano y a barro de río es constante.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1184, 'Bar Lithyrn', 'village', 1000, '70% Donaen, 30% Gondorian', 'Bar Lithyrn is a mining village on the slopes of the northern Ered Lithui, founded by Gondorian commercial interests to extract silver ore from the mountains. Most inhabitants are local Donaen men lured by the prospect of wages; their Dúnadan lords ship the silver south to Gondor''s treasuries. The village is isolated and in slow decline — the silver veins are thinning, and each year a few more families leave for easier lives elsewhere.', 'Bar Lithyrn es una aldea minera en las laderas del norte de las Ered Lithui, fundada por intereses comerciales gondorianos para extraer mineral de plata de las montañas. La mayoría de sus habitantes son hombres donaen del lugar, atraídos por la perspectiva de un jornal; sus señores dúnedain embarcan la plata al sur, hacia los tesoros de Gondor. La aldea está aislada y en decadencia lenta — las vetas de plata se van agotando, y cada año unas cuantas familias más se van a buscar una vida más fácil en otra parte.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1185, 'Belegost', 'ruins', 0, 'N/A', 'The First Age, possibly before the Sun and the Moon first rose.. Exploit the riches of the Ered Luin, defense against all enemies.. A few bold Dwarven explorers have recently begun to explore the ruins in hopes of finding the artifacts of their ancestors.', 'La Primera Edad, posiblemente antes de que se alzaran por primera vez el Sol y la Luna.. Explotar las riquezas de las Ered Luin; defensa frente a todos los enemigos.. Unos pocos exploradores enanos audaces han empezado hace poco a explorar las ruinas con la esperanza de encontrar los objetos de sus antepasados.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1186, 'Bottoms Bridge', 'village', 85, '95% Northman, 5% Dúnadan', 'Settled circa T.A. 1337.. A supply center for traders sailing on the Anduin.. Bottoms Bridge is located on a small island at the edge of the Gladden Marshes.', 'Poblada hacia la T.E. 1337.. Centro de abastecimiento para los comerciantes que navegan el Anduin.. Bottoms Bridge está en una isla pequeña al borde de los Campos Gladios.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1187, 'Bridge Of Stonebows', 'bridge', 0, 'N/A', 'Built by Arthedain, T.A. 1102.. Passage across the River Baranduin on the Great East Road.. The King of Arthedain grants the Hobbits the right to collect a toll, which they keep at a modest few copper coins.', 'Construido por Arthedain, T.E. 1102.. Paso sobre el río Baranduin en el Gran Camino del Este.. El Rey de Arthedain concede a los hobbits el derecho a cobrar un peaje, que ellos mantienen en unas pocas monedas de cobre.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1188, 'Buhr Ailgra', 'fortified town', 220, '100% Northman', 'Buhr Ailgra is one of the few permanent settlements of the Éothraim, a fortified town on the lower plains of Rhovanion enclosed by a stout earthen rampart. Most of its residents use it as a seasonal base, following their herds through the rest of the year; the town is most crowded in winter and nearly empty in midsummer. Thatch-and-turf houses cluster inside the rampart; the permanent residents are traders and craftsmen who supply the Éothraim when they return.', 'Buhr Ailgra es uno de los pocos asentamientos permanentes de los Éothraim, un pueblo fortificado en las llanuras bajas de Rhovanion, cercado por un recio terraplén de tierra. Casi todos sus habitantes lo usan como base de temporada y siguen a sus rebaños el resto del año; el pueblo está más lleno en invierno y queda casi vacío a mediados del verano. Casas de paja y turba se apiñan dentro del terraplén; los residentes permanentes son comerciantes y artesanos que abastecen a los Éothraim cuando vuelven.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1189, 'Aradhrynd', 'manor', 500, '93% Silvan Elvish, 7% Sinda', 'Aradhrynd is the great underground palace of King Thranduil of the Woodland Realm, carved beneath a hill near the northern edge of Mirkwood after the growing Shadow of Dol Guldur made the southern forest uninhabitable. Unlike the dark tunnels of Goblins, the halls are bright with torchlight and alive with Elvish voices; carved pillars support high ceilings, and a river runs through the lower levels. Visitors are rare and rarely welcome — the guards are watchful, and the gates of great iron and oak are seldom opened for strangers.', 'Aradhrynd es el gran palacio subterráneo del rey Thranduil, del Reino del Bosque, cavado bajo una colina cerca del linde norte del Bosque Negro después de que la Sombra creciente de Dol Guldur volviera inhabitable el sur del bosque. A diferencia de los túneles oscuros de los trasgos, los salones están claros por la luz de las antorchas y vivos de voces élficas; pilares tallados sostienen techos altos, y un río corre por los niveles bajos. Las visitas son raras y rara vez bien recibidas — los guardias están atentos, y las puertas de hierro y roble se abren pocas veces para forasteros.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1190, 'Azanulinbar-dûm', 'dwarven mine', 480, '100% Naugrim', 'Azanulinbar-dûm is the principal mansion of the Dwarves of the Iron Hills and the seat of Lord Fulla III. First delved around T.A. 1000, it has grown into a full Dwarven settlement of homes, workshops and mines beneath the Emyn Angren. Outsiders are rarely admitted; those few who have seen the interior describe halls of bare stone brightened by crystal formations, and the constant sound of industry echoing from every gallery.', 'Azanulinbar-dûm es la mansión principal de los Enanos de las Colinas de Hierro y el asiento del señor Fulla III. Cavada por primera vez alrededor de la T.E. 1000, ha crecido hasta ser un asentamiento enano completo, de viviendas, talleres y minas bajo las Emyn Angren. A los de fuera rara vez se los admite; los pocos que han visto el interior describen salones de piedra desnuda iluminados por formaciones de cristal, y el sonido constante del trabajo resonando desde cada galería.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1191, 'Bridge Of Mitheithel', 'bridge', 0, 'N/A', 'Built by Arnor, T.A. 320.. Passage across the Mitheithel on the Great East Road. The Last Bridge, so-named because it is the farthest east on the Road, was built of stone with three great arches.', 'Construido por Arnor, T.E. 320.. Paso sobre el Mitheithel en el Gran Camino del Este. El Último Puente, llamado así porque es el más oriental del Camino, fue construido en piedra con tres grandes arcos.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1192, 'Buhr Fram', 'town', 0, '100% Northman', 'Name given to Wraecaburg after the Éothraim settled there in the nineteenth century of the Third Age.. Settlement of Éothraim.. Name given to Wraecaburg after the Éothraim settled there in the nineteenth century of the Third Age.', 'Nombre dado a Wraecaburg después de que los Éothraim se asentaran allí en el siglo diecinueve de la Tercera Edad.. Asentamiento de los Éothraim.. Nombre dado a Wraecaburg después de que los Éothraim se asentaran allí en el siglo diecinueve de la Tercera Edad.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1193, 'Buhr Mahrling', 'fortified town', 490, '50% Northman (Éothraim), 50% Easterling', 'Buhr Mahrling is a Northman trading town on the lower River Celduin, seized from Easterlings in T.A. 1503. Most residents are seasonal Éothraim who use it as a base between their herding migrations; a sizeable community of Esgaroth Northmen maintain it as an advance trading outpost near Dorwinion. The result is a busy, polyglot town where Éothraim horse-traders, Northman merchants and the occasional Easterling trader haggle across a language barrier.', 'Buhr Mahrling es un pueblo comercial de los Hombres del Norte sobre el curso bajo del río Celduin, arrebatado a los Hombres del Este en la T.E. 1503. La mayoría de sus habitantes son Éothraim de temporada que lo usan como base entre sus migraciones de pastoreo; una comunidad considerable de Hombres del Norte de Esgaroth lo mantiene como puesto comercial avanzado cerca de Dorwinion. El resultado es un pueblo movido y políglota, donde tratantes de caballos éothraim, mercaderes del norte y algún comerciante del este regatean por encima de la barrera del idioma.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1194, 'Buhr Waldmarh', 'fortified town', 1250, '100% Northman', 'Founded by Northmen, circa T.A. 1290.. A stable base for the Withras clan; an economic focus for the surrounding farms.. This typical Northman town has many timber longhouses and an earthen dike surmounted by a wooden palisade.', 'Fundado por Hombres del Norte hacia la T.E. 1290.. Base estable del clan Withras; foco económico de las granjas de alrededor.. Este pueblo típico de los Hombres del Norte tiene muchas casas largas de madera y un dique de tierra coronado por una palizada.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1195, 'Buhr Widu', 'fortified town', 520, '100% Northman', 'Founded by Vidugavia in T.A. 1249.. A center for administration for the Waildung clan; a collecting point for the surrounding Gramuz farms.. Buhr Widu, by the side of the small lake known as Woodmere, retains some of the royal splendor from the time of Vidugavia.', 'Fundado por Vidugavia en la T.E. 1249.. Centro de administración del clan Waildung; punto de acopio de las granjas gramuz de alrededor.. Buhr Widu, junto al lago pequeño conocido como el Lago del Bosque, conserva algo del esplendor real de los tiempos de Vidugavia.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1196, 'Caldur', 'fortress', 210, '50% Coastal People, 20% Corsair, 20% Haradan, 10% Black Númenórean', 'Raised by the Captains of Umbar c. T.A. 520.. A base for sorties against Gondor; administration of the lands around the northern entrance to the Bay of Umbar.. Caldûr is located on a steep outcropping on the northern penninsula guarding the Nen Umbar.', 'Levantada por los Capitanes de Umbar hacia la T.E. 520.. Base para las salidas contra Gondor; administración de las tierras alrededor de la entrada norte de la Bahía de Umbar.. Caldûr está en un afloramiento empinado de la península septentrional que guarda el Nen Umbar.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1197, 'Carach Angren', 'keep', 50, '100% Gondorian', 'Carach Angren is the great iron gate that closes the pass between Udûn and Gorgoroth, its original Second Age construction by Sauron destroyed by the Last Alliance and rebuilt by Gondor in T.A. 42. The gate and its flanking walls completely block the pass; without permission to pass through, there is no way from Udûn into the interior of Mordor. The Gondorian garrison here is among the most unusual postings in the realm — surrounded on three sides by Mordor.', 'Carach Angren es la gran puerta de hierro que cierra el paso entre Udûn y Gorgoroth; su construcción original de la Segunda Edad, obra de Sauron, fue destruida por la Última Alianza y reconstruida por Gondor en la T.E. 42. La puerta y los muros que la flanquean bloquean el paso por completo; sin permiso para pasar, no hay manera de ir de Udûn al interior de Mordor. La guarnición gondoriana de aquí tiene uno de los destinos más insólitos del reino — rodeada por Mordor en tres de sus lados.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1198, 'Caras Amarth', 'ruins', 0, 'N/A', 'Caras Amarth was the first palace of the Woodland Realm, built by King Oropher deep in the forest — a network of caverns carved into a hillside, lit within by lanterns. When Thranduil moved his court northward to the Aradhrynd, Caras Amarth was abandoned; by the mid-Third Age the forest has grown back over the old entrances and only the oldest Elves remember exactly where they lie.', 'Caras Amarth fue el primer palacio del Reino del Bosque, construido por el rey Oropher en lo profundo del bosque — una red de cavernas talladas en una ladera, iluminadas por dentro con faroles. Cuando Thranduil trasladó su corte al norte, al Aradhrynd, Caras Amarth quedó abandonado; hacia mediados de la Tercera Edad el bosque ha vuelto a crecer sobre las entradas viejas y solo los Elfos más ancianos recuerdan con exactitud dónde están.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1199, 'Caras Gwindor', 'fortified town', 120, '75% Gondorian, 25% Mixed Mannish', 'Settled by Gondorians around T.A. 1098.. Supply station for caravans in Rhovanion and the garrison at Tir Nindor; surveillance of the Dead Marshes.. Caras Gwindor controls most of the trade between Dagorlad and the Anduin, but its isolation limits its size.', 'Poblada por gondorianos alrededor de la T.E. 1098.. Estación de abastecimiento para las caravanas de Rhovanion y para la guarnición de Tir Nindor; vigilancia de las Ciénagas de los Muertos.. Caras Gwindor controla la mayor parte del comercio entre la Dagorlad y el Anduin, pero su aislamiento limita su tamaño.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1200, 'Caras Tolfalas', 'village', 520, '100% Gondorian', 'Claimed by Gondor since S.A. 3321; first settled by royal command in T.A. 934.. Subsidized by Gondor''s King more to maintain a claim on the Isle of Tolfalas than for economic reasons.. A poor harbor limits access to this town, but it is the only sure mooring on Tolfalas.', 'Reclamada por Gondor desde la S.E. 3321; poblada por primera vez por orden real en la T.E. 934.. Subsidiada por el Rey de Gondor más para mantener el reclamo sobre la isla de Tolfalas que por razones económicas.. Un puerto malo limita el acceso a este pueblo, pero es el único amarradero seguro de Tolfalas.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1201, 'Cor Angálaladh', 'cemetery', 0, 'N/A', 'Used originally by Edain and ancestors of the Northmen in the First Age.. A ritual burial ground, now disused.. The site, now darkened within Mirkwood, was once one of the holiest of Northman sites.', 'Usado en origen por los edain y por los antepasados de los Hombres del Norte en la Primera Edad.. Terreno ritual de enterramiento, hoy en desuso.. El sitio, hoy ensombrecido dentro del Bosque Negro, fue en su momento uno de los lugares más sagrados de los Hombres del Norte.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1202, 'Creb Durga', 'fortress', 210, '20% Troll, 80% Mixed Mannish', 'Creb Durga was carved by the Warlord''s Trolls from a craggy hill about seventy miles north of Sudúri — a hidden base for raids across central Cardolan. Its location is deliberately obscure; travellers in the region have disappeared without explanation, taken by the Warlord''s parties operating from this base.', 'Creb Durga fue tallada por los trolls del Señor de la Guerra en una colina escarpada unas setenta millas al norte de Sudúri — una base oculta para las incursiones por el centro de Cardolan. Su ubicación es deliberadamente confusa; en la región han desaparecido viajeros sin explicación, tomados por las partidas del Señor de la Guerra que operan desde esta base.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1203, 'Crossroads Of The', 'crossroads', 0, 'N/A', 'First mentioned in the time of King Anárion.. A landmark for travellers in Ithilien.. The Crossroads are the junction of the road between Osgiliath and Minas Ithil with the Morannon-Harad Road.', 'Mencionado por primera vez en tiempos del rey Anárion.. Mojón para los viajeros de Ithilien.. El Cruce de Caminos es la unión del camino entre Osgiliath y Minas Ithil con el camino del Morannon a Harad.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1204, 'Derndingle', 'cultivated glade', 0, 'N/A', 'Used by Ents since the First Age.. A place of gathering and debate.. Derndingle is a dish-shaped valley with a small, tree-topped mound in the center.', 'Usado por los Ents desde la Primera Edad.. Lugar de reunión y de debate.. Derndingle es un valle con forma de fuente, con un montículo pequeño y coronado de árboles en el centro.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1205, 'Dundok', 'village', 150, '100% Stoor Hobbit', 'Dundok is a Stoor Hobbit village hidden in the drier edges of the Gladden Fields, occupied since at least T.A. 1360. Its low-roofed smials and reed-thatched houses are almost invisible among the reeds and sedge grass — which suits the inhabitants perfectly, as they have little desire for outside visitors. The village sustains itself through small-scale agriculture and the fishing of the Gladden''s quieter channels.', 'Dundok es una aldea de hobbits Fuertes escondida en los bordes más secos de los Campos Gladios, ocupada desde por lo menos la T.E. 1360. Sus smials de techo bajo y sus casas con techo de junco son casi invisibles entre los juncos y la hierba de las ciénagas — lo que les viene perfecto a sus habitantes, que tienen pocas ganas de recibir visitas de fuera. La aldea se sostiene con agricultura en pequeña escala y con la pesca en los canales más tranquilos del Gladio.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1206, 'Durthang', 'citadel', 240, '100% Gondorian', 'Durthang rests on a precarious ledge high above Udûn, giving its Gondorian garrison an excellent view of any movement across the plain below. Built by Isildur in T.A. 1, it is an uncomfortable posting — the winds off the Ephel Dúath are cold and bitter, the views are spectacular and grim, and the isolation is total. Supplies must be hauled up by ropes from the road below.', 'Durthang se asienta en una cornisa precaria muy por encima de Udûn, lo que le da a su guarnición gondoriana una vista excelente de cualquier movimiento por la llanura de abajo. Construida por Isildur en la T.E. 1, es un destino incómodo — los vientos que bajan de las Ephel Dúath son fríos y cortantes, las vistas son espectaculares y sombrías, y el aislamiento es total. Los suministros hay que subirlos con cuerdas desde el camino de abajo.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1207, 'Dûsalan', 'town', 1900, '60% Coastal People, 35% Haradan, 5% Black Númenórean', 'Settled by entrepreneurs from Umbar in roughly T.A. 307.. A mercantile hub for traffic to and from the South.. Dûsalan is a coastal town ruled by three independent Black Númenórean lords but dominated by Umbar.', 'Poblada por emprendedores de Umbar hacia la T.E. 307.. Nudo mercantil del tránsito que va y viene del Sur.. Dûsalan es un pueblo costero gobernado por tres señores numenóreanos negros independientes, pero dominado por Umbar.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1208, 'Eilenach', 'watchtower', 120, '100% Gondorian', 'Current tower completed in T.A. 522.. A link in Gondor''s chain of communication with the North.. Eilenach is located on the tallest and steepest hill within Druadan Forest.', 'La torre actual se terminó en la T.E. 522.. Eslabón de la cadena de comunicación de Gondor con el Norte.. Eilenach está en la colina más alta y más empinada del Bosque de Drúadan.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1209, 'Eithel Celebrin', 'fortified town', 140, '70% Gondorian, 30% Mixed Mannish', 'Settled by trading company from Pelargir, circa T.A. 1290.. Reprovisioning caravans near the eastern rim of the Dead Marshes.. Eithel Celebrin suffers from the growing tendency of merchants bound for Rhovanion to ship their goods by means of the safer route up the Anduin.', 'Poblada por una compañía comercial de Pelargir hacia la T.E. 1290.. Reaprovisionamiento de caravanas cerca del borde oriental de las Ciénagas de los Muertos.. Eithel Celebrin sufre por la tendencia creciente de los mercaderes que van a Rhovanion a embarcar sus mercancías por la ruta más segura, remontando el Anduin.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1210, 'Eldanar', 'castle', 288, '100% Angmarean (Mixed Mannish)', 'Built by Númenórean colonists around S.A. 2800, seized by Angmar in T.A. 1325.. An advance watch-station for Angmar.. Built originally by the Dúnedain of Rhudaur, Eldanar is now a secure watch-station set well out into the plain known as the En Udanoriath.', 'Construido por colonos numenóreanos alrededor de la S.E. 2800, tomado por Angmar en la T.E. 1325.. Puesto de vigilancia avanzado de Angmar.. Construido en origen por los dúnedain de Rhudaur, Eldanar es hoy un puesto de vigilancia seguro, bien adentrado en la llanura conocida como En Udanoriath.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1211, 'Erädas', 'castle', 200, '50% Coastal People, 20% Haradan, 20% Corsair, 10% Black Númenórean', 'Erädas is a Gondorian castle on a sheltered cove in the Bay of Umbar — built by Eärnil I and later seized by Umbar in T.A. 1449. It now serves as a rural retreat for Lord Teldûmeir and as the seat of local administration. The stone battlements look out over a blue harbour; the Coastal People, Haradan and Corsair inhabitants give it a character quite unlike any Gondorian fortress further north.', 'Erädas es un castillo gondoriano en una cala abrigada de la Bahía de Umbar — construido por Eärnil I y tomado más tarde por Umbar en la T.E. 1449. Hoy sirve de retiro rural para el señor Teldûmeir y de sede de la administración local. Las almenas de piedra miran sobre un puerto azul; sus habitantes, Gente de la Costa, haradanos y Corsarios, le dan un carácter muy distinto del de cualquier fortaleza gondoriana más al norte.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1212, 'Erebor', 'dungeon', 0, 'N/A', 'Natural formation, enlarged by Dwarves in Second Age (?).. Unknown.. Many tunnels and caverns lie underneath the Lonely Mountain near the town of Dale in northern Rhovanion.', 'Formación natural, ampliada por los Enanos en la Segunda Edad (?).. Desconocido.. Bajo la Montaña Solitaria, cerca del pueblo de Valle, en el norte de Rhovanion, hay muchos túneles y cavernas.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1213, 'Erelas', 'watchtower', 85, '100% Gondorian', 'Construction begun on the site of an older, simpler signal-platform in T.A. 494.. A link in Gondor''s northern chain of communication.. Erelas is the fourth beacon in the series running northwest from Minas Anor.', 'La construcción se empezó en la T.E. 494 sobre el sitio de una plataforma de señales más antigua y sencilla.. Eslabón de la cadena septentrional de comunicación de Gondor.. Erelas es la cuarta almenara de la serie que corre al noroeste desde Minas Anor.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1214, 'Fennas Drúnin', 'fortified town', 430, '50% Cardolani, 30% Dunnish, 20% Eriadoran', 'First settled by Númenóreans from Tharbad around S.A. 2910.. A social and economic focal point for the farms and villages of Feotar.. A Council runs most affairs in the town, which relies upon the local farms and vineyards for its prosperity.', 'Poblada por primera vez por numenóreanos de Tharbad alrededor de la S.E. 2910.. Foco social y económico de las granjas y las aldeas de Feotar.. Un Consejo dirige la mayor parte de los asuntos del pueblo, que depende de las granjas y los viñedos del lugar para su prosperidad.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1215, 'The Forsaken Inn', 'inn', 15, '80% Dunnish, 20% Hillman', 'In business since T.A. 1412.. Reprovisioning and boarding of travellers on the Great East Road at the Mitheithel Bridge.. Operated by a family of Dunlendings, the Forsaken Inn is one of the few safe and neutral places an innocent traveller may rest on the road from Rivendell to Bree.', 'En funcionamiento desde la T.E. 1412.. Reaprovisionamiento y alojamiento de viajeros del Gran Camino del Este, en el Puente del Mitheithel.. Regenteada por una familia de dunlendinos, la Posada Abandonada es uno de los pocos lugares seguros y neutrales donde un viajero inocente puede descansar en el camino de Rivendel a Bree.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1216, 'Goblin-town', 'city', 3100, '70% Orcish, 5% Troll, 25% Mixed Mannish Slaves', 'Goblin-town is a vast maze of natural caverns near the High Pass, occupied by Orcs since at least the Second Age. The tunnels connect Imladris to the eastern lands and give the Goblins an unmatched ability to ambush travellers crossing the Misty Mountains. Those who have entered and escaped describe a stench of smoke and filth, crowded galleries lit by smoky torches, and the constant noise of Orc voices. The Great Goblin rules here by fear and brute force.', 'La Ciudad de los Trasgos es un laberinto vasto de cavernas naturales cerca del Paso Alto, ocupado por orcos desde por lo menos la Segunda Edad. Los túneles conectan Imladris con las tierras del este y les dan a los trasgos una capacidad inigualable de emboscar a los viajeros que cruzan las Montañas Nubladas. Quienes han entrado y escapado describen un hedor a humo y a inmundicia, galerías atestadas iluminadas por antorchas humeantes, y el ruido constante de las voces de los orcos. El Gran Trasgo gobierna aquí por el miedo y la fuerza bruta.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1217, 'Haudh-in-gwanur', 'burial', 0, 'N/A', 'Originally created in the Second Age to house the noble dead among the Men of Twilight.. A ritual burial ground, no longer in use.. Extensive ruins mark the burial place of Bel''zordin, a prince who was slain in times before the Númenóreans came east to found colonies.', 'Creado en origen en la Segunda Edad para albergar a los muertos nobles de los Hombres del Crepúsculo.. Terreno ritual de enterramiento, ya sin uso.. Unas ruinas extensas marcan el lugar de enterramiento de Bel''zordin, un príncipe muerto en tiempos anteriores a la llegada de los numenóreanos al este para fundar colonias.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1218, 'Hobbiton/bywater', 'village', 360, '50% Harfoot, 40% Fallohide, 10% Stoor', 'Settled during the migrations of Hobbits to the Shire, T.A. 1601-1610.. An agricultural and pastoral community.. Set on the Great East Road, Hobbiton sees more strange travellers than most of the rural areas of the Shire.', 'Poblada durante las migraciones de los hobbits a la Comarca, T.E. 1601-1610.. Comunidad agrícola y de pastoreo.. Asentada sobre el Gran Camino del Este, Hobbiton ve pasar más viajeros extraños que la mayoría de las zonas rurales de la Comarca.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1219, 'Ilanin', 'town', 360, '80% Easterling, 20% Northman', 'Traditional trading site since at least T.A. 950.. A site for commerce; a gathering spot for many Easterling tribes.. Ilanin has few permanent buildings. Most structures are simple tents which disappear as soon as a market ends.', 'Sitio tradicional de comercio desde por lo menos la T.E. 950.. Lugar de intercambio; punto de reunión de muchas tribus de los Hombres del Este.. Ilanin tiene pocos edificios permanentes. Casi todas sus estructuras son carpas sencillas que desaparecen en cuanto termina un mercado.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1220, 'Isigir', 'castle', 210, '60% Coastal People, 25% Corsair, 10% Haradan, 5% Black Númenórean', 'Isigir is a castle on the north shore of the Nen Umbar, its surroundings known for the pungent medicinal herbs that grow in the warm lowland soil. Built by the Captains of Umbar in the early Third Age, it serves as the rural power base of Lord Adûmir and administers the productive farmlands around the lake. The herb-gardens are its most distinctive feature; their smell reaches the traveller well before the castle walls are visible.', 'Isigir es un castillo en la orilla norte del Nen Umbar, y sus alrededores son conocidos por las hierbas medicinales de olor penetrante que crecen en el suelo cálido de la tierra baja. Construido por los Capitanes de Umbar a comienzos de la Tercera Edad, sirve de base de poder rural del señor Adûmir y administra las tierras de labranza productivas de alrededor del lago. Sus jardines de hierbas son su rasgo más distintivo; el olor le llega al viajero mucho antes de que se vean los muros del castillo.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1221, 'Kas Marzûk', 'town', 1600, '80% Haradan, 20% Corsair', 'Settled by Gondorians around T.A. 932, occupied by Corsairs in T.A. 1448.. A mercantile center near the mouth of the Harnen; a base for Haradan raids against Gondorian holdings in Harondor.. Kas Marzûk was once a Gondorian town known as Caras Mirilond, but it now rests under the authority of Sangahyandim.', 'Poblada por gondorianos alrededor de la T.E. 932, ocupada por los Corsarios en la T.E. 1448.. Centro mercantil cerca de la desembocadura del Harnen; base para las incursiones haradanas contra las posesiones gondorianas de Harondor.. Kas Marzûk fue en su momento un pueblo gondoriano llamado Caras Mirilond, pero hoy está bajo la autoridad de los Sangahyandim.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1222, 'Kas Shadoul', 'town', 2700, '85% Haradan, 15% Corsair', 'Original town walls built by Ar-Pharazôn around Second Age 3261, deserted then resettled by Haradrim in the early Third Age.. A mercantile center on the south bank of the Harnen; a gathering point for many tribes of Harad.. Kas Shadoul is a major shipping port, and it is also the source for many of the contraband goods which flow into southern Gondor.', 'Las murallas originales del pueblo las construyó Ar-Pharazôn alrededor del 3261 de la Segunda Edad; después quedó desierto y fue repoblado por los haradrim a comienzos de la Tercera Edad.. Centro mercantil en la orilla sur del Harnen; punto de reunión de muchas tribus de Harad.. Kas Shadoul es un puerto de embarque importante, y es también la fuente de muchas de las mercancías de contrabando que entran al sur de Gondor.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1223, 'Kas Shafras', 'town', 1900, '40% Coastal People, 40% Haradan, 20% Corsair', 'Settled by Haradrim around T.A. 800.. A trading port, roughly halfway between the Ethir Anduin and the City of Umbar.. Kas Shafras is renowned for the rare medicinal herbs grown in its environs.', 'Poblada por los haradrim alrededor de la T.E. 800.. Puerto comercial, más o menos a mitad de camino entre el Ethir Anduin y la Ciudad de Umbar.. Kas Shafras es célebre por las hierbas medicinales raras que se cultivan en sus alrededores.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1224, 'Larach Duhnnan', 'town', 420, '90% Dunnish, 5% Dúnadan, 5% Other Mannish', 'Established as an outpost on the Old North Road, T.A. 3; taken over by Dunlendings, T.A. 275.. An urban center for the scattered Dunnish tribes; a neutral place of contact for negotiation.. Larach Duhnnan is in the territory claimed by Clan Feargan, but the foreign traffic passing through it makes it an excellent place for neutral discussion and trade.', 'Establecida como puesto avanzado en el Viejo Camino del Norte, T.E. 3; tomada por los dunlendinos, T.E. 275.. Centro urbano de las tribus dunlendinas dispersas; lugar neutral de contacto para negociar.. Larach Duhnnan está en territorio reclamado por el Clan Feargan, pero el tránsito extranjero que pasa por ella la vuelve un lugar excelente para la discusión y el comercio neutrales.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1225, 'Londaroth', 'ruins', 50, '100% Northman', 'Settled by Northmen around T.A. 900.. Portage river traffic around the falls at Lindal.. Only a small trading station, two mills, and an inn remain to serve the merchants who must portage their wares over the Falls of Celduin.', 'Poblada por Hombres del Norte alrededor de la T.E. 900.. Portear el tránsito fluvial alrededor de los saltos de Lindal.. Solo quedan una estación comercial pequeña, dos molinos y una posada para atender a los mercaderes que deben portear sus mercancías por encima de las Cataratas del Celduin.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1226, 'Lond Ernil', 'city', 10200, '90% Gondorian, 10% Mixed Mannish', 'Site of an Elvish watch-tower, built c. S.A. 3440; city planned and constructed by Dúnedain, c. T.A. 830.. Seat for the Prince of Dor-en-Ernil; harbors and building yards for Gondor''s navy; a mercantile center.. The city guards one of Gondor''s safest harbors, holding the realm''s largest fleet outside of Pelargir.', 'Sitio de una torre de vigilancia élfica, construida hacia la S.E. 3440; ciudad planificada y construida por los dúnedain, hacia la T.E. 830.. Asiento del Príncipe de Dor-en-Ernil; puertos y astilleros de la armada de Gondor; centro mercantil.. La ciudad guarda uno de los puertos más seguros de Gondor y alberga la flota más grande del reino fuera de Pelargir.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1227, 'Maethelburg', 'fortified town', 1200, '90% Northman, 5% Gondorian, 5% Other', 'Built by Northman settlers in roughly T.A. 1020.. A focal point for Northman political, social, and economic activity in the Nan Anduin.. Due to its central position, Maethelburg controls virtually all trade in the upper Anduin valley.', 'Construida por colonos de los Hombres del Norte hacia la T.E. 1020.. Foco de la actividad política, social y económica de los Hombres del Norte en el Nan Anduin.. Por su posición central, Maethelburg controla prácticamente todo el comercio del valle alto del Anduin.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1228, 'Marös', 'castle', 150, '30% Coastal People, 30% Corsair, 30% Haradan, 10% Black Númenórean', 'Marös occupies a promontory jutting into the Bay of Umbar — a Númenórean-built castle that has watched the bay''s traffic for over two thousand years. The sea breaks directly against its lower walls at high tide. Its current lord is Borathôr of Umbar; the mixed population of Coastal People, Corsairs and Haradan give the place a rough, polyglot character.', 'Marös ocupa un promontorio que se adentra en la Bahía de Umbar — un castillo de construcción numenóreana que lleva más de dos mil años vigilando el tránsito de la bahía. Con la marea alta, el mar rompe directamente contra sus muros bajos. Su señor actual es Borathôr de Umbar; su población mezclada de Gente de la Costa, Corsarios y haradanos le da al lugar un carácter tosco y políglota.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1229, 'Minas Anor', 'fortified town', 45000, '95% Gondorian, 5% Other', 'Founded by Anárion in S.A. 3320, rebuilt by Ostoher in T.A. 420.. Capital and royal residence of Gondor; location of a Palantír; the burial place of Gondor''s Kings.. Minas Anor is situated on a great spur of rock at the eastern tip of the White Mountains.', 'Fundada por Anárion en la S.E. 3320, reconstruida por Ostoher en la T.E. 420.. Capital y residencia real de Gondor; lugar de un palantír; sitio de enterramiento de los Reyes de Gondor.. Minas Anor está situada sobre un gran espolón de roca en el extremo oriental de las Montañas Blancas.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1230, 'Morannon', 'keep', 300, '100% Gondorian', 'Built by Sauron in the Second Age.. Control of passage into or out of Mordor.. During the Battle of Dagorlad, Sauron was forced to retreat to Barad-dûr when the forces of the Last Alliance broke the defenses here.', 'Construido por Sauron en la Segunda Edad.. Control del paso de entrada y de salida de Mordor.. Durante la Batalla de la Dagorlad, Sauron se vio forzado a retirarse a Barad-dûr cuando las fuerzas de la Última Alianza rompieron las defensas de aquí.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1231, 'Morthondost', 'fortified town', 650, '80% Gondorian, 20% Dunnish', 'Built by Dúnedain in the late Second Age, granted autonomy in T.A. 569.. Protection and administration of the Morthond Vale; exploitation of mineral resources.. Despite its proximity to the notorious Paths of the Dead, the Morthond Vale remains an important mining center for Gondor.', 'Construida por los dúnedain a fines de la Segunda Edad, recibió autonomía en la T.E. 569.. Protección y administración del Valle del Morthond; explotación de los recursos minerales.. A pesar de su cercanía al tristemente célebre Sendero de los Muertos, el Valle del Morthond sigue siendo un centro minero importante para Gondor.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1232, 'Mount Gundabad', 'fortified town', 14100, '78% Orcish, 20% Human Slave, 2% Troll', 'Orcs have occupied the Mountain since the Ruin of Beleriand.. The capital of the Orcish realm of Gundabad; a military base for operations in Rhovanion.. Mount Gundabad faces the peak Ügûlai across the Den Lóke, the gap between the Hithaeglir and the Ered Mithrin.', 'Los orcos han ocupado la Montaña desde la Ruina de Beleriand.. Capital del reino orco de Gundabad; base militar para las operaciones en Rhovanion.. El Monte Gundabad mira al pico Ügûlai al otro lado del Den Lóke, la brecha entre las Hithaeglir y las Ered Mithrin.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1233, 'Mulkan', 'village', 100, '100% Lossoth', 'Mulkan is a Lossoth settlement in the frozen wastes of Forochel, established as a seasonal base for hunting and gathering. In summer, it consists of hide tents and driftwood shelters around a communal fire; in winter, the Lossoth build their remarkable snow-and-ice houses, low-roofed and surprisingly warm inside. Strangers are mistrusted, but those who arrive with trade goods — iron, cloth, salt — may be received with cautious hospitality.', 'Mulkan es un asentamiento de los lossoth en los yermos helados de Forochel, establecido como base de temporada para la caza y la recolección. En verano consiste en carpas de cuero y refugios de madera de deriva alrededor de un fuego común; en invierno, los lossoth construyen sus notables casas de nieve y hielo, de techo bajo y sorprendentemente cálidas por dentro. De los forasteros se desconfía, pero a los que llegan con mercancías para intercambiar — hierro, tela, sal — se los puede recibir con una hospitalidad cautelosa.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1234, 'Nansret', 'village', 140, '100% Beffraen', 'Nansret is the only known village of the Beffraen, the Wild Men of the Rast Vorn. It is a rough settlement of bark shelters and timber lean-tos in the densest part of the forest, deliberately difficult to find. The Beffraen do not welcome outsiders; the village exists to support their hunting and gathering, and its location shifts with the seasons.', 'Nansret es la única aldea conocida de los beffraen, los Hombres Salvajes del Rast Vorn. Es un asentamiento tosco de refugios de corteza y cobertizos de madera en la parte más densa del bosque, difícil de encontrar a propósito. Los beffraen no reciben bien a los de fuera; la aldea existe para sostener su caza y su recolección, y su ubicación cambia con las estaciones.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1235, 'Nardol', 'watchtower', 85, '100% Gondorian', 'Built by Tarostar of Gondor to replace a wooden signal-platform on the site; completed in T.A. 516.. A link in Gondor''s communications network along the Old North Road.. Nardol is the third beacon in the chain.', 'Construida por Tarostar de Gondor para reemplazar una plataforma de señales de madera que había en el sitio; terminada en la T.E. 516.. Eslabón de la red de comunicaciones de Gondor a lo largo del Viejo Camino del Norte.. Nardol es la tercera almenara de la cadena.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1236, 'Nogothiant', 'bridge', 0, 'N/A', 'Built by the Naugrim of Moria before S.A. 1693.. Passage across the Anduin on the Great East Road.. The Nogothiant is crumbling, having lasted without maintenance for many centuries.', 'Construido por los Naugrim de Moria antes de la S.E. 1693.. Paso sobre el Anduin en el Gran Camino del Este.. El Nogothiant se está desmoronando, después de aguantar muchos siglos sin mantenimiento.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1237, 'Nogrod', 'ruins', 0, 'N/A', 'First delved in the Early First Age.. The mining, smelting, and working of precious metals found in the Ered Luin.. Nogrod was destroyed in the cataclysm that sank Beleriand beneath the ocean.', 'Cavada por primera vez a comienzos de la Primera Edad.. Extracción, fundición y trabajo de los metales preciosos que se encuentran en las Ered Luin.. Nogrod fue destruida en el cataclismo que hundió Beleriand bajo el océano.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1238, 'Ostigurth', 'fortified city', 2560, '40% Orc, 40% Haradan, 15% Easterling, 5% Troll', 'Built by Sauron in the mid-Second Age.. Control of traffic in the Den Nurn; the manufacture of finished products; small-scale trade.. Ostigurth is situated at the head of a small canyon on the southern edge of Gorgoroth.', 'Construida por Sauron a mediados de la Segunda Edad.. Control del tránsito en el Den Nurn; manufactura de productos terminados; comercio en pequeña escala.. Ostigurth está situada en la cabecera de un cañón pequeño, en el borde meridional de Gorgoroth.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1239, 'Paths Of The Dead', 'dungeon', 0, 'N/A', 'The Paths of the Dead are natural caverns beneath the White Mountains, connecting the vale of Dunharrow to the Morthond valley — once used as royal burial chambers by the Daen Coentis, last interred in T.A. 679. The entrance is known, but no living person willingly passes inside. Locals speak of cold air, a sense of invisible presences, and sounds that have no natural explanation. The broken Oath of the Dead men lingers here; the caverns are considered one of the most accursed places in Gondor.', 'El Sendero de los Muertos son cavernas naturales bajo las Montañas Blancas, que conectan el valle del Sagrario con el valle del Morthond — usadas en su momento como cámaras funerarias reales por los Daen Coentis, con el último enterramiento en la T.E. 679. La entrada es conocida, pero ninguna persona viva pasa dentro por su voluntad. Los lugareños hablan de aire frío, de una sensación de presencias invisibles y de sonidos que no tienen explicación natural. El juramento roto de los Muertos sigue pesando aquí; las cavernas se consideran uno de los lugares más maldecidos de Gondor.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1240, 'Pellardur', 'castle', 180, '50% Haradan, 30% Coastal People, 15% Corsair, 5% Black Númenórean', 'Built by the Captains of Umbar, circa T.A. 750.. Defense of southern land approaches to the city of Umbar; administration of surrounding farmlands.. Pellardur is situated close to the City of Umbar and rests in fairly fertile agricultural lands.', 'Construido por los Capitanes de Umbar hacia la T.E. 750.. Defensa de los accesos terrestres meridionales a la ciudad de Umbar; administración de las tierras de labranza de alrededor.. Pellardur está cerca de la Ciudad de Umbar y se asienta en tierras agrícolas bastante fértiles.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1241, 'Riavod', 'fortified town', 1060, '100% Easterling', 'Settled by Easterlings, circa T.A. 1408.. A trading base for expeditions up the Celduin; a port on the Sea of Rhûn.. Although ruled by a Sagath prince, the Dorwinrim use the town as their main trading base with the lands of Western Endor.', 'Poblada por Hombres del Este hacia la T.E. 1408.. Base comercial para las expediciones que remontan el Celduin; puerto en el Mar de Rhûn.. Aunque la gobierna un príncipe sagath, los dorwinrim usan el pueblo como su base principal de comercio con las tierras del Endor Occidental.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1242, 'Romenost', 'village', 95, '100% Gondorian', 'Romenost is a Gondorian waystation on the Men Romen, built by the Eastern Army to defend the road against incursions from the east. Its stone walls and barracks are practical rather than impressive; the garrison is small and the surrounding steppe is empty and windswept. Travellers on the Men Romen are glad to see it — it is the only shelter for many miles.', 'Romenost es una posta gondoriana en el Men Romen, construida por el Ejército del Este para defender el camino de las incursiones que vienen del este. Sus muros de piedra y sus barracas son prácticos antes que imponentes; la guarnición es pequeña y la estepa de alrededor está vacía y batida por el viento. Los viajeros del Men Romen se alegran de verla — es el único refugio en muchas millas.');
INSERT INTO locations (id, name, location_type, inhabitants, description, description_es) VALUES (1243, 'Saarkaana', 'fortress', '?', 'Possibly Númenórean (?).. Unknown, possibly ceremonial.. Saarkaana is an Umbarean fortress in the parched Talath Naur, situated near the ruins of a Second Age structure.', 'Posiblemente numenóreana (?).. Desconocido, posiblemente ceremonial.. Saarkaana es una fortaleza umbareana en el reseco Talath Naur, situada cerca de las ruinas de una estructura de la Segunda Edad.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1244, 'Sook Asni', 'town', 680, '90% Haradan, 10% Corsair', 'Settled by Haradrim, circa T.A. 1400.. Fishing; ship building and repair.. The lacquered tableware created by the craftsmen of Sook Asni is much in demand among the nobility of Umbar.', 'Poblada por los haradrim hacia la T.E. 1400.. Pesca; construcción y reparación de naves.. La vajilla laqueada que hacen los artesanos de Sook Asni es muy solicitada entre la nobleza de Umbar.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1245, 'Spathlin', 'town', 820, '90% Gondorian, 10% Dunnish', 'Settled by Gondor, circa T.A. 410.. Trading center at the confluence of the Rivers Ciril and Ringló; a collecting point for local farms.. Spathlin controls much of the river traffic to northern Lamedon, but it suffers nonetheless from isolation.', 'Poblada por Gondor hacia la T.E. 410.. Centro de comercio en la confluencia de los ríos Ciril y Ringló; punto de acopio de las granjas del lugar.. Spathlin controla buena parte del tránsito fluvial hacia el norte de Lamedon, pero sufre de todos modos por su aislamiento.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1246, 'Staddle', 'village', 90, '70% Stoor Hobbit, 30% Bree-man', 'Settled by Bree-land farmers, circa T.A. 1250.. Agriculture.. Staddle is just a short walk from Bree, and it relies upon its larger neighbor for most of the services a small agrarian community cannot provide for itself.', 'Poblada por granjeros de las Tierras de Bree hacia la T.E. 1250.. Agricultura.. Staddle queda a un paso de Bree y depende de su vecina más grande para casi todos los servicios que una comunidad agraria pequeña no puede darse a sí misma.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1247, 'Strayhold', 'fortified town', 900, '85% Northman, 15% Mixed Mannish', 'Settled by Gramuz outcasts, circa T.A. 1340.. Trade with Gramuz and Gondor; a local economic focal point.. Strayhold rests near the eastern edge of Mirkwood, situated in a deep gorge near the edge of the Talath Harroch.', 'Poblada por proscritos gramuz hacia la T.E. 1340.. Comercio con los gramuz y con Gondor; foco económico local.. Strayhold se asienta cerca del borde oriental del Bosque Negro, en una garganta profunda junto al borde del Talath Harroch.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1248, 'Sudúri', 'fortified city', 6000, '95% Dunnish, 5% Cardolani', 'Founded by the adventurer Gordaigh in T.A. 1503 on site of a Dúnadan fortress.. Administrative center for the Kingdom of Saralainn; a meeting place for Dunnish tribes.. The town was originally built by Númenóreans, but now almost all of the inhabitants are Dunnish in origin.', 'Fundada por el aventurero Gordaigh en la T.E. 1503 sobre el sitio de una fortaleza dúnadan.. Centro administrativo del Reino de Saralainn; lugar de encuentro de las tribus dunlendinas.. El pueblo lo construyeron en origen los numenóreanos, pero hoy casi todos sus habitantes son de origen dunlendino.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1249, 'Thalion', 'palace', 45, '60% Cardolani, 40% Eriadoran', 'Built by Tarcil of Arnor in T.A. 514.. The seat of House of Dol Tinare.. Thalion is in a sorry state of repair.', 'Construido por Tarcil de Arnor en la T.E. 514.. Asiento de la Casa de Dol Tinare.. Thalion está en un estado de conservación lamentable.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1250, 'Tharagrond', 'fortress', 65, '100% Black Númenórean', 'Founded by Númenórean colonists c. S.A. 2300.. Defense of the lands of the Principality of Tharagrond; local administration.. Tharagrond is a small and isolated fief, but it carries its autonomy proudly.', 'Fundada por colonos numenóreanos hacia la S.E. 2300.. Defensa de las tierras del Principado de Tharagrond; administración local.. Tharagrond es un feudo pequeño y aislado, pero lleva su autonomía con orgullo.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1251, 'Thorontir', 'fortress', 1350, '80% Gondorian, 20% Mixed Mannish', 'Founded by Gondor, circa T.A. 500.. A center for regional administration; a garrison for Gondor''s Eastern Army.. The fortress is located just off the Men Romen, several miles east of the town of Thorontir.', 'Fundada por Gondor hacia la T.E. 500.. Centro de administración regional; guarnición del Ejército del Este de Gondor.. La fortaleza está apenas apartada del Men Romen, varias millas al este del pueblo de Thorontir.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1252, 'Tir Anduin', 'castle', 2500, '90% Gondorian, 10% Northman', 'Settled by Gondorians, circa T.A. 1402; granted royal charter in T.A. 1560.. Northernmost significant Gondorian trading outpost; location of a ferry across the Anduin.. The ferry of Tir Anduin and the nearby ford at the Undeeps are the safest crossings of the Anduin between Osgiliath and the Old Ford.', 'Poblado por gondorianos hacia la T.E. 1402; recibió fuero real en la T.E. 1560.. Puesto comercial gondoriano de importancia más septentrional; lugar de una balsa que cruza el Anduin.. La balsa de Tir Anduin y el vado cercano de los Bajos son los cruces más seguros del Anduin entre Osgiliath y el Viejo Vado.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1253, 'Tir Limlight', 'fortified town', 156, '60% Gondorian, 40% Northman', 'Tir Limlight marks the effective northern limit of Gondorian authority on the Anduin, guarding one of the few crossings at the Undeeps. Founded by Gondorian merchants, it has grown into a walled town of mixed Gondorian and Northman character — stone houses and timber warehouses, the smell of river trade, and the constant awareness of the northern wilderness beyond the walls. The garrison here watches for threats from Rhovanion as much as it watches the river traffic.', 'Tir Limlight marca el límite efectivo de la autoridad gondoriana en el norte del Anduin, y guarda uno de los pocos cruces de los Bajos. Fundada por mercaderes gondorianos, ha crecido hasta ser un pueblo amurallado de carácter mezclado, gondoriano y de los Hombres del Norte — casas de piedra y depósitos de madera, el olor del comercio fluvial, y la conciencia constante del yermo septentrional que hay más allá de los muros. La guarnición de aquí vigila tanto las amenazas que vienen de Rhovanion como el tránsito del río.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1254, 'Tir Nindor', 'castle', 60, '90% Gondorian, 10% Mixed Mannish', 'Constructed by Gondor around T.A. 410.. Guarding the only safe and dry passage through the Dead Marshes.. Tir Nindor is a strategic castle guarding the passage through the Dead Marshes.', 'Construido por Gondor alrededor de la T.E. 410.. Guardar el único paso seguro y seco a través de las Ciénagas de los Muertos.. Tir Nindor es un castillo estratégico que guarda el paso por las Ciénagas de los Muertos.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1255, 'Towers Of The Teeth', 'watchtower', 340, '100% Gondorian', 'The Towers of the Teeth — Narchost and Carchost — flank the Cirith Gorgor on either side of the Morannon, built by Gondor in the first year of the Third Age to observe all traffic attempting to enter or leave Mordor. They are forbidding structures of black stone on bare crags; their garrison peers down at the ash-plain of Udûn below and reports any movement. No one passes into Mordor without being seen.', 'Las Torres de los Dientes — Narchost y Carchost — flanquean el Cirith Gorgor a ambos lados del Morannon, construidas por Gondor en el primer año de la Tercera Edad para observar todo el tránsito que intente entrar o salir de Mordor. Son estructuras adustas de piedra negra sobre riscos desnudos; su guarnición mira hacia abajo, a la llanura de ceniza de Udûn, e informa de cualquier movimiento. Nadie entra en Mordor sin ser visto.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1256, 'Tuckburrow', 'village', 320, '90% Fallohide, 10% Stoor & Harfoot', 'Settled by Hobbits during the migration to the Shire, T.A. 1601-1610.. Clan dwelling; agriculture.. The village is located in the Green-hill country of the Westfarthing of the Shire.', 'Poblada por hobbits durante la migración a la Comarca, T.E. 1601-1610.. Morada de clan; agricultura.. La aldea está en el País de las Colinas Verdes, en la Cuaderna del Oeste de la Comarca.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1257, 'Umbar', 'fortified town', 60000, '35% Coastal People, 30% Corsair, 25% Haradan, 10% Black Númenórean', 'Founded by Tar-Atanamir of Númenor in S.A. 2280, expanded several times.. Capital of Umbar; economic and political center; ship building and repair.. A great monument raised by the Númenórean King Ar-Pharazôn to commemorate his victory over Sauron guards the entrance to the harbor.', 'Fundada por Tar-Atanamir de Númenor en la S.E. 2280, ampliada varias veces.. Capital de Umbar; centro económico y político; construcción y reparación de naves.. Un gran monumento levantado por el rey numenóreano Ar-Pharazôn para conmemorar su victoria sobre Sauron guarda la entrada del puerto.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1258, 'Vamag', 'ruins', 0, 'N/A', 'Vamag is a coastal ruin of the mid-Second Age, said to have served as a retreat for Adûnaphel — believed by some to be one of the Nazgûl. The local Coastal Peoples refuse to approach it, declaring the site haunted. The walls stand dark and salt-worn above the cliffs, and the silence around them feels heavier than it should.', 'Vamag es una ruina costera de mediados de la Segunda Edad, de la que se dice que sirvió de retiro a Adûnaphel — a quien algunos creen uno de los Nazgûl. La Gente de la Costa del lugar se niega a acercarse y declara el sitio encantado. Los muros se alzan oscuros y gastados por la sal sobre los acantilados, y el silencio de alrededor se siente más pesado de lo que debería.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1259, 'Warfinger', 'village', 54, '100% Gondorian', 'Built by the Gondorian Eastern Army around T.A. 1428.. A waystation along the south fork of the Men Romen; a defensive point against invasion from the East.. The small garrison at Warfinger is situated far away from the authority of the Regent in Thorontir.', 'Construida por el Ejército del Este de Gondor alrededor de la T.E. 1428.. Posta a lo largo del ramal sur del Men Romen; punto defensivo contra una invasión desde el Este.. La guarnición pequeña de Warfinger está muy lejos de la autoridad del Regente en Thorontir.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1260, 'Woodmen-town', 'village', 200, '100% Woodman (Northman)', 'Settled permanently around T.A. 1580.. A gathering place for the Woodman clans; the home of the Althyn; the site of an annual fair.. Woodmen-town is built upon great platforms in the trees in the Elvish manner, for the Woodmen are on friendly terms with the Elves of the Forest.', 'Poblada de forma permanente alrededor de la T.E. 1580.. Lugar de reunión de los clanes de los Hombres de los Bosques; hogar del Althyn; sitio de una feria anual.. Woodmen-town está construida sobre grandes plataformas en los árboles, a la manera élfica, porque los Hombres de los Bosques están en buenos términos con los Elfos del Bosque.');
INSERT INTO locations (id, name, location_type, population, inhabitants, description, description_es) VALUES (1261, 'Wraecaburg', 'fortified town', 340, '80% Northman, 20% Mixed Mannish', 'Settled by Northmen around T.A. 1000.. Agriculture; a center for trade in the northern Anduin Vales.. Though not directly under the sway of the Witch-king, Wraecaburg suffers from frequent raids, despair, and a large population of shady characters from beyond Rhovanion.', 'Poblada por Hombres del Norte alrededor de la T.E. 1000.. Agricultura; centro de comercio en los Valles del norte del Anduin.. Aunque no está directamente bajo el dominio del Rey Brujo, Wraecaburg sufre incursiones frecuentes, desesperanza y una población numerosa de gente turbia venida de más allá de Rhovanion.');